quests[26238] = { id = 26238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilden Zwerge", description = "Die Horde hat für uns Bruchhauer viel getan und Trittbrettfahrer sind wir sicherlich nicht. Die anderen Waldtrollstämme wurden zurückgedrängt und wir sind dabei, im Namen der Horde neue Ländereien zu sichern.\n\nJetzt sind uns aber die Wildhammerzwerge in den Weg gekommen. Wenn sie Krieg wollen, so werden sie Krieg bekommen... und ich habe nicht vor, einen Krieg gegen jemanden zu verlieren, der nur halb so groß ist wie ich.\n\nGeht los und tötet ein paar Zwerge für mich.", sourceObjective = "Tötet 10 Krieger der Wildhämmer oder Schamanen der Wildhämmer.", completion = "Das wird den Wildhammerzwergen klar machen, dass sie auf unseren Ländereien nichts zu suchen haben!\n\nDie verrückten Zwerge hätten einfach in den Bergen bleiben sollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26240] = { id = 26240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Takt", description = "Unsere Krieger kämpfen hart, um die üblen Wildhammerzwerge auszuschalten, damit wir hier im Dorf wieder in Sicherheit sind. Wir müssen tun, was wir können, um sie zu unterstützen.\n\nEs gibt etwas, das bei jedem Troll seine besten Kampfkünste herauskommen lässt: der hämmernde Rhythmus der Trommeln lässt sie fester zuschlagen und ruft die Geister dazu auf, über die Krieger zu wachen. Nehmt meine Trommeln mit auf das Schlachtfeld. Spielt sie für unsere Krieger und zeigt den Wildhammerzwergen, wem dieses Land gehört!", sourceObjective = "Spielt die Kriegstrommeln der Bruchhauer für 6 Krieger der Bruchhauer.", completion = "Es macht einen großen Unterschied, nicht wahr? Das wird diesen Zwergen eine Lektion erteilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26241] = { id = 26241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfalleintopf", description = "Hallo, <mein Lieber/meine Liebe>. Willkommen in unserem Zuhause. Hmm, Ihr seht aber nicht aus, als ob Ihr obdachlos wärt. Seid Ihr hier, um uns zu helfen? Wenn das so ist, dann kommt Ihr gerade rechtzeitig! Ich plane ein Abendessen für die Kinder und ich brauche ein paar einfache Zutaten.\n\nWenn Ihr mir ein paar Okraschoten, Geiferzahnflanken und sehniges Fleischreißerfleisch bringt, kann ich meinen berühmten Westfalleintopf zubereiten. Ihr könnt all diese Zutaten in der Nähe unserer Farm finden. Nehmt Euch nur vor den Erntebehütern in Acht. Das sind gnadenlose Vernichtungsmaschinen.", sourceObjective = "Sammelt 6 Okraschoten, 6 Stück sehniges Fleischreißerfleisch und 6 Geiferzahnflanken.", progress = "Das Essen ist fertig, sobald ich alle Zutaten habe. Beeilt Euch!", completion = "Seid gesegnet, mein Lieber. Diese armen Waisen haben schon seit Tagen keine warme Mahlzeit mehr bekommen.\n\nEs sieht so aus, als hätten wir genug übrig, um noch viele weitere Obdachlose Westfalls zu versorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26243] = { id = 26243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weltensäule", description = "Die Säule in diesem Zimmer stützt mehr als nur den Tempel der Erde.\n\nDiese gesamte Existenzebene stürzt bald in unsere Welt, wenn wir sie nicht wieder aufbauen.\n\nEs ist schon bald Zeit zu handeln. {name}. Aber zunächst müsst Ihr Euch anhören, was ich Euch zu sagen habe.", sourceObjective = "Befragt Maruut Steinbinder zur Weltensäule.", sourceObjectiveStatus = "unverified-source-field" }
quests[26244] = { id = 26244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde nimmt sich alles", description = "Wir befinden uns auf der Ebene der Erde, {name}. Nach und nach wird das Land alles in sich aufnehmen.\n\nDie Sturmfuror wird bald nichts als Staub sein. Dann können wir keine Erkenntnisse aus ihren Resten mehr gewinnen.\n\nGeht und vernichtet die Elementare, die das Schiff auseinandernehmen. Wir zögern das Unvermeidliche nur heraus, aber wir müssen uns etwas Zeit verschaffen, wenn wir alle Teile der Weltensäule finden wollen.", sourceObjective = "Vernichtet 5 Tiefensteinelementare.", completion = "Ihr habt getan, was notwendig war, {name}. Ich merke schon, dass Ihr genau die Sorte {class} seid, mit der es sich gut leben lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26245] = { id = 26245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftschiff am Boden", description = "Der Abschlussstein wurde in einem Luftschiff der Horde namens Sturmfuror transportiert.\n\nDas Luftschiff ist südlich von hier abgestürzt. Laut unseren Untersuchungen befindet sich der Abschlussstein nicht mehr an Bord.\n\nDurchsucht das Schiff nach Hinweisen darauf, was passiert sein könnte.", sourceObjective = "Sucht im Wrack der Sturmfuror in Tiefenheim nach Hinweisen.", completion = "Die Hinweise deuten auf das Offensichtliche. Vielleicht zu offensichtlich…", sourceObjectiveStatus = "unverified-source-field" }
quests[26246] = { id = 26246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Logbuch des Kapitäns", description = "<Ihr blättert zum letzten, abgebrochenen Eintrag.>\n\n… nähern uns dem Tempel der Erde bei 300 Knoten und beginnen die Landemanöver gemäß der neuen Route. Wir haben ein Niedrigdrucksystem im Norden notiert und ziehen jetzt unser…\n\nBLUT UND DONNER! ABSCHAUM DER ALLIANZ NÄHERT SICH!", sourceObjective = "Bringt das Logbuch des Kapitäns zu Maruut Steinbinder beim Tempel der Erde in Tiefenheim.", completion = "Warum sollte die Allianz die Horde angreifen, wenn sie uns gerade ein Stück der Weltensäule bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26247] = { id = 26247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatie hat Vorrang", description = "Der Irdene Ring ist eine neutrale Gemeinschaft, {name}. Wir können uns im Krieg zwischen der Horde und der Allianz auf keine Seite schlagen.\n\nSeht Euch um. Wir haben Mitglieder verschiedenster Herkunft. Wenn wir die Spannungen zwischen den einzelnen Völkern über unser Ziel stellen würden, wäre unsere Mission in Gefahr. Lasst uns dies also vertraulich behandeln, bis wir weitere Informationen gesammelt haben.\n\nWir dürfen keine voreiligen Schlüsse ziehen. Ich schicke Euch zusammen mit einem unserer neuen Mitglieder los, um das Kanonenboot der Allianz zu suchen.\n\nFindet heraus, was Ihr könnt, ohne uns in den Konflikt hineinzuziehen.", sourceObjective = "Trefft Euch mit Sturmruferin Mylra auf dem Kanonenboot der Allianz.", completion = "He, {name}! Man hat mir gesagt, dass ich bald Gesellschaft bekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[26248] = { id = 26248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All unsere Freunde sind tot", description = "Irgendwas ist hier nicht in Ordnung, {name}.\n\nDie Besatzung des Schiffes wurde erschlagen. Und doch sehe ich kein vergossenes Blut oder Schäden am Schiffskörper.\n\nDas war nicht das Werk der Horde.\n\nWir müssen mit den Geistern der Toten sprechen, um Antworten zu finden. Sie haben diese Welt noch nicht verlassen.\n\nNehmt dieses Totem und stellt es neben den Leichnamen der Gefallenen auf. Dann könnt Ihr ihre letzten Gedanken hören.\n\nAber seid vorsichtig! Es ist schwer zu sagen, wie die Geister der Toten auf unsere Nachforschungen reagieren werden.", sourceObjective = "Benutzt das Geistertotem in der Nähe von 6 Leichnamen erschlagener Besatzungsmitglieder.", progress = "Die Geister haben immer eine Geschichte für die zu erzählen, die zuhören.", completion = "Es war nur eine Frage der Zeit, bis wir auf Mitglieder des Schattenhammers trafen, {name}. Wenn sie hinter all dem stecken, dann haben sie sicher auch das Fragment der Weltensäule in ihrer Gewalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26249] = { id = 26249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kajüte des Admirals", description = "Möglicherweise finden wir in der Kajüte des Admirals weitere Spuren. Sie befindet sich direkt unter uns.\n\nSchaut, ob es dort unten irgendwelche Überlebenden oder Informationen gibt, die uns nähere Hinweise zum Verbleib des Weltensäulenfragments geben können. Seid vorsichtig, {name}. Wer auch immer die Besatzung auf dem Gewissen hat, könnte noch dort sein.", sourceObjective = "Haltet in der Kajüte des Admirals auf dem Kanonenboot der Allianz nach Hinweisen Ausschau.", completion = "Dieses Schiff ist voller Ratten…", sourceObjectiveStatus = "unverified-source-field" }
quests[26250] = { id = 26250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ach, einen Gefangenen sollten wir doch nehmen", description = "Es ist nicht zu spät, {name}. Die Kultisten sind bestimmt immer noch hier.\n\nGeht unter Deck, findet heraus, wer das Sagen hat und unterwerft ihn.\n\nWir werden Antworten auf unsere Fragen bekommen, auf die eine oder andere Art.", sourceObjective = "Unterwerft Mor'norokk den Hasserfüllten auf dem Kanonenboot der Allianz in Tiefenheim.", progress = "Grüße, {name}.", completion = "Uff, das war ein schwerer Brocken! Er hat meinem armen Greifen fast den Rücken gebrochen!\n\nSeid Ihr bereit, den Oger zu befragen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26251] = { id = 26251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht keine Gefangenen", description = "Sieht aus, als wäre der Schattenhammer noch immer auf dem Schiff. Geht unter Deck und macht kurzen Prozess mit ihnen.\n\nSeid vorsichtig, {name}. Ich habe das Gefühl, dass sie nicht hier sind, um ihr spirituelles Gleichgewicht zu finden, wenn Ihr versteht, was ich meine.", sourceObjective = "Tötet 6 Zwielichtsaboteure.", progress = "Habt Ihr es erledigt, {name}?", completion = "Gut gemacht, {name}. Der Schattenhammer ist ein Übel, das wir an allen Ecken und Enden bekämpfen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26252] = { id = 26252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz des Behüters", description = "Ihr habt etwas gefunden, das offenbar das Herz eines Erntebehüters ist.\n\nDem Geräusch nach zu urteilen, das von dem Gerät ausgeht, ist es noch immer voll funktionsfähig. Vielleicht solltet Ihr es zu Bauer Saldean zurückbringen.", sourceObjective = "Bringt das Herz eines Erntebehüters zurück zu Bauer Saldean auf Saldeans Hof.", progress = "Was habt Ihr denn da, {name}?", completion = "Ist das etwa... Ist das das Herz eines der Behüter? Ich habe Geschichten darüber gehört, wie man eins von diesen Dingern dazu benutzen kann, einen Behüter für den Eigengebrauch anzutreiben. Natürlich bin ich selbst nicht mehr in der Verfassung, solche Dinge selbst zu versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26254] = { id = 26254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erklärt Euch!", description = "Springt auf, {name}. Mal sehen, was Herr Ogervisage hier zu seiner Verteidigung zu sagen hat.\n\nNur keine Scheu. Sturmschnabel hat erst ein paar Mal einen Reiter fallenlassen.", sourceObjective = "Springt auf Sturmschnabel und beobachtet Mor'norokks Befragung.", progress = "Ja, {name}?", completion = "Wir haben unsere Antworten, {name}. Melden wir uns zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26255] = { id = 26255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Tempel der Erde", description = "Ihr müsst die anderen am Tempel informieren. Wahrscheinlich bringen sie das Fragment gerade an einen sicheren Ort.\n\nBerichtet Maruut, was Ihr wisst. Ich werde diesen Zwielichtrat in der Zwischenzeit unter die Lupe nehmen.", sourceObjective = "Sprecht mit Maruut Steinbinder im Tempel der Erde in Tiefenheim.", completion = "Wir müssen Eure Erkenntnisse genauer untersuchen, aber wir dürfen die Spur des Fragments nicht verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26256] = { id = 26256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Blutformer bluten", description = "Der Schattenhammer wirkt hier bösartige Magie, {name}. Sie beleben die Überreste von Todesschwinges Blut und erfüllen sie mit Energie. Statt auszutrocknen und zu verschwinden gedeiht es und wird immer mehr.\n\nErledigt einen ihrer Blutformer und presst Informationen aus ihm heraus, wo wir diesen \"Schmiedemeister\" finden.", sourceObjective = "Besorgt Euch die Schattenhammerbefehle von einem der Zwielichtblutformer in Todesschwinges Sturz.", progress = "Wir müssen uns beeilen, wenn wir die Weltensäule wieder errichten möchten, {name}.", completion = "Sie halten hier Sklaven? Wir sollten sie ohne Frage befreien, aber vielleicht können sie uns auch dabei helfen, den Schmiedemeister zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26257] = { id = 26257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es lebt!", description = "Soweit ich gehört habe, müsst Ihr nur einen geeigneten Erntegolem finden und rein mit dem Herzen. Sobald das erledigt ist, solltet Ihr die volle Kontrolle über das Geschöpf haben.\n\nIch glaube, es gibt ein ganzes Feld mit überladenen Erntegolems westlich von hier auf dem Hof der Molsens. Haltet nach den Lichtbögen Ausschau.\n\nFalls Ihr einen zum Laufen bringen könnt, benutzt den Golem, um die aufgeladenen Ernteschnitter auf dem alten Molsenhof zu zerstören. Die Monster dort sind viel zerstörerischer als die auf unserem Hof hier.", sourceObjective = "Wendet das Herz eines Erntebehüters auf einen überladenen Erntegolem an und benutzt dann den überladenen Erntegolem, um 25 aufgeladene Ernteschnitter zu töten.", completion = "Es hat tatsächlich funktioniert? Das ist unglaublich, {name}. Hoffentlich löst das das Problem mit den Erntegolems hier in Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[26258] = { id = 26258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesschwinges Sturz", description = "Dass der Schattenhammer etwas mit dem Verschwinden der Weltensäule zu tun hat, ist nicht verwunderlich. Hoffentlich können wir schnell genug handeln, um sie zurückzuholen.\n\n<Maruut legt seine Hand auf Eure Schulter.>\n\nIch habe ein spirituelles Band zu Euch gewirkt. Wir sollten miteinander kommunizieren können, solange Ihr in Tiefenheim seid.\n\nGeht zu Todesschwinges Sturz im Südosten und untersucht, was der Schattenhammer vorhat.", sourceObjective = "Geht zu Todesschwinges Sturz in Tiefenheim.", completion = "Das muss der Ort sein, an den sie das Säulenfragment gebracht haben. Lasst uns einen genaueren Blick darauf werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26259] = { id = 26259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Erdenwächters", description = "Als Todesschwinge nach Tiefenheim geflohen ist, war seine Verderbtheit stark ausgeprägt, aber vielleicht noch nicht vollständig.\n\nDie Kultisten in Todesschwinges Sturz ernten sein übrig gebliebenes verderbtes Blut und formen es in lebende Wesen, um deren Energie aufzunehmen.\n\nWas, wenn eine kleine Spur der Essenz des Erdenwächters geblieben ist? Schließlich war Neltharion der Aspekt der Erde, bevor er zum Aspekt des Todes wurde.\n\nSammelt Proben des lebenden Blutes, das die Kultisten erschaffen, und wir überprüfen, ob eine Spur des Erdenwächters darin verblieben ist.", sourceObjective = "Sammelt 5 Proben des Blutes von Neltharion vom lebenden Blut in Todesschwinges Sturz.", progress = "Ihr seid zurück, {name}. Habt Ihr das Blut bekommen?", completion = "In diesem Blut schlummert immer noch viel Macht, {name}. Ich kann sie sogar jetzt spüren.\n\nUnd dennoch spüre ich auch viel Verderbtheit. Ich bin mir nicht sicher, ob wir daraus die Essenz des Erdenwächters gewinnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26260] = { id = 26260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Logbuch des Schmiedemeisters", description = "Geht zu dem Turm, von dem der Sklave gesprochen hat. Ihr solltet ihn am nordöstlichen Ende des Lagers finden.\n\nWenn wir schnell genug handeln, können wir vielleicht das Treffen des Schmiedemeisters belauschen.", sourceObjective = "Findet das Logbuch des Schmiedemeisters in Todesschwinges Sturz in Tiefenheim.", completion = "Ein Eintrag berichtet von einem anstehenden Treffen in den Oberen Silbermarschen.\n\nDer Schmiedemeister muss sich dort aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26261] = { id = 26261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragt die Sklaven", description = "Laut den Befehlen, die Ihr gefunden habt, soll sich in einem Zelt am südöstlichen Ende von Todesschwinges Sturz ein Schlüssel befinden.\n\nBesorgt ihn Euch und befreit die Sklaven im Steinbruch im Süden.", sourceObjective = "Besorgt Euch den Schlüssel des Zwielichtsklavenhändlers und befreit 6 versklavte Minenarbeiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[26263] = { id = 26263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thornar Donnerknall", description = "Wir haben versucht, den Kommandanten der eindringenden Wildhammerzwerge auszuschalten - bisher jedoch ohne Erfolg.\n\nThornar Donnerknall befindet sich in der Sicherheit seines Kommandopostens und man kann nur seine Stimme hören, die die Zwerge auf dem Schlachtfeld donnernd antreibt. Wir glauben, dass wir ihn zum Schweigen bringen müssen.\n\nErledigt Thornar und wir werden mit dem Rest seiner Truppen problemlos fertig werden.", sourceObjective = "Tötet Thornar Donnerknall.", completion = "Gut gemacht, Mann. Ihr seid ein echter Held der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26264] = { id = 26264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zurückgelassenen", description = "Die meisten von uns haben die kranken und irren Gnome gesehen, die unter den Folgen der Gifte und der Strahlung in Gnomeregan leiden. Ihr Niedergang ist erst vollendet, wenn aus ihnen hirnlose, aber größtenteils harmlose Pfützen aus toxischem Schlick werden.\n\nMeine Nachforschungen lassen darauf schließen, dass wir sie selbst in diesem Zustand noch retten können. Reist zum Toxischen Flugplatz im Süden, unterwerft den toxischen Schlick, von dem ich Euch erzählt habe, und bringt mir den Besitz der Gnome, die sie einst waren.", sourceObjective = "Beschafft 6 zurückerlangte Besitztümer von toxischem Schlick auf dem Toxischen Flugplatz.", progress = "Konntet Ihr den Besitz einiger bestrahlter Gnome bergen?", completion = "Ich kann es kaum erwarten, diese neue Technologie auszuprobieren! Zahllose Gnome sind der Strahlung zum Opfer gefallen. Es wird Zeit, den Prozess umzukehren!", sourceObjectiveStatus = "unverified-source-field" }
quests[26265] = { id = 26265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt die Verseuchung", description = "Tock Flinkspross hat eine verrückte Theorie. Er glaubt, bei den toxischen Schlickpfützen handele es sich um die Überreste von Gnomen, deshalb haben meine Männer Befehl, sie erst einmal nicht anzugreifen.\n\nAllerdings wimmelt es auf dem Toxischen Flugplatz südlich von hier von lebenden Verseuchungen. Dabei handelt es sich um Elementare, die aus verseuchtem Wasser und anderen toxischen Materialien bestehen. Wenn wir uns nicht um sie kümmern, werden sie die Stadt überrennen. Würdet Ihr uns helfen, sie loszuwerden?", sourceObjective = "Zerstört 6 lebende Verseuchungen auf dem Toxischen Flugplatz.", completion = "Welch eine Erleichterung! Ich danke Euch für Eure Hilfe. Ich hoffe, dass Dingsda, an dem Ingenieur Schleiffunke gearbeitet hat, hilft uns, den Flugplatz endgültig zu säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26266] = { id = 26266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung für das Volk", description = "Vor ungefähr vier Jahren stolperte ein kleines Mädchen mitten in der Nacht in unser Farmhaus und brach zusammen. Niemand kannte sie. Das arme, kleine Ding hatte keine Erinnerung daran, wer sie sein könnte oder woher sie kam - wahrlich eine verirrte Seele.\n\nBald darauf adoptierten wir die Kleine und nannten sie Hope - denn für uns bedeutete sie Hoffnung.\n\nJetzt ist sie eine junge Dame und kümmert sich um die Obdach- und Mittellosen von Westfall. Bringt meinen Westfalleintopf zu ihr zur Späherkuppe südlich von hier.", sourceObjective = "Bringt den Westfalleintopf zu Hope Saldean an der Späherkuppe.", progress = "Guten Tag werter Herr. Wie kann ich Euch dienen?", completion = "Ich rieche Westfalleintopf! Hat Mutter Euch geschickt!?", sourceObjectiveStatus = "unverified-source-field" }
quests[26267] = { id = 26267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lauerfels aufräumen", description = "Vor vielen Jahren hatte die Horde eine Station tief im Lauerfels. Sie steht seitdem leer aber es ist immer noch eine gute Stellung, die wir wieder einnehmen sollten.\n\nDas Problem ist dass die Station voll von Schlamm ist inzwischen. Schlamme sind üble Dinger... kopflos, ätzend, und gefährlich, da sie alles essen, was ihnen in den Weg kommt.\n\nIch brauche jemand, der mutig genug ist, um sich zum Lauerfels zu begeben und die Schlamme zu beseitigen. Seid Ihr mutig genug, {name}?", sourceObjective = "Tötet 10 jadegrüne Schlamme.", completion = "Gut, dass Ihr wieder hier seid... und sogar mit allen Gliedmaßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26268] = { id = 26268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauerfelsvorräte", description = "Ich war im Zweiten Krieg in Lauerfels stationiert. Ich war jung, noch Jahre davon entfernt, meine Partnerin kennenzulernen, und erinner mich noch gut an das Chaos, das ausbrach, als die Allianz uns angriff. Wir sind mit den Orcs geflohen und haben keine Zeit damit verschwendet, unsere Besitztümer zu packen.\n\nWir haben alles hinter uns gelassen. In Lauerfels sind noch immer viele unserer alten Vorräte. Wir könnten sie hier im Dorf gut gebrauchen... und vor allem sollten die Wildhammerzwerge sie nicht in ihre dreckigen Hände bekommen.", sourceObjective = "Sammelt 5 schlammbedeckte Vorratskisten.", progress = "Wie viele Kisten habt Ihr gefunden?", completion = "Sie sind unversehrt! In diesen Kisten sind viele Erinnerungen festgehalten. Mal sehen, was wir hier haben...\n\nBananenbrot! Und es ist noch gut!\n\nHier, also ich nehme das hier, Ihr könnt Euch auch etwas aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26269] = { id = 26269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grünen Hügel des Schlingendorntals", description = "Eine Seite! Ich brauche nur noch eine Seite!\n\nMit dem Schmöker von Meister Nesingwary gab es einen kleinen... Unfall <Barnil blickt vorwurfsvoll zu Klaps>... und wir haben ein paar der Seiten verloren.\n\nIch habe die anderen Abenteurer bereits um Hilfe gebeten und sie konnten auch ein paar der Seiten wiederfinden, aber eine Seite fehlt immer noch.\n\nIhr seid sicher furchtbar beschäftigt mit anderen Sachen, aber falls Ihr sowieso im Dschungel sein solltet, würde es Euch sicherlich nicht stören, ein wenig nach der Seite Ausschau zu halten?", sourceObjective = "Findet Seite 14 von Die Grünen Hügel des Schlingendorntals.", progress = "Habt Ihr sie gefunden? Ich würde Hemet nur äußerst ungern ein fast fertiges Buch geben.", completion = "Ihr habt mir sicherlich viel Ärger erspart, {name}! Ich kann Euch gar nicht genug danken. Es wird nicht mehr lange dauern, und wir werden das Buch von Meister Nesingwary in Bibliotheken überall auf der Welt finden können!\n\nIch werde eine Kopie für Euch hierlassen, falls Ihr Euch je für das fertige Exemplar interessieren solltet. Vielen Dank, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26270] = { id = 26270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Dank ist Euch gewiss", description = "Es ist viele Jahre her, dass uns Hilfe angeboten wurde, {name}. Wärt Ihr nicht gewesen, hätten wir es womöglich nicht über den nächsten Winter geschafft. Ihr habt Euch als eine selbstlose Person erwiesen - jemand, dem wir vertrauen können. Ich wünschte nur, wir hätten etwas von Wert, das wir Euch anbieten könnten.\n\nIch habe zwar keine Informationen, die Euch bei Eurem Vorhaben, die Mörder der Brauenwirbels zur Strecke zu bringen, von Nutzen sein werden, aber vielleicht kann Euch meine Frau weiterhelfen. Sprecht mit Salma im Haus und sie wird Euch sagen, was Ihr wissen müsst, bevor Ihr Euch wieder auf den Weg macht.", sourceObjective = "Sprecht mit Salma Saldean auf Saldeans Hof in Westfall.", completion = "Aber natürlich, mein Lieber. Unsere kleine Tochter arbeitet an der Späherkuppe und steht den Obdachlosen von Westfall sehr nahe. Vielleicht hat sie ja etwas mitbekommen. Bevor Ihr geht, lasst mich den Westfalleintopf einpacken und Euch ein wenig über unsere liebe kleine Tochter erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26271] = { id = 26271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hungrigen und die Hoffnungslosen speisen", description = "Ja, ich habe von den Brauenwirbelmorden gehört. Es ist sehr tragisch, aber solche Tragödien sind in Westfall an der Tagesordnung. Hier gibt es viele Leute, die einfach nicht mehr die Mittel oder den Willen haben, sich selbst zu versorgen. Sie haben die Hoffnung aufgegeben. Könnt Ihr Euch vorstellen, wie es ist, so hoffnungslos zu sein, dass man sich seines Lebens nicht mehr erfreuen kann? Wir müssen uns gemeinsam darum bemühen, ihnen zu zeigen, dass es noch Hoffnung gibt. Dass jeder neue Tag ein besseres Leben bringt.\n\nNehmt den Westfalleintopf meiner Mutter und helft dabei, die Obdachlosen an der Späherkuppe zu versorgen.", sourceObjective = "Benutzt den Westfalleintopf, um 20 Obdachlose an der Späherkuppe in Westfall zu speisen.", completion = "Ihr habt ein gutes Herz, {name}. Ihr habt heute eine gute Tat vollbracht und das wird Euch am jüngsten Tag nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26272] = { id = 26272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Voldreka im Osten.", sourceObjective = "Trefft Voldreka auf dem Ausbildungsgelände der Dunkelspeere.", sourceObjectiveStatus = "unverified-source-field" }
quests[26273] = { id = 26273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Okay, Mann. Fangen wir klein an. Ich weiß, dass Ihr die Grundlagen der dunklen Künste beherrscht.\n\nGeht und macht diese Tikiziele fertig. Nehmt Euch Zeit. Bleibt ganz natürlich. Ich sehe zu, wie Ihr Eure Zauber formt. Dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", sourceObjectiveStatus = "unverified-source-field" }
quests[26274] = { id = 26274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Hexenmeisters", description = "Ich glaube ich habe da etwas, was ich Euch zeigen kann. Es ist wirklich sehr einfach, sollte aber helfen.\n\nEine der grundlegensten Mächte, die wir kontrollieren können, ist die Fähigkeit, dämonisches Feuer auf unsere Feinde loszulassen, sie brutal zu verbrennen und eine Weile weiterbrennen zu lassen.\n\nVersucht es. Lasst mich wissen, wenn Ihr glaubt, es zu beherrschen.", sourceObjective = "Sprecht mit Voldreka, um \"Feuerbrand\" zu lernen. Übt Feuerbrand fünf Mal, indem Ihr es auf ein Tikiziel anwendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26275] = { id = 26275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[26276] = { id = 26276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit einem Gefängniswärter der Dunkelspeere, dann betretet die Grube und tötet einen gefangenen Späher der Gallschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26277] = { id = 26277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als nur erwartet", description = "Ihr seid auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, wir haben wichtigeres, auf das Ihr Eure Talente anwenden könnt. Ihr müsst nicht mehr mit den Neulingen rumhängen.\n\nGeht runter zum Dorf im Südosten und stellt Euch vor. Helft einfach hier und da aus, und Ihr könnt Euch sicher ganz schön schnell zu etwas prestigeträchtigerem hocharbeiten.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[26278] = { id = 26278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Raptorenrisiko", description = "Throm'ka, {class}!\n\nEure Ankunft in Grom'gol kommt zu einer guten Zeit. Unsere Aufgabe, einen sicheren Weg für die Vorräte für Steinard zu finden, wird von den Ortsansässigen verhindert.\n\nIch werde Euch damit beauftragen, die Raptoren außerhalb Grom'gols für immer zu beseitigen. Macht Euch um die Raptoren selber keine Sorgen... diese jämmerlichen Jäger von Nesingwary werden sich um sie kümmern.\n\nIhr sollt die Eier der Raptoren zerstören.", sourceObjective = "Zerstört 12 Schmetterschwanzeier.", completion = "Macht mir der guten Arbeit weiter, {class}. Höllschrei hat Euch im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26279] = { id = 26279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Ogerunterdrückung", description = "Als wir zuerst hier im Dschungel ankamen hatten wir nicht vor, gegen die Einheimischen einen Krieg zu führen. Unsere Aufgabe, Steinard zu versorgen, hat oberste Priorität. Es ist aber zu Komplikationen gekommen. Ein paar Oger haben die Ruinen von Mizjah südöstlich von Grom'gol eingenommen. Trotz unsere Warnungen greifen sie unsere Versorgungskarawanen weiterhin an.\n\nIch werde Euch damit beauftragen, Euch um die unkooperativen Oger zu kümmern.\n\nBegebt Euch zu den Ruinen und versucht, sie aus der Gegend zu vertreiben. Zumindest muss ihnen eine klare Nachricht geschickt werden.", sourceObjective = "Tötet 4 Schläger der Mosh'Ogg und 4 Hexendoktoren der Mosh'Ogg.", completion = "Ihr seid auch für Sachen zu gebrauchen, die etwas herausfordernder sind als das Zerschlagen von Eiern. Das ist gut. Die Horde kann einen fähigen {race} wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26280] = { id = 26280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Murlocbedrohung", description = "Die Murlocs der Düsterkiemen wurden von den Salzschuppen aus dem Ozean vertrieben und nun suchen sie in den Ruinen von Kal'ai nordöstlich von hier Zuflucht. Früher war das kein Problem, aber inzwischen ist es nicht länger tragbar.\n\nWeit entfernt von dem Ozean, ihrer Heimat, wurden die Düsterkiemen unruhig und schicken Futterwühler aus, um die Versorgungskarawanen zu überfallen. Vermittelt ihnen folgende Nachricht: solches Verhalten wird von Höllschreis Horde NICHT geduldet.", sourceObjective = "Tötet 15 Murlocs der Düsterkiemen.", completion = "Ausgezeichnete Arbeit. Hoffentlich werden die Beutezüge jetzt aufhören.\n\nIch habe noch eine weitere Aufgabe für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26281] = { id = 26281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Grom'gol: Trolldiebstähle", description = "Die Trolle lassen uns eigentlich in Ruhe hier in Grom'gol. Die meisten Trolle wissen genau, dass die Horde sie leicht zerschmettern kann, wenn es sein muss, und auch die Trolle hier in Schlingendorntal sind sich dessen bewusst.\n\nDie Blutskalpe wurden in der letzten Zeit aber immer aktiver. Erst letzte Woche haben sie einen Trupp nach Grom'gol geschickt und mehrere Rationen gestohlen.\n\nDem Stehlen von Nahrung kann von jeder Art des Diebstahls noch am ehesten vergeben werden, aber ich kann trotzdem nicht zulassen, dass es vorkommt während ich das Sagen habe. Begebt Euch nach Norden zu den Ruinen von Bal'lal und holt unser Eigentum zurück.", sourceObjective = "Holt die Rationen aus Grom'gol aus den Ruinen von Bal'lal.", progress = "Mitleid hat unter meinem Kommando nichts zu suchen. Die Trolle können ihr Essen anderweitig besorgen. Der Dschungel ist groß genug.", completion = "<Aggro'gosh begrüßt Euch.>\n\nIhr habt den Dank der Horde, {name}. Grom'gol ist sicher, wenn auch nur für einen Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[26282] = { id = 26282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gunst Akil'darahs" }
quests[26283] = { id = 26283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Schleim", description = "Die Schleime, die in Lauerfels zu finden sind, interessieren mich mehr und mehr. Sie kommen immer wieder, egal, wie oft man sie entfernt, aber sie scheinen sich von einem einzigen Schleim selber nicht vermehren zu können.\n\nIch glaube, das in Lauerfels etwas wächst. Eine Quelle, aus der der Schleim kommt. Ich möchte sie untersuchen - findet diese Quelle und bringt mir eine Probe.", sourceObjective = "Erhaltet eine Terrorklumpenprobe von Terrorklumpen.", progress = "Und? Was habt Ihr gefunden?", completion = "Faszinierend... wie groß war es? Ich frage mich, ob es davon noch andere gibt, die funktionstüchtig sind...\n\nDiese Probe ist ausgezeichnet. Ich werde sie meinen Forscherkollegen zugänglich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26284] = { id = 26284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst", description = "Für solche Aufträge bringe ich normalerweise meine ganze Belegschaft von Demolierern mit. Mit etwas Hilfe bei der Pulverherstellung, der Herstellung der Sprengladungen und dem Rest von unserem Zeug wird alles viel schneller fertig.\n\nDiese verdammten Troggs haben meine Jungs überall rund um die Höhle der Frostmähnen in Käfige gesperrt. Jetzt stehe ich ganz allein da, ohne das Personal, das ich für dieses Vorhaben brauche. Würdet Ihr die Demolierer finden, die die Troggs eingesperrt haben, und sie aus ihren Käfigen befreien?", sourceObjective = "Befreit 6 gefangene Demolierer aus ihren Käfigen in der Nähe der Höhle der Frostmähnen.", completion = "Ihr habt meinen Dank und den der Männer, die Ihr gerettet habt. Ich habe die Jungs schon die Ausrüstung in der Höhle aufstellen lassen. Bald sollte alles bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26285] = { id = 26285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt meinen Sprengstoff zurück!", description = "Wir werden jede Menge Pulver brauchen, um die Höhlen zum Einsturz zu bringen. Keine Ahnung, ob die verdammten Troggs das wussten, als sie meine Vorräte stahlen und meine Demolierer entführten! Das Ergebnis ist dasselbe.\n\nKann nichts in die Luft jagen, wenn ich kein Pulver habe.\n\nGeht nach Süden zur Höhle der Frostmähnen und tötet alle Troggs, die Ihr seht. Jeder von ihnen könnte meine Pulverfässer dabei haben.", sourceObjective = "Beschafft 7 gestohlene Pulverfässer von Knochenpflückern der Felsenkiefertroggs oder von Marodeuren der Felsenkiefertroggs bei der Höhle der Frostmähnen.", progress = "Habt Ihr meine fehlenden Vorräte gefunden?", completion = "Na, so gefällt mir das schon besser. Vielleicht sprengen wir doch noch irgendwas in die Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26286] = { id = 26286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung Westfalls", description = "Nachdem meine Dienstzeit in den Grizzlyhügeln beendet war, bin ich nach Westfall zurückgekehrt und musste das Land in einem schlimmeren Zustand als vor meinem Einsatz vorfinden.\n\nWir haben den Krieg mit tausenden von obdachlosen Bürgern bezahlt. Jetzt wandern sie hierhin aus und lassen sich auf den verlassenen Bauernhöfen und Siedlungen dieser Gegend nieder.\n\nZu allem Überfluss werden wir jetzt auch noch von den Gnollen angegriffen. Die Westfallbrigade braucht Eure Hilfe, {name}. Tötet die angreifenden Gnolle und nehmt ihnen ihre Befehle ab. Da zieht jemand im Hintergrund die Fäden und wir müssen herausfinden, wer das ist!", sourceObjective = "Erhaltet die Angriffsbefehle der Gnolle.", progress = "Habt ihr die Angriffsbefehle?", completion = "Helix? Den Namen habe ich doch schon mal gehört. Und zwar vor gar nicht so langer Zeit, aber wer ist dieser Admiral?", sourceObjectiveStatus = "unverified-source-field" }
quests[26287] = { id = 26287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Westfallbrigade", description = "Wir waren einst als Volksmiliz bekannt. Heutzutage kämpfen wir unter der Flagge von Sturmwind mit der vollen Unterstützung von König Varian Wrynn. Wir haben viele Ziele hier in Westfall: die Unordnung, die die Defias hinterlassen haben, aufzuräumen, das Hoheitsgebiet der Allianz auszuweiten und Ordnung zu bewahren. Bisher versagen wir auf der ganzen Linie.\n\nDie Zeiten sind jetzt noch schlimmer, als zu dem Zeitpunkt, als die Defias Amok gelaufen sind. Jetzt, da die einheimischen Gnolle sich ebenfalls bewaffnet haben, sind wir in eine Ecke gedrängt worden. Helft uns, {name}!", sourceObjective = "Tötet 12 beliebige Gnolle der Flusspfoten, die die Späherkuppe angreifen.", completion = "Gut gemacht, {name}. Ihr habt uns eine Atempause von dem Sturmangriff der Gnolle verschafft, aber es gibt noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26288] = { id = 26288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jango Fleckfell", description = "Südlich von hier befindet sich ein Landstrich von Westfall, den wir Staubebenen nennen. Soweit wir wissen, haben die Gnolle der Region die Staubebenen zu ihrem inoffiziellen Hauptquartier erklärt. Wie bei jedem Hauptquartier gibt es auch bei diesem einen Anführer. Wenn wir diesen Angriffen einen Riegel vorschieben wollen, dann müssen wir den Gnoll ausfindig machen, der den Ton angibt, und ihm das Handwerk legen.\n\nBegebt Euch zu den Staubebenen, findet den Anführer der Gnolle, Jango Fleckfell, und tötet ihn. Erledigt auch sämtliche Gnolle, die sich Euch in den Weg stellen.", sourceObjective = "Tötet 5 Mystiker der Flusspfoten, 5 Zuchtmeister der Flusspfoten und Jango Fleckfell.", completion = "Ausgezeichnete Arbeit, {name}. Die Flusspfoten werden Wochen brauchen, um sich von dem Schlag zu erholen, den Ihr ihnen heute zugefügt habt. Bitte wählt einen Gegenstand als Belohnung für Eure Tat aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26289] = { id = 26289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Agentin Kearnen", description = "Der SI:7 hat die Bewegungen von Helix Ritzelbrecher genau beobachtet, seit er vor zwei Wochen seinen Fuß auf Allianzboden gesetzt hat. Der Brief, den ich von Mathias Shaw erhalten habe, erklärt, dass er eine Agentin namens Kearnen nach Westfall entsandt hat, um Helix zu beschatten. Findet Agentin Kearnen, dann werdet Ihr auch Helix Ritzelbrecher finden.\n\nKearnen war vor zwei Tagen in der Stadt, um Vorräte zu besorgen. Sie hat erwähnt, dass sie in der Nähe von Jagdrufs Turm südöstlich von hier in den Staubebenen zu finden sein würde.\n\nAbmarsch, {name}.", sourceObjective = "Findet Agentin Kearnen.", completion = "Helix steckt hinter den Gnollangriffen?\n\n<Kearnen nickt dem Turm zu.>\n\nEr ist da drin. Er ist schon seit Tagen dort. Ich warte nur auf einen Grund, ihn hopszunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26290] = { id = 26290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Turms", description = "Helix hat sich oben im alten Turm von Klaven Jagdruf verschanzt. Ich werde Euch nicht belügen, {name}, er wird schwer bewacht. Ich habe allein im Freien sechs bewaffnete Söldner gezählt. Ihr schafft es nie allein in den Turm. Zu Eurem Glück sind Claire und ich hier.\n\n<Kearnen tätschelt ihr Scharfschützengewehr.>\n\nIch gebe Euch Deckungsfeuer.\n\nNehmt diesen Verschleierungstrank; Ihr werdet ihn brauchen, wenn Ihr es ins Innere geschafft habt. Trinkt ihn, sobald Ihr den Turm betretet und steigt dann den Turm hinauf. Findet heraus, was Helix dort oben versteckt!", sourceObjective = "Betretet Jagdrufs Turm und macht Helix Ritzelbrecher ausfindig.", completion = "Was um alles in der Welt könnte denn in Mondbruch los sein? Das alles schmeckt mir überhaupt nicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26291] = { id = 26291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel Ärger in Mondbruch", description = "Ich werde bald meinen Bericht schreiben und nach Sturmwind zurückkehren. Der SI:7 muss über die Situation in Westfall informiert werden. Ich schlage vor, Ihr tut das gleiche und erstattet Gryan Bericht.", sourceObjective = "Berichtet Marschall Gryan Starkmantel an der Späherkuppe in Westfall, was Ihr herausgefunden habt.", completion = "Wer ist wohl diese merkwürdige Gestalt? Wir müssen nach Mondbruch gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26292] = { id = 26292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Mondbruch!", description = "Wir haben schon eine ganze Weile ein Lager in der Nähe von Mondbruch, {name}. Einer meiner besten Soldaten ist zusammen mit einer Kompanie von der Späherkuppe in diesem Gebiet stationiert. Meldet Euch umgehend bei Hauptmann Alpert und findet heraus, ob er irgendwelche Neuigkeiten über die Vorgänge in Mondbruch hat.\n\nEin weiterer Verbündeter von mir ist auch in dem Mondbrucher Lager. Sein Name ist Thoralius. Ich habe Thoralius in Nordend während meiner Dienstzeit in Valgarde kennengelernt. Er ist ein weiser und mächtiger Schamane. Vielleicht können uns seine Fähigkeiten dabei helfen, diesen Fall zu lösen.", sourceObjective = "Meldet Euch bei Hauptmann Alpert in Mondbruch in Westfall.", completion = "Die Einheimischen werden unruhig, {name}. Ich weiß nicht, was los ist, aber die Aktivitäten der Obdachlosen in dieser Gegend haben sich in den letzten zwei Tagen vervierfacht. Wenn ich es nicht besser wüsste, würde ich sagen, die hecken etwas aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[26293] = { id = 26293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen", description = "Diese \"Weltenbrecher\" verstecken sich in einer Hochlandwildnis und besetzen die Gebiete hinter den Allianzkönigreichen im Osten. Wir werden sie vernichten, und zwar mit der mächtigsten Armee seit unseren Siegen in Nordend!\n\nIch habe unsere neuen Goblinverbündeten gebeten, eine Flotte an Kriegsmaschinen zu bauen, doch die Berichte zeigen, dass ihre Arbeitsqualität manchmal... zu wünschen übrig lässt.\n\nIch werde nicht mit fehlerhaften Maschinen in die Schlacht ziehen. Trefft Euch mit Großknecht Glibbs hier in Orgrimmar und stellt sicher, dass meine Kriegsmaschinen kampfbereit sind!", sourceObjective = "Sprecht mit Großknecht Glibbs am Hinteren Tor von Orgrimmar in Orgrimmar.", completion = "Hab zu tun. Geht weg.\n\nWartet, was? Höllschrei schickt Euch? Was… äh… was kann ich für Euch tun? Für ihn? Für uns?", sourceObjectiveStatus = "unverified-source-field" }
quests[26294] = { id = 26294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massenversagenswaffen", description = "<Glibbs wischt sich mit einem öligen Taschentuch den Schweiß von der Stirn.>\n\nHöllschrei ist mit unserer Arbeit nicht zufrieden? Oh weh. Und wir haben \"Höllschreis Verwüster\" sogar nach ihm BENANNT. Das ist nicht gut. Meine Jungs müssen sich mehr ins Zeug legen.\n\nVielleicht könnt Ihr für uns ein Exempel statuieren. Ein neuer Satz von Höllschreis Verwüstern kam gerade aus der Produktion und ist bereit, inspiziert zu werden. Untersucht sie gründlich. Wenn Ihr Probleme findet, dann verpasst dem Chefingenieur eine Abreibung. Erinnert ihn daran, dass Höllschrei uns im Auge hat!", sourceObjective = "Untersucht Höllschreis Verwüster, bis Ihr einen fehlerhaften Verwüster findet, und erteilt dem Chefingenieur dann eine Lektion.", completion = "<Garrosh lacht.>\n\nIhr habt ihnen also ein bisschen Disziplin beigebracht, was? Gut, gut!\n\nIn meiner Horde leistet jeder seinen Beitrag, vom geringsten Peon bis hin zum stolzesten Krieger. Weniger dulde ich nicht.\n\nUnsere Vorbereitungen für die Invasion sind fast abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26295] = { id = 26295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda", description = "Uns ist ein Anstieg der Gewalttaten unter den Obdachlosen in dieser Gegend aufgefallen. Irgendetwas oder irgendjemand versetzt sie ganz schön in Aufruhr. Wer auch immer dahinter steckt, organisiert sich immer besser. Erst vor Kurzem ist eine Gruppe Schläger hier durchgekommen und hat Flugblätter verteilt.\n\nGeht nach Mondbruch und sucht nach Beweisen. Propaganda, Handzettel, egal was... Bringt mir alles, was Ihr finden könnt. Vielleicht können wir ja den Ursprung der Schriften finden.", sourceObjective = "Erhaltet ein Informationsflugblatt, ein geheimes Tagebuch, eine Ausgabe des Mondbrucher Blatts und mysteriöse Propaganda.", progress = "Konntet Ihr etwas finden?", completion = "V? Der einzige V, den ich kenne, ist van Cleef und der ist vor vielen Jahren gestorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26296] = { id = 26296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweissammlung", description = "Dieses Kopftuch besteht aus dem gleichen Stoff, der auch am Tatort des Brauenwirbelmordes gefunden wurde. Ihr solltet noch mehr rote Kopftücher als Beweis sammeln und Euren Fund zu Hauptmann Alpert bringen.", sourceObjective = "Sammelt 6 rote Kopftücher.", progress = "Rote Kopftücher?!", completion = "Ich habe seit fünf Jahren keine roten Kopftücher mehr gesehen. Ob diese merkwürdige Gestalt wohl versucht, die Bruderschaft der Defias neu zu gründen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26297] = { id = 26297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anbruch eines neuen Tages", description = "Sieht so aus, als fängt die Versammlung, von der die merkwürdige Gestalt sprach, bald an. Die Obdachlosen setzen sich in Bewegung. Ich möchte, dass Ihr an der Kundgebung teilnehmt und Informationen sammelt, {name}.\n\nBegebt Euch zur Stadtmitte Mondbruchs und hört Euch die Ansprache an. Kehrt zu mir zurück und berichtet, was Ihr herausfinden konntet.", sourceObjective = "Sammelt Informationen bei der Versammlung von Mondbruch.", completion = "Ich konnte die Jubelschreie von hier aus hören. Wir haben es anscheinend mit einem riesigen Problem zu tun, {name}. Wir müssen die Identität dieser schattenhaften Bedrohung aufdecken, bevor wir die Hilfe Sturmwinds anfordern. Vielleicht gibt es eine andere Möglichkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[26298] = { id = 26298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Yenniku", description = "Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Dunkelspeerstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.\n\nUnd ich glaube, dass der Blutskalpstamm ihn hat.\n\nWenn Ihr mir helfen wollt, dann jagt die Blutskalpe. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.", sourceObjective = "Beschafft 6 Hauer der Blutskalpe von Blutskalptrollen in den Ruinen von Bal'lal.", progress = "{class}. Zeigt mir, dass Ihr Beute von dem Blutskalpstamm gemacht habt.\n\nZeigt mir Eure Trophäen.", completion = "Das sind gute Hauer, {name}. Ihr habt bewiesen, dass Ihr stark genug seid, um die Blutskalpe zu jagen.\n\nDas ist gut, denn die Jagd auf sie ist für Euch noch nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[26299] = { id = 26299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfjägerei", description = "Wir müssen herausfinden, ob Yenniku tot ist.\n\nErschlagt die Kopfjäger der Blutskalpe und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.\n\nSollte Yenniku von den Blutskalpen getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!\n\nGeht, {name}. Ihr könnt die Köpfe bei den Ruinen von Zuuldaia an der Küste im Norden finden.", sourceObjective = "Beschafft 25 Schrumpfköpfe von Blutskalptrollen in den Ruinen von Zuuldaia.", progress = "{name}. Ich fürchte um den Sohn unseres Häuptlings. Habt Ihr die Schrumpfköpfe, sodass ich sie untersuchen kann?", completion = "Ich danke Euch, {name}. Ich werde sie sogleich untersuchen, um sicherzugehen, dass der arme Yenniku der Axt der Kopfjäger entgangen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26300] = { id = 26300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nezzliok wird es wissen", description = "Yennikus Kopf war nicht dabei und ich danke der großen Schlange dafür. Wir sind aber noch keinen Schritt weiter, ihn zu finden.\n\nWir müssen die Wahrheit erfahren und ich fürchte, nur der Hexendoktor der Blutskalpe wird uns helfen können. Als Feind der Dunkelspeere wird er nicht offen sprechen wollen und daher müssen wir die Wahrheit aus seinen toten Lippen zwingen!\n\nBringt mir den Kopf von Nezzliok dem Düsteren und platziert ihn hier im Kessel.\n\nIhr werdet ihn tief in Zul'Kunda finden. Bringt mir seinen Kopf... wir werden ihn schon zum Sprechen bringen.", sourceObjective = "Erhaltet Nezzlioks Kopf von Nezzliok dem Düsteren in Zul'Kunda.", progress = "Die grüne Brühe im Kessel brodelt.", completion = "Ihr platziert den Kopf von Nezzliok im Kessel...", sourceObjectiveStatus = "unverified-source-field" }
quests[26301] = { id = 26301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Nezzliok sprechen", description = "<Der Kopf von Nezzliok spricht.>\n\nEs stimmt. Ich weiß, wo das Kind der Dunkelspeere hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!\n\nDie Blutskalpe streiten mit den Schädelspaltern. Um mein Wohlwollen zu erhalten, stehlt zwei der meist geschätzten Trophäenschädel von den Schädelspaltern östlich des Flusses. Legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah und der zweite von Ziata'jai stammen.", sourceObjective = "Erhaltet eine Trophäe von Balia'mah und eine Trophäe von Ziata'jai aus den Ruinen der Schädelspalter.", progress = "Ich erwarte die Schädel...", completion = "Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in den Nether eintreten!\n\nIhr seid eine Zierde Eures Klans, {race}, und Ihr habt mich beschwichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26302] = { id = 26302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yennikus Schicksal hinterher", description = "<Nezzliok spricht.>\n\nIhr habt mich und meinen Meister beschwichtigt und ich werde Euch die Informationen geben, nach denen es Euch verlangt...\n\nDer junge Yenniku ist verloren.\n\nEr wurde von Hexendoktor Zanzil dem Ausgestoßenen entführt. Jetzt sind sein Geist und sein Körper in Zanzils Kontrolle und nur die stärkste aller Magien kann ihn davon befreien.\n\nMagie, die Euch nicht zur Verfügung steht, {class}.\n\nVielleicht können Eure Verbündeten der Dunkelspeere in Bambala östlich von einen Hoffnungsschimmer zur Erlösung Yennikus darstellen. Aber das bezweifle ich.", sourceObjective = "Sprecht mit Kin'weelay in Bambala.", completion = "Zanzil der Ausgestoßene??\n\nWenn Yenniku von diesem Troll, einem bösartigen und mächtigen Hexedoktor, gefangen gehalten wird, dann befürchte ich, dass nur das kleinste bisschen Hoffnung übrig bleibt. Das Allerkleinste. So klein wie das kleinste aller Insekten.\n\nIch habe aber auch einen Verdacht. Ein Verdacht, der zu Yennikus Erlösung führen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26303] = { id = 26303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gedankenauge", description = "Das Gedankenauge befindet sich bei einem Ogermagier, im Ogerhügel der Mosh'Ogg südlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Dunkelspeere im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.\n\nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.\n\nIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.", sourceObjective = "Erhaltet das Gedankenauge von Mai'Zoth.", progress = "Seid gegrüßt, {name}. Die Geister lobpreisen Euren Mut, aber sie sagen mir nichts von Eurem Kampf gegen Mai'Zoth.\n\nHabt Ihr das Auge?", completion = "Ihr habt das Auge geholt! Eure Macht ist der Stoff, aus dem Legenden sind, {name}!\n\nUnd da Ihr im Besitz des Auges seid, müsst Ihr Mai'Zoth besiegt und ihn in den Nether geschickt haben. Darum wollten die Geister zuvor nicht von ihm sprechen.\n\nEs ist gut, dass er diese Welt des Fleisches und der Knochen verlassen hat, aber nun, da er im Reich der Geister wandelt... fürchte ich, wird er dort erneut die Macht ergreifen.\n\nAber darum sorge ich mich ein anderes Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26304] = { id = 26304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn es Nacht wird im Dschungel", description = "Vor einem Jahr wurde meine Mutter - die Trollfrau, die mich großzog - von den Schädelspaltern Zul'Mamwes gefangen genommen. Jung und eigen wie ich war machte ich mich auf, um sie zu retten, nur um zu sehen, wie sie von einem Dutzend Krieger auf eine riesige brennende Kohlenpfanne zugestoßen wurde. Ich versteckte mich hinter einem Baum und sah zu, wie sie sie packten und.. und..\n\n<Kil'karil senkt seinen Blick.>\n\nWenn es Nacht wird wird das Licht der Kohlenpfannen von den Bäumen reflektiert und hält mich wach. Bitte, {name}... reist nach Süden nach Zul'Mamwe und löscht die Kohlenpfannen.", sourceObjective = "Löscht 8 Kohlenpfannen von Zul'Mamwe in Zul'Mamwe im Nördlichen Schlingendorntal.", completion = "Der Geist meiner Mutter wird heute in Frieden ruhen, {name}.\n\nUnd ich auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26305] = { id = 26305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yennikus Rettung", description = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.\n\nMeine anfänglichen Vermutungen waren korrekt: die Geister sagen mir, dass Yenniku nicht bei Zanzil dem Ausgestoßenen ist, sondern in den Ruinen von Zul'Mamwe im Südwesten. Kehrt zu Nimboya in Grom'gol zurück, sobald Ihr Yennikus Seele befreit habt.", sourceObjective = "Bringt den gefüllten Seelenedelstein zu Nimboya.", progress = "{name}. Kin'weelay sagte mir, er habe Euch ausgesandt, Yenniku zu finden.\n\nIst es wahr? Habt Ihr ihn?", completion = "Ihr habt es geschafft! Ihr konntet Yenniku vom Willen Zanzils und der Tyrannei der Schädelspalter befreien und so die Mission erfüllen, die ich kurz vorm Scheitern sah.\n\nZanzil ist noch immer eine Bedrohung für das Schlingendornkap, aber zumindest weiß ich jetzt, dass die Seele des Häuptlingssohnes frei ist.\n\nUnser Stamm wird Euren Namen in Liedern ehren, {name}, und wir werden Eure Geschichte in Stein ritzen, so dass sie auf ewig leben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[26306] = { id = 26306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anfang der Zurückeroberung", description = "Heute fangen wir mit dem ersten Angriff auf das Herz des wilden Blutfratzenstamms an. Zeigt ihnen keine Gnade, {name}. Hier geht es um mehr als Rivalität unter Trollen. Jeder Sieg der Bruchhauer ist ein Sieg für die Horde!\n\nDie Kopfjäger der Blutfratzen und Hexendoktoren müssen zuerst beseitigt werden. Greift die unteren Terrassen an und erstattet mit Blut an Eurer Waffe Bericht bei mir.", sourceObjective = "Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha'Alor.", completion = "Gut gemacht, {name}! Lasst die Blutfratzen vor Angst fliehen, die ihnen durch Euren Anblick eingeflößt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[26307] = { id = 26307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Blutfratzen", description = "Wir werden ihnen nicht erst die Gelegenheit geben, auf unseren Angriff zu reagieren. Ihr müsst zurück nach Jintha'Alor und Euch den Weg zu den höheren Ebenen freikämpfen.\n\nDie Berserker und Schattenzauberer der Blutfratzen sind gefährliche Gegner, {name}. Wenn die anderen sehen, wie ihre Leichen über die Mauern geworfen werden, so werden sie wissen, WIE ernst wir es meinen.\n\nIch möchte kein Blutfratzenherz mehr schlagen hören!", sourceObjective = "Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha'Alor.", completion = "Es wird nicht mehr lange dauern und wir sind die einzigen atmenden Trolle bei diesen Mauern!", sourceObjectiveStatus = "unverified-source-field" }
quests[26308] = { id = 26308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gehört jetzt uns", description = "Nur die stärksten und bösartigsten Blutfratzen sind übrig geblieben. Die Seelenfresser und Bluttrinker, die verkommenen Anhänger des bösen Gottes Hakkar.\n\nSie sind NARREN! Sie halten an altem, falschem Glauben fest. Ich werde ihre Verbrechen gegenüber den Bruchhauern nicht länger dulden.\n\nMacht Euch zum finalen Angriff auf. Nehmt Jintha'Alor für die Bruchhauer ein... nehmt es für die Horde ein!", sourceObjective = "Tötet 5 Bluttrinker der Blutfratzen und 5 Seelenfresser der Blutfratzen in Jintha'Alor.", completion = "Nun ist niemand mehr übrig, der sich den Bruchhauern in den Weg stellen kann! Um Nachzügler können wir uns problemlos kümmern.\n\nIhr habt meinem Volk eine große Ehre erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26309] = { id = 26309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Gefäße", description = "Die Trolle der Blutfratzen hier haben früher das verdorbene Blut des Gottes Hakkars getrunken, um Macht zu erlangen. Sie haben es, bevor sie es tranken, in primitiven Kesseln gekocht - dunkle Gefäße voller unheiliger Stärke.\n\nHakkar wurde natürlich vor langer Zeit schon getötet. Doch das Interessante ist... Ich sehe immer noch Kessel, die hier oben blubbern. Bringt mir einige her und dann sehen wir, was sie so zusammenbrauen.", sourceObjective = "Beschafft 5 Gefäße mit besudeltem Blut aus Jintha'Alor.", progress = "Seid vorsichtig in der Nähe der Kessel, {class}. Die Blutfratzen werden nicht kampflos zulassen, dass Ihr ihre Leckereien wegnehmt.", completion = "Erst Spinnen und jetzt das hier. Ich kann das Gift in seinem Blut reichen... Es ist dasselbe wie bei den Huschern, nur stärker.\n\nDie Blutfratzen und Spinnen... Ich sehe da Potential.", sourceObjectiveStatus = "unverified-source-field" }
quests[26310] = { id = 26310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was krabbelt", description = "Bevor Ihr dort hoch geht, {class}...\n\nIch kenne ein paar Verkäufer, die sehr interessiert an starken Giften sind. Mir sind die Spinnen in der Gegend natürlich nicht entgangen... sie sind nicht riesig, aber ungefähr so groß wie Euer Hand.\n\nSie haben eine Färbung, die ich noch nie zuvor in der Gegend gesehen habe. Könntet Ihr ein paar sammeln und mir bringen?", sourceObjective = "Sammelt 8 huschende Spinnlinge in Jintha'Alor.", progress = "Wie viele habt Ihr gefunden?", completion = "Oh ja... es war gut von mir, Euch zu beten, mir diese Spinnlinge zu bringen. Sie sind so faszinierend.\n\nKommt her, meine Hübschen. Hier in meine Tasche, so ist es brav.", sourceObjectiveStatus = "unverified-source-field" }
quests[26311] = { id = 26311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbekannte Gewässer", description = "Der Kriegshäuptling plant einen großangelegten Angriff auf das Schattenhochland. Wir hoffen, dass wir uns dort mit den Orcs des Drachenmals verbünden können.\n\nMeine Quellen haben mir berichtet, dass ein Orc des Drachenmalklans hier in Orgrimmar lebt. Er ist als Herezegor Flammenhauer bekannt und führte einst ihre Krieger an.\n\nSein Wissen als einer von ihnen ist für uns von größtem Wert. Findet Flammenhauer und besorgt uns eine Karte der Wasserwege im Schattenhochland.\n\nLaut meinen letzten Informationen hielt er sich in einer Kneipe im Tal der Ehre auf...", sourceObjective = "Findet Herezegor Flammenhauer in der Kneipe \"Zum Wyvernschweif\" im Tal der Ehre in Orgrimmar und besorgt Euch eine Küstenkarte des Schattenhochlands.", progress = "<Sauranok ist überrascht, Euch so bald wiederzusehen.>\n\nAh, {class}, Ihr seid zurück. Was habt Ihr herausgefunden?", completion = "<Sauranok scheint sich nicht für die Karte zu interessieren, während Ihr Eure Geschichte erzählt.>\n\nZwielichtassassinen sind Euch in die Kneipe gefolgt? Hier in Orgrimmar?\n\nDer Kriegshäuptling wird alles andere als erfreut sein, das zu hören.\n\nFahrt mit Euren Vorbereitungen für den Einmarsch fort. Ich versuche, mehr darüber herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26312] = { id = 26312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bröckelnde Verteidigung", description = "Als der Angriff begann, sind wir nach vorne geprescht, um das Feld so schnell wie möglich einzunehmen. Ihre Streitkräfte waren schier unerschöpflich... wir haben sie unterschätzt. Nun sitzen einige unserer besten Schamanen da draußen fest, gestrandet, erschöpft und weit entfernt von unserer Verteidigung.\n\nBegebt Euch auf das Feld und entlastet unsere gestrandeten Brüder. Selbst eine kleine Pause vom Kampf sollte ihnen die Gelegenheit geben, endlich einmal durchzuatmen.\n\nBeeilt Euch, {class}.", sourceObjective = "Entlastet Tawn Winterfels, Sturmruferin Mylra und Hargoth Trübflamm, indem Ihr ihnen helft, ihre Gegner zu besiegen.", completion = "Vielen Dank, {class}. Viele Anhänger des Irdenen Rings verdanken Euch heute ihr Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26313] = { id = 26313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kern unserer Sorgen", description = "Elementare sind von Natur aus chaotisch, doch diese organisierte Aggressivität passt einfach nicht zu ihnen. Besonders hier unten, wo ihr Tod ein bisschen dauerhafter ist. Ich vermute, die Steinmutter Therazane steckt dahinter, aber ich muss Gewissheit haben.\n\nVernichtet die Zornsteinrumpler und bringt mir ihre Kerne. Wenn wir es mit dem Hass der Steinmutter zu tun haben, werden wir die Sache hier und jetzt erledigen.", sourceObjective = "Sammelt 6 Zornsteinkerne.", progress = "Die Elementarlords waren nie unsere Freunde, aber wir haben dennoch auf ein gewisses Maß an Sicherheit in ihrem Chaos vertraut. So lange sie unorganisiert bleiben, haben wir nur wenig zu fürchten.\n\nWenn die Steinmutter jedoch tatsächlich die Erde gegen uns in den Kampf führt, haben wir Einiges zu befürchten.", completion = "Die sind in einem überraschend guten Zustand. Gute Arbeit, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26314] = { id = 26314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fest auf dem Boden", description = "Wir können von Glück sagen, dass diese Riesen so schlecht zielen. Doch irgendwann wird das Glück auf ihrer Seite sein.\n\nWir müssen sie aus dem Kampfgeschehen nehmen, aber ihnen direkt gegenüberzutreten ist wohl keine gute Idee.\n\nNehmt dieses Wurfleine, werft sie ihnen um einen Knöchel und zieht ihnen die Füße weg. Sobald sie am Boden liegen, sollten sie leicht zu besiegen sein.", sourceObjective = "Benutzt die Elementiumwurfleine, um 3 Diener von Therazane von den Füßen zu holen.", completion = "Das wird ihren Angriff ein wenig verlangsamen, bis Norsala einen Weg gefunden hat, sie zu besänftigen. Wir haben kein Bedürfnis, weiter Feinde von Therazane der Steinmutter zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26315] = { id = 26315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein imposantes Aufeinandertreffen", description = "Habt Ihr den Riesen gesehen, der bedrohlich im Nordwesten aufragt? Das ist Boden der Imposante, einer der Steinlords von Therazane der Steinmutter.\n\nWir wissen nicht viel über die Steinlords, aber Boden zählt nicht gerade zu den Sanftmütigen seiner Art. Leider führt ausgerechnet er den Angriff an, also müssen wir ihm gegenübertreten.\n\nBringt diese Proklamation zu ihm und lest sie im Namen des Irdenen Rings laut vor. Ich weiß, es ist ganz schön optimistisch zu hoffen, dass Worte dies beilegen können, aber wir müssen es versuchen. Seid vorsichtig.", sourceObjective = "Lest Boden dem Imposanten die Proklamation des Irdenen Rings vor.", progress = "Hattet Ihr schon die Gelegenheit, Boden gegenüberzutreten?", completion = "Ja… genau diese Reaktion hatte ich erwartet.\n\nDoch er hat Diamant erwähnt? Wenn die beiden nicht miteinander auskommen, ist dieser Diamant vielleicht nicht so unbändig wie Boden. Zumindest besteht eine kleine Hoffnung.\n\nMal sehen, ob ich die Erde dazu bringen kann, mir den Aufenthaltsort dieses Diamant zu verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26316] = { id = 26316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worauf wartet Jessup?", description = "Der Kataklysmus öffnete tiefe Spalten unter der Höhle der Frostmähnen. Troggs stürmten daraufhin aus ihren Bauten. Es gelang ihnen, die Trolle, die dort lebten, zu verjagen und das gleiche Schicksal blüht uns auch, wenn wir nicht handeln.\n\nHochtüftler Mekkadrill hat den bekannten Demolierer Jessup McCree angeheuert, um die Spalten zu versiegeln und den Ansturm der Troggs zu beenden. Er hat uns noch nicht mitgeteilt, ob es ihm gelungen ist, die Troggs aufzuhalten. Würdet Ihr in seinem Lager nahe der Höhle der Frostmähnen, südlich des Toxischen Flugplatzes nach ihm suchen?", sourceObjective = "Findet Jessup McCree in seinem Lager nahe der Höhle der Frostmähnen.", completion = "Die Tunnel zu sprengen, ist nicht schwer, aber dafür brauche ich mein Team und meine Ausrüstung. Vorher kann ich nicht anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26317] = { id = 26317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schmetterschwanzjunges", description = "Als Ihr das letzte der Schmetterschwanzeier zerstört habt, seht Ihr, wie ein neugeborenes Schmetterschwanzjunges Euch anschaut. Ihr seht, wie es Euch genau betrachtet, Eure Gesichtszüge untersucht und alle Eure Bewegungen aufmerksam verfolgt.\n\nDas Schmetterschwanzjunge hat Euch in sein Herz geschlossen.\n\nEigentlich solltet Ihr die Bevölkerung der Raptoren ausmerzen, aber Ihr habt alle Eier zerstört, die von Euch zerstört werden sollten, und dieser Raptor ist ein unschuldiges Jungtier. Vielleicht weiß jemand im Basislager Grom'gol, was man mit einem Raptorenjungen anfangen kann.", sourceObjective = "Bringt das Schmetterschwanzjunge zu Scharfseher Mok'thardin im Basislager Grom'gol.\n\nBereitgestellter Gegenstand:", completion = "Ja, die Kleine scheint einen Narren an Euch gefressen zu haben. Ich vermute, dass ein einzelner Raptor, noch dazu, wenn er unter Orcs aufwächst, eine viel geringere Gefahr sein wird, als ein ganzes Rudel. Behaltet sie, {name}... vielleicht erweist sie sich noch als nützlich.\n\nUm genau zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26318] = { id = 26318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unvollendete Aufgabe", description = "Mein Team hat die Pulverfässer und den Zünder bereits am Ende der Höhle im westlichen Teil der Höhle der Frostmähnen angebracht. Ihr müsst nur dorthin vordringen und den Zünder aktivieren, dann explodiert das Pulver und die Tunnel brechen ein.\n\nDann werden die Troggs die Tiefen der Erde nicht mehr verlassen. Mekkadrill wird mit den restlichen Troggs leichter fertig werden, wenn Ihr ihren Anführer, der sich selbst Boss Bruggor nennt, ausschaltet. Viel Glück, {name}.", sourceObjective = "Dringt zum Ende der Höhle in der Höhle der Frostmähnen vor, tötet Boss Bruggor und aktiviert den Zünder, um die Troggtunnel zum Einsturz zu bringen.", completion = "Ich konnte die Explosion selbst hier oben spüren! Meine Jungs haben die Sprengung gut vorbereitet, aber ohne Eure Hilfe hätte uns das nichts genutzt. Es ist nur gerecht, wenn ich mein Vertragshonorar mit Euch teile. Schließlich habt Ihr unsere Aufgabe vollendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26319] = { id = 26319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelöste Geheimnisse", description = "Es gibt hier einen Schamanen, Thoralius, der uns vielleicht helfen kann. Er ist ein Freund von Gryan und ist vor Kurzem nach Westfall gekommen, um die elementare Verwüstung zu untersuchen, die über uns hereingebrochen ist.\n\nSprecht mit Thoralius und seht, ob er etwas Licht auf die Identität dieser merkwürdigen Gestalt werfen kann.", sourceObjective = "Sprecht mit Thoralius dem Weisen in Mondbruch in Westfall.", completion = "Hmm, ja, vielleicht kann ich Euch helfen. Als ich in Nordend war, habe ich den Einwohnern von Valgarde dabei geholfen, einige der Geheimnisse der Vrykul aufzudecken, indem ich in die Geisterwelt eingetaucht bin. Vielleicht kann ich dasselbe auch hier tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26320] = { id = 26320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision aus der Vergangenheit", description = "Dieser Weihrauch wird Euren Körper und Euren Geist in tiefe Meditation versetzen. Sobald die Trance beginnt, werdet Ihr in die Geisterwelt übertreten. Wehrt Euch nicht gegen die Trance, sobald sie begonnen hat, {name}. Erlaubt den Geistern, Euch zu zeigen, was sie wissen.\n\nIhr müsst nun aufbrechen. Begebt Euch zu den Todesminen, ein Ort, der angeblich eine große Rolle in der Geschichte Westfalls gespielt hat. Sobald Ihr im Inneren seid, benutzt den Weihrauch.\n\nIhr gelangt durch das alte Bauernhaus südlich von hier in die Todesminen. Folgt den Obdachlosen.\n\nKehrt zu Gryan zurück und berichtet ihm von dem, was Ihr erfahren habt.", sourceObjective = "Betretet das Versteck der Defias und folgt der Spur der Obdachlosen in die Todesminen. Betretet den Dungeon \"Die Todesminen\" und benutzt das Räuchergefäß, um in die Vergangenheit zu blicken.", completion = "WAS? Van Cleef hatte eine Tochter?", sourceObjectiveStatus = "unverified-source-field" }
quests[26321] = { id = 26321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaube, sie hat Hunger", description = "Ich glaube, Euer Raptorenjunges ist hungrig. Wenn Ihr sie behalten wollt, solltet Ihr Essen für sie finden, nicht wahr? Schmetterschwänze greifen oft das Lager der Düsterkiemen nördlich von hier an.\n\nSie ist wahrscheinlich noch nicht stark genug, um selbst zu jagen, aber frisches Murlocfleisch kann sie sicher schon essen.", sourceObjective = "Tötet Murlocs der Düsterkiemen im Nördlichen Schlingendorntal und gebt Eurem Schmetterschwanz 40 Bissen Murlocfleisch.", completion = "Sie sieht schon ein bisschen größer aus! Ihr müsst wissen, dass Raptoren schnell wachsen. Ihr habt Glück, so einen starken Begleiter gefunden zu haben.\n\nBehaltet sie, so lange Ihr könnt, {name}. Sie wird sich sicherlich bald als sehr wertvoll für Euch erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26322] = { id = 26322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Bruderschaft", description = "Ich hatte ja keine Ahnung, dass van Cleef eine Tochter hatte, {name}. Wenn es etwas gab, in dem der Mann außerordentlich gut war, dann war es, Geheimnisse zu bewahren.\n\nWie tragisch. Das arme Ding hat eine schreckliche Tat mitangesehen. Hätte ich doch nur etwas geahnt.\n\nWas war das? Habt Ihr etwas gehört? Scheint so, als ziehen sich die Gnolle zurück... wo sind meine Wachen?\n\nPASST AUF, {name}!", sourceObjective = "Werdet Zeuge des Aufstiegs der Bruderschaft.", completion = "Ich werde sofort ein Bataillon nach Westfall entsenden! Nun da die Bruderschaft der Defias neu gegründet worden ist, ist eine alte Bedrohung für das Königreich wiederauferstanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26323] = { id = 26323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsschädel", description = "Euer Raptor scheint ein neues Spielzeug gefunden zu haben: einen Schädel aus einem Haufen von Trollschädeln.\n\nIhr wisst nicht, warum sie diesen Schädel allen anderen bevorzugt, aber aus irgendeinem Grund lässt sie nicht von ihm ab.\n\nNimboya im Basislager Grom'gol ist eine Art Schädelexperte, wenn man von dem Schädelhaufen ausgeht, den er hat. Vielleicht weiß er, was an diesem Schädel so besonders ist.", sourceObjective = "Kehrt zu Nimboya im Basislager Grom'gol zurück und zeigt ihm den Lieblingsschädel von Eurem Schmetterschwanzjungen.\n\nBereitgestellter Gegenstand:", completion = "Was haben wir hier? Ein Schmetterschwanzjunges und ihren Goblinbegleiter.Hah!\n\nUnd weitaus wichtiger, was für einen Schädel habt Ihr da? Das war kein normaler Troll. Es war ein sehr großer Troll...\n\n<Nimboya klopft auf die Schädeldecke.>\n\n... und ein sehr starker. Mal sehen, was wir damit machen können.\n\nGeht nicht weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26324] = { id = 26324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist meine Kriegsflotte?", description = "Wir haben eine Karte von den Zugängen zum Schattenhochland. Unser Plan ist eindeutig: Wir werden uns mit unserer kompletten Streitmacht zeigen. Wenn die Orcs des Drachenmals unsere ganzen Truppen an ihrem Strand sehen, haben sie keine Wahl, außer sich mit uns zu verbünden und uns bei unserem Kreuzzug gegen den Schattenhammer zu unterstützen.\n\nDie Flotte wird im Bilgepier in Azshara zusammengebaut, doch sie kommen für meinen Geschmack viel zu langsam voran.\n\n{class}! Ihr seid geschickt darin, die Räder an meinen Kriegsmaschinen zu ölen. Sucht nach Kriegsfürst Krogg in Azshara und findet heraus, was da so lange dauert.", sourceObjective = "Sprecht mit Kriegsfürst Krogg am Bilgepier in Azshara.", completion = "Was? Noch eine Nachricht von Höllschrei? Sein Geduldsfaden ist dünner als Elfenhaar.\n\nHabt Ihr je mit Goblins zusammengearbeitet? Überall sind weitere versteckte Kosten. Unsere Schiffe liegen halb zusammengebaut im Hafen und unsere Luftflotte ist in alle Winde zerstreut.\n\nWenn diese Invasion tatsächlich stattfinden soll, brauche ich Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26325] = { id = 26325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für solche Dinge", description = "<Der Schädel spricht zu Euch.>\n\nIch lebe? Nein, ich lebe nicht... aber ich kann leben.\n\nEuer Raptor ist sehr schlau, wenn er meinen Schädel in einem Haufen so vieler Schädel gefunden hat. Zu Lebzeiten war ich ein starker, mächtiger Troll, ein Fürst unter den Trollen. Mit Eurer Hilfe kann ich wieder ein Fürst sein.\n\nDie Blutskalpe in Zuuldaia haben magische Fetische, die mir zur Rückkehr verhelfen können. Sie verstecken die Artefakte unter dem Sand. Euer Schmetterschwanzjunges wird diese Artefakte finden können, {name}... wenn Ihr sie habt, werft sie in den Kessel.", sourceObjective = "Lasst Euer Schmetterschwanzjunges 8 Fetische von Zuuldaia aufspüren.", progress = "<Der große Trollschädel taucht aus dem brodelnden Kessel auf.>\n\nWie viele konntet Ihr finden?", completion = "<Ihr fügt die Fetische dem Kessel hinzu.>\n\nJa... jaaaaa...\n\nMein Geist ist wieder stark, {name}, und ich bin bereit, in die Welt zurückzukehren. Jetzt brauche ich einen Körper.", sourceObjectiveStatus = "unverified-source-field" }
quests[26326] = { id = 26326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde unter unseren Füßen", description = "Nur noch ein Teil der Weltensäule fehlt, und der befindet sich in den Händen der Steinmutter selbst. Schlimmer noch, der Tempel wird von Elementaren und Riesen belagert. Selbst einem Narr dürfte klar sein, dass sie auf ihren Befehl hin handeln.\n\nGeht und stellt Euch den Elementaren im Nordwesten im Kampf. Beratet Euch mit Torunskar und Norsala und findet einen Weg, um mit ihren Anführern zu sprechen und die Weltensäule zu finden. Wir ziehen eine friedliche Beilegung vor, aber wir werden alles tun, was nötig ist, um den Riss zu schließen.", sourceObjective = "Sucht nach Erdenrufer Torunskar direkt nordwestlich des Tempels der Erde in der Zackenwüste.", completion = "Hey, Mann! Vielen Dank für Euer Kommen.\n\nWir waren auf diese Art von Angriff nicht vorbereitet. Wir haben den Schattenhammerkult erwartet, aber nicht die Elementare. Ich habe keine Ahnung, was sie so sehr in Aufruhr versetzt hat, dass sie sich plötzlich gegen uns wenden.\n\nIhr habt doch keine von ihnen getötet, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26327] = { id = 26327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambossar der Held", description = "Ihr verschwendet nur Eure Zeit, wenn Ihr jetzt mit mir reden wollt, <Junge/Mädchen>. Thargas Ambossar hält sich auf der anderen Seite dieser Wagen auf.\n\nIhr habt von ihm gehört, oder? Er hat an der Seite des Königs von Sturmwind den Thandolübergang gegen die Dunkeleisenzwerge verteidigt! Er ist einer der größten Helden von Eisenschmiede.\n\nAber jetzt steckt er bis zum Hals in Ärger! Geht zu ihm und lasst ihn wissen, dass Ihr helfen wollt. Aber haltet Abstand; er holt weit aus.", sourceObjective = "Redet mit Thargas Ambossar.", completion = "Seid gegrüßt! Wenn Ihr eine Waffe habt, könnt Ihr mir gern helfen, diese verrückten Narren loszuwerden!", sourceObjectiveStatus = "unverified-source-field" }
quests[26328] = { id = 26328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinige Beziehungen", description = "<Norsala legt die Hand auf den Boden, um Diamants Aufenthaltsort herauszufinden, springt jedoch sofort schockiert zurück.>\n\nMeine Güte! Das habe ich nicht erwartet. Diamant ist gar nicht weit entfernt. Als ich eine Verbindung zu ihm aufbaute, hat er geantwortet und mir gesagt, wo wir ihn finden können. Geht zum nordöstlichen Rand der Zackenwüste. Diamant erwartet Euch.\n\n{name}, seid vorsichtig. Es sieht Erdgeschöpfen zwar nicht ähnlich, einen Hinterhalt zu planen, aber es sah ihnen auch nicht ähnlich, den Tempel überhaupt zu belagern.", sourceObjective = "Findet Diamant den Geduldigen am nordöstlichen Rand der Zackenwüste.", completion = "Ah… Ihr müsst der {class} sein, den ich erwarte.\n\nAlso kommt Ihr im Namen des Irdenen Rings?", sourceObjectiveStatus = "unverified-source-field" }
quests[26329] = { id = 26329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und noch etwas", description = "So, dann werde ich meine Sachen packen und mich der nächsten Aufgabe widmen. Irgendwo gibt es immer etwas zu sprengen. Irgendwo gibt es einen Berg, der bewegt werden muss oder eine Schlucht, die gegraben werden muss. Dafür bin ich da.\n\nWürdet Ihr mir vielleicht noch einen Gefallen erweisen? Würdet Ihr diesen Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt bringen? Er sollte wissen, dass die Troggs seinem Volk in nächster Zeit keine Probleme mehr machen werden.", sourceObjective = "Bringt Jessups Bericht zu Hochtüftler Mekkadrill in Neu-Tüftlerstadt.", progress = "Willkommen zurück, {name}.", completion = "<Der Hochtüftler liest Jessups Bericht.>\n\nGroßartige Neuigkeiten! Ohne die Troggs können wir unsere Aufmerksamkeit endlich dem Ärger widmen, den Ritzelstoß veranstaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26330] = { id = 26330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist ein großer Troll?", description = "<Der Schädel spricht erneut.>\n\nMeine Seele ist bereit, doch mein Körper ist es nicht. Die Blutskalpe haben meinen alten Körper vor langer Zeit entweiht. Die Schrecken, die sie mir zugefügt haben... mein Geist sah dabei zu, als sie meinen Körper in Stücke rissen und... und... ich kann es nicht erzählen.\n\nIhr Häuptling, Gan'zulah, leitete diese grauenvollen Taten. Wenn ich mich recht erinnere, so war er ein starker, mächtiger Troll... ungefähr so groß wie ich. Was für ein interessanter Zufall.\n\nIhr wisst, was Ihr zu tun habt, {name}. Beeilt Euch.", sourceObjective = "Holt Gan'zulahs Leiche aus Zul'Kunda.", progress = "<Ihr hört die Stimme des Schädels:>\n\nGan'zulah...", completion = "Ihr habt Gutes getan, {name}. Es gilt nur noch eine Aufgabe zu erfüllen, bevor ich zurückkehren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26331] = { id = 26331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritzelstoß' Handlanger", description = "Unser alter Feind Thermadraht versucht uns mit allen Mitteln vom Wiederaufbau und der Rückeroberung Gnomeregans abzuhalten. Er hat einen seiner loyalsten Schergen, Razlo Ritzelstoß und einen Trupp bestrahlter Gnome ausgesandt, um uns zu terrorisieren.\n\nSie haben sich in einem alten Arsenal auf der Straße nach Norden verschanzt. Ritzelstoß' Techniker reparieren die Waffen dort. Wir müssen sie aufhalten, bevor die Mechanopanzer einsatzbereit sind. Geht zu Ritzelstoß' Arsenal und eliminiert alle Techniker, die Ihr findet.", sourceObjective = "Tötet 8 von Ritzelstoß' Handlangern in Ritzelstoß' Arsenal. Ihr könnt wahlweise bestrahlte Techniker oder Ritzelstoß' Kampfanzüge töten.", completion = "Das sollte Ritzelstoß ein wenig aufhalten, aber wir dürfen nicht ruhen, bevor er besiegt und das Frosthauchtal sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26332] = { id = 26332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mojo der Schädelspalter", description = "<Der Schädel spricht wieder.>\n\nDank Euch und Eurem Raptor habe ich meinen Körper. Wenn ich mich recht erinnere, so braucht Ihr und Euer Freund, der Hexendoktor, Mojo, um das Ritual abzuschließen.\n\nDie Blutskalpe haben Mojo in Zul'Kunda, aber es ist schwach. Das Mojo der Dunkelspeere wird auch nicht ausreichen. Nein... wir brauchen das Mojo der Schädelspalter. Ihr könnt sie auf der anderen Seite des Flusses östlich von hier finden.\n\nBeeilt Euch, {race}. Ich werde Euch zusehen...", sourceObjective = "Erhaltet 6 Mojos der Schädelspalter von Trollen der Schädelspalter in den Ruinen von Ziata'jai und den Ruinen von Balia'mah.", progress = "<Der große Trollschädel treibt im Kessel umher.>", completion = "<Ihr fügt das Mojo dem Kessel hinzu.>\n\nAusgezeichnete Arbeit, {race}. Ihr und Euer Raptor haben eine große Tat vollbracht. Hakkar wäre sehr erfreut...", sourceObjectiveStatus = "unverified-source-field" }
quests[26333] = { id = 26333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Panzer!", description = "Wir haben bereits einige Späher bei dem Versuch verloren, herauszufinden, was Razlo Ritzelstoß mit all den Mechanopanzern vorhat, die seine bestrahlten Techniker reparieren.\n\nWir dürfen nicht noch mehr Zeit verlieren. Wir müssen handeln, bevor Ritzelstoß seine Anhänger und seine Waffen auf uns hetzt.\n\nIn dieser Techno-Granate befindet sich genügend Sprengkraft, um die Mechanopanzer zu zerstören. Dann wird Ritzelstoß sie nicht mehr verwenden können. Nehmt sie mit nach Norden, auf die Straße, die zu Ritzelstoß' Arsenal führt, und vernichtet diese Panzer!", sourceObjective = "Benutzt die Techno-Granate, um 5 reparierte Mechanopanzer in Ritzelstoß' Arsenal zu vernichten.", completion = "Mekkadrill wird zufrieden sein, wenn er erfährt, dass Ihr Ritzelstoß davon abgehalten habt, seine Anhänger mit unseren alten Waffen auszurüsten. Wenn er die Mechanopanzer nicht einsetzen kann, wird er schwach und angreifbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26334] = { id = 26334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfürst Mandokir", description = "{race}. {race}, {race}, {race}... Ihr dachtet nicht, ich wäre Euch freundlich gesinnt, oder, {race}? Ah, ha, hahahaa!\n\nIhr habt Euren Zweck erfüllt. Ich bin ins Reich der Lebenden zurückgekommen und das nur dank Euch. Anstatt Euch zu töten werde ich Euch also ein Angebot machen.\n\nGebt mir den Raptor.\n\nIhr solltet bereits gemerkt haben, dass sie kein normaler Schmetterschwanz ist und ich brauche einen Ersatz für Ohgan. Tut, was ich sage, oder Ihr und Euer Hexendoktor werdet meine Wut zu spüren bekommen.", sourceObjective = "Bringt das Eierfragment eines Schmetterschwanz' zu Blutfürst Mandokir im Basislager Grom'gol.", progress = "Ich will nicht mehr als den Raptor, {name}. Gebt sie mir und Ihr und der Troll könnt weiterleben.", completion = "Gut, dass Ihr zu Sinnen kommt.\n\nVielleicht wollt Ihr mich ja mal in Zul'Gurub besuchen, {race}. Ich werde Euch im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26335] = { id = 26335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Marine startklar", description = "Höllschrei erwartet eine Armada von Schiffen für seinen Einmarsch, aber die Arbeiten hier hinken dem Zeitplan um Wochen hinterher. Die Kosten sind himmelhoch und die Qualität erbärmlich. Das Problem hier ist Korruption, {name}! Und ich brauche Euch, um dieses Übel auszumerzen.\n\nDie Feindbrecher, ein Kriegsschiff, das am nordwestlichen Pier liegt, sollte schon vor Tagen ausgestattet werden. Da ist etwas faul. Geht dorthin und überwacht den Bau selbst.\n\nFindet heraus, wer unsere Schiffsvorbereitungen unterbricht und setzt dem ein Ende!", sourceObjective = "Untersucht den Rumpf der Feindbrecher.", completion = "<Dies sind die Blaupausen für die Feindbrecher mit allen noch so kleinen Details.>\n\n<Ihr dreht und wendet die Dokumente und versucht, die Notizen, Bemerkungen und Korrekturen zu entziffern.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26336] = { id = 26336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wank O'Breen", description = "Ihr seid in Ordnung, {name}. Man trifft nur selten sogenannte Helden, die so weit entfernt von der Heimat tatsächlich wissen, was sie tun. Ich würde Euch gern etwas mehr Arbeit überlassen. \n\nIch habe einen Freund namens Wank O'Breen. Er kommandiert eine Piratenbesatzung, die Schwarzmeerräuber; das sind gute Jungs, respektabel für Piraten. Sie haben in Faldirs Bucht angelegt, die versteckt am Südstrand liegt.\n\nO'Breen wird Euch sicherlich einige lukrative Angebote machen können, wenn Ihr interessiert seid.", sourceObjective = "Findet Wank O'Breen in Faldirs Bucht im Arathihochland.", completion = "Ahoi, {class}. Jeder Freund von Skuerto ist auch mein Freund.\n\nHier gibt es eine Menge zu tun. Wir sitzen nicht in dieser Bucht und drehen Däumchen, weil wir das wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26337] = { id = 26337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagfertige Überredungskunst", description = "<Es ist offensichtlich, warum die Feindbrecher im Zeitplan hinterherhinkt. Alle zwei Tage nimmt ein Großknecht Änderungen an den Blaupausen vor.>\n\n<Am beunruhigendsten sind die letzten Änderungen. Den Arbeitern wurde befohlen, Nieten zu entfernen, um Kosten zu sparen!>\n\n<Ihr solltet einen der Bilgewässer Großknechte finden, die dafür verantwortlich sind und ein Exempel statuieren. Ansonsten kommen noch Mitglieder der Horde wegen der fehlerhaften Schiffe ums Leben!>", sourceObjective = "Sucht einen Bilgewässer Großknecht im Bilgewasserhafen und mischt ihn ein wenig auf.", completion = "Also haben sie versucht, bei den Produktionskosten zu schummeln? Völlig inakzeptabel!\n\nIch bin froh, dass Ihr ihnen ein wenig Verstand eingeprügelt habt. Wenn dieser Großknecht sein Wort hält, ist unsere Flotte rechtzeitig für unsere Invasion seetauglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[26338] = { id = 26338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevölkerungskon-Trolle", description = "Ich habe gehört, dass Ihr bald nach Zul'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe für Euch, wenn Ihr dort seid.\n\nDie Bevölkerung der Trolle ist zu groß für Schlingendorntal geworden. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie kommen aus den Ruinen und machen sich im Dschungel breit. Das stört das natürliche Gleichgewicht der Gegend. Dieses Gleichgewicht muss jetzt wiederhergestellt werden.\n\nZul'Kunda ist die Hochburg der Blutskalpe. Dort werdet Ihr die hochrangigsten Blutskalpe finden. Reduziert ihre Zahlen und kehrt zu mir zurück.", sourceObjective = "Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.", completion = "Das Gleichgewicht ist erst einmal wiederhergestellt. Wir werden uns vielleicht zu einem späteren Zeitpunkt wieder an Euch wenden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26339] = { id = 26339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen in Bräuhall", description = "Während Hochtüftler Mekkadrill, seine militärischen Berater und ich die Pläne für den Angriff auf Razlo Ritzelstoß durchgehen, ist mein Assistent schon einmal nach Bräuhall gereist, um mit den Vorbereitungen zu beginnen.\n\nFolgt der Straße nach Südosten aus der Stadt hinaus, um nach Bräuhall zu gelangen. Findet Jarvi Schattenschritt nach Eurer Ankunft und findet heraus, ob er Hilfe benötigt. Unsere Zwergencousins haben einen Trupp Gebirgsjäger aus Eisenschmiede abgestellt, um uns im Kampf gegen Ritzelstoß zu unterstützen.", sourceObjective = "Sprecht mit Jarvi Schattenschritt in Bräuhall.", completion = "Ach ja, Kelsey sagte mir, Ihr würdet bald eintreffen. Es gibt viel zu erledigen, bevor wir uns Ritzelstoß stellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26340] = { id = 26340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd", description = "Von allen Plätzen in Azeroth stecke ich ausgerechnet hier in Grom'gol fest. Es ist ein Wunder, dass ich noch am Leben bin, mit den gefährlichen Wildtieren, den Überfällen auf Karawanen und der dauernden Bedrohung durch Angriffe der Trolle.\n\nEs könnte schlimmer sein. Hier in Grom'gol gibt es wenigstens Mauern und Wächter. Eine Gruppe Jäger hat nördlich von hier mitten im Dschungel ihr Lager errichtet!\n\nIch sehe die ganze Zeit, wie Leute dort hingehen. Wenn Ihr nach Ärger sucht, solltet Ihr in diese Richtung aufbrechen. Ich bleibe in Grom'gol.", sourceObjective = "Meldet Euch bei Barnil Steinkrug bei Nesingwarys Expedition im Nördlichen Schlingendorntal.", completion = "Hmm? Ich heiße Barnil. Und wer seid Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26341] = { id = 26341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steinsplitter", description = "Ich habe das ganze Hochland bereist, {name}, und dabei etwas gefunden, für das ich keine Erklärung habe.\n\nNordöstlich von hier gibt es einen Steinkreis, ähnlich denen, die man überall in Arathi findet... nur deutlich größer und beeindruckender. Er wurde in den Berg hineingebaut.\n\nUnter uns: Ich hörte Stimmen, als ich dort war. Das Flüstern der Erde. Solltet Ihr neugierig geworden sein, könnt Ihr Euch das selbst ansehen...", sourceObjective = "Untersucht die Splitter von Myzrael.", completion = "<Die Splitter pulsieren sanft; ein Flüstern windet sich langsam durch Euren Kopf.>\n\nHilfe...", sourceObjectiveStatus = "unverified-source-field" }
quests[26342] = { id = 26342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmalerei", description = "Uns liegen verlässliche Informationen vor, laut derer Razlo Ritzelstoß eine Verteidigungsstellung auf der Insel in der Mitte des gefrorenen Eiswellensees errichtet hat. Hinzu kommt, dass er sich mit zahlreichen Späh-o-Bots umgibt, die mögliche Angreifer entdecken sollen.\n\nWir können uns Ritzelstoß erst stellen, wenn diese Späher zerstört worden sind. Dieses Gerät schießt eine dunkle, klebrige Farbe ab. Sie wird die optischen Sensoren von Ritzelstoß' Späh-o-Bots verdecken. Schaltet sein Frühwarnsystem damit aus.", sourceObjective = "Benutzt den Farbinator, um 5 von Ritzelstoß' Späh-o-Bots die Sicht zu nehmen.", completion = "Ihr habt es uns gerade ermöglicht, Ritzelstoß zu überrumpeln. Hervorragende Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26343] = { id = 26343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angebot und Nachfrage", description = "Der beste Ledermacher der Südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.\n\nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!\n\nGerade habe ich eine Bestellung von Direktor Quizvox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.\n\nFür die Grundform benötige ich Krokiliskenhäute von den Krokis entlang des Flusses im Nördlichen Schlingendorntal.", sourceObjective = "Bringt 2 große Flusskrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.", progress = "Meine Ausrüstung ist startklar, {name}, ich warte nur noch auf die Häute. Wir wollen Quizvox ja nicht warten lassen.\n\nEs ist für niemanden gut, wenn der Cheferfinder des Tüftlerverbands unzufrieden ist.", completion = "Diese Häute sollen genügen. Ihre Qualität ist nicht allzu wichtig, da sie ja nur die innere Schicht der Stiefel bilden, aber sie sollten schon bequem sein.\n\nWenn sie ein bisschen zu steif sind, verwende ich ein wenig Tigerblut, um sie aufzuweichen. Kleines Betriebsgeheimnis, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26344] = { id = 26344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Zusammenbau benötigt", description = "Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir brachtet, werden leider nicht für die inneren Schichten ausreichen.\n\n\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen, und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!\n\nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokis holen, die um den Nazferitisee leben.", sourceObjective = "Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik bei Nesingwarys Expedition.", progress = "Drizzliks Exzelsiorlederstiefel, feinste Handwerksarbeit, Stiefel aus 100 Prozent Salzwasserkrokiliskenhaut von höchster Qualität. Es gibt nichts Besseres!\n\nSo eine tolle Beschreibung sucht ihresgleichen, was?\n\nOder habt Ihr vielleicht schon diese Häute für mich?", completion = "Meine Stiefel... sie sind 'n bisschen wie Würstchen, {name}. Sehen gut aus und schmecken auch so. Ich sag Euch, dass sie mit dem allerbesten Fleisch und feinsten Zutaten gefüllt sind und Ihr esst sie und Ihr liebt sie.\n\nEs ist sicherer - und schmackhafter -, wenn Ihr mir einfach nur traut und nicht allzu viele Fragen stellt, was wirklich drin ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26345] = { id = 26345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exzelsior", description = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.\n\nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Ihr findet sie im Süden, in der der Nähe der Grenze am Kap.", sourceObjective = "Bringt die Haut eines alten Krokilisken zu Drizzlik bei Nesingwarys Expedition.", progress = "Irgendwo habe ich gelesen, dass die älteren Krokilisken langsam aussterben... schlecht für mein Geschäft, was?\n\nEgal, ich hoffe, Ihr habt die Haut eines alten Salzwasserkrokilisken für mich!", completion = "Großartig! Dank Eurer Hilfe habe ich diese Bestellung fertig und kann sie mit dem nächsten Schiff zu Direktor Quizvox nach Lorenhall abschicken. Sogar noch vor der Frist!\n\nFür all Eure harte Arbeit, hier, ich habe einige zusätzlich gemacht, nehmt Euch ein Paar. Geht auf Drizzliks Rechnung.\n\nUnd denkt dran, nirgends gibt es Stiefel, die so fein, wie Stiefel von Drizzliks Exzelsiorlinie ganz allein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26346] = { id = 26346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzraels Geschichte", description = "Als der Stein verstummt, hallt ein ungutes Gefühl in Euch nach. Etwas stimmt nicht.\n\nVielleicht solltet Ihr Skuerto erzählen, was Ihr bis jetzt getan habt.", sourceObjective = "Kehrt zu Skuerto in der Zuflucht im Arathihochland zurück.", completion = "Ihr müsst nicht mehr sagen, {name}. Ich habe mich mit einem... \"alten Freund\" unterhalten, während Ihr unterwegs wart. Ich hätte Euch nicht zu diesen Splittern schicken sollen.\n\nEs war ein schwerer Fehler von uns beiden, uns damit zu beschäftigen. Zum Glück konnte ich meinen Freund Gerrig davon \"überzeugen\", mir zu erklären, was in diesem Fall zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26347] = { id = 26347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrer der Flamme", description = "Die Nacht, als die Leuchtturmwärterfamilie starb, war schrecklich. Ich musste hilflos zusehen, während Trübauge der Alte den Angriff anführte. Aber die Vergangenheit lässt sich nicht ändern und meine Hauptsorge gilt jetzt den Leben der Seeleute auf dem Großen Meer. Ihre Schiffe kommen den gefährlichen Felsen entlang der Küste oft zu nahe. Da niemand mehr auf das Leuchtfeuer aufpasst, fällt diese Aufgabe jetzt mir zu.\n\nHelft mir, die Flamme am Leben zu erhalten, indem Ihr mir Schluchtenschlamm von den Schleimen im Rasenden Schlund im Nordosten bringt.", sourceObjective = "Bringt 5 Schluchtenschlamme zu Kapitän Grausohn am Leuchtturm von Westfall.", progress = "Das Feuer wird ohne Schlamm nicht sehr lang brennen, {name}. Früher haben wir Öl benutzt, aber das war schwer zu beschaffen!", completion = "Ich muss Euch für Euren Mut loben, {class}. Die Felsen an der Küste Westfalls werden dank Eurer harten Arbeit beleuchtet sein. Solange das Feuer brennt, werden viele Leben verschont bleiben.\n\nMein Tod an diesem Strand war unnötig. Meine Aufgabe im Jenseits ist es, dafür zu sorgen, dass niemand dem gleichen Schicksal erliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26348] = { id = 26348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Küste", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das Große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet Gezeitenjäger und Orakel, dann sorge ich dafür, dass Ihr belohnt werdet.", sourceObjective = "Tötet 7 Murlocgezeitenjäger und 7 Murlocorakel.", completion = "Gut gemacht, {name}. Ihr habt ein ziemliches Talent für den Kampf. Dank Euch ist die Küste Westfalls jetzt sicherer als zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26349] = { id = 26349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung an der Küste", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Trübauge der Alte die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Trübauge brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Trübauge den Alten, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", sourceObjective = "Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten.", progress = "Habt Ihr der Bedrohung namens Trübauge schon den Garaus gemacht? Er ist gesehen worden, wie er an der Küste von Westfall umherstreifte.\n\nKehrt zu mir zurück, sobald das garstige Ungeheuer tot ist.", completion = "Also ist Trübauge, dieser garstige Heide, endlich tot. Gut gemacht, {name}. Durch Eure Hand ist ein Leben beendet worden, doch vielleicht wurden gerade durch diese Tat viele weitere Leben gerettet. So gefährlich das Große Meer auch ist, diese Nacht wird es dank Eurer heldenhaften Tat ein wenig sicherer sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26350] = { id = 26350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priesterin Hu'rala", description = "Ich danke Euch, {name}. Ich weiß, ich hättet mich nicht retten müssen und... nun, ich bin Euch sehr dankbar.\n\nDie Rückkehr von Blutfürst Mandokir ist eine schreckliche Nachricht. Er wurde vor vielen Jahren in Zul'Gurub getötet und wir dachten, es wäre das Ende von ihm und seinesgleichen. Die Trolle von Zul'Gurub haben versucht, ein abscheuliches, furchtbares Ritual durchzuführen. Wenn Mandokir lebt, so gibt es Grund zur Annahme dass er nicht der Einzige ist.\n\nDie Trolle in Bambala östlich von hier könnten mehr wissen. Sprecht mit der Priesterin.", sourceObjective = "Sprecht mit Priesterin Hu'rala in Bambala im Nördlichen Schlingendorntal.", completion = "Mandokir lebt, ja.\n\nIhr seid dafür verantwortlich, ja.\n\nIhr könnten ihn noch aufhalten können, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26351] = { id = 26351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankensicht", description = "Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.\n\nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.\n\nIhr habt Euch angefreundet mit Raptor: Ohgan'aka: Tochter von Ohgan.\n\nUm Freundschaft zu stärken, brauchen wir Federn.\n\nGeht nach Westen und Ihr werdet Federn finden, ja.", sourceObjective = "Erhaltet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.", progress = "Raptor namens Ohgan'aka immer noch Eure Freundin.", completion = "Ihr bringt Federn, ja.\n\nIhr könnt Anweisungen folgen, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26352] = { id = 26352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cozzles Vorhaben", description = "Ich mag den Dunkelspeeren abstammen, aber ich habe meine Kindheit hier im Schlingendorntal verbracht. Ich habe jedes Fleckchen des Schlingendorntals gesehen; es gibt jedoch nichts schlimmeres als die Zerstörung, die die Venture Company dem Flussbett zugefügt hat.\n\nUnd es wird noch schlimmer, weil Großknecht Cozzle und seine Arbeiter ihre Aktivität gesteigert haben. Ich fürchte, sie haben etwas Neues vor. Schließt die Aufgabe ab, an der ich gescheitert bin, {name}: tötet Cozzle, nehmt seinen Schlüssel und stehlt die Blaupausen aus seinem Heim.", sourceObjective = "Nehmt Cozzles Schlüssel dem Großknecht Cozzle ab und erhaltet die Treibstoffreglerblaupausen.", progress = "Was die Venture Company dem Schlingendorntal angetan hat kann nicht verziehen werden.", completion = "Ein Treibstoffregler? Das scheint wichtig zu sein. Zumindest hoffe ich das.\n\nWir werden die Unternehmungen der Venture Company nicht beendet haben, aber wenigstens haben wir sie verlangsamt. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26353] = { id = 26353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sanders in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", sourceObjective = "Findet Käpt'n Sanders' Schließkiste und sucht darin nach dem nächsten Hinweis.", completion = "Der Schließkasten knarrt als Ihr ihn langsam öffnet. Sand und Wasser scheinen der einzige Inhalt zu sein. Aber halt! Eine kleine Krabbe huscht mit einem Hinweis auf den Schatz in den Scheren davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26354] = { id = 26354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Osten halten. Im Osten die Steilhänge hoch, dann weiter nach Osten bis zur Straße. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr 'n altes Fass mit Eurem nächsten Hinweis drin.", sourceObjective = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.", progress = "Das sieht wie das richtige Fass aus.", completion = "Gut gemacht! Das war der nächste Schritt auf der Schatzsuche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26355] = { id = 26355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch den Henkelkrug mal genau anguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", sourceObjective = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.", progress = "Es steckt ein Hinweiszettel in dem leeren Henkelkrug.", completion = "Ihr seid bei Eurer Schatzsuche auf dem richtigen Weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[26356] = { id = 26356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Sanders' versteckter Schatz", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders' Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", sourceObjective = "Findet Käpt'n Sanders' Truhe und öffnet sie. Darin befindet sich Eure Belohnung.", progress = "Der verlorene Schatz von Käpt'n Sanders wartet!", completion = "Die Scharniere der alten Truhe sind rostig, aber sie funktionieren noch. Ihr brecht die Truhe auf und nehmt die Beute heraus.\n\nHerzlichen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[26357] = { id = 26357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesichter des Bösen", description = "Die Blutfratzen haben ihre Tikimasken überall in Jintha'Alor an die Mauern gehangen. Die Geister werden nicht mehr lange über sie wachen.\n\nNehmt die Fackel und kämpft Euch durch die Blutfratzen, {class}. Zündet ihre Tikimasken an. Ich werd zusehen, wie ihre Abwehr- und Schutzzauber vergehen und ihr ketzerischer dunkler Voodoo in Rauch aufgeht.", sourceObjective = "Zündet mit der Tikifackel 8 Tikimasken in Jintha'Alor an.", completion = "Was für'n schöner Anblick. Die Hoffnungen des Feindes verbrennen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26358] = { id = 26358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Luftwaffe startklar", description = "Ich habe Höllschrei persönlich garantiert, dass seine Luftflotte diese Woche fertig wird, aber unser Flaggschiff, die Speer von Durotar, hat immer noch keine Haupttriebwerke.\n\nFliep hat mir letzte Woche ein niegelnagelneues Triebwerk versprochen. Geht zu ihrem Schrottplatz hinter der Bank und findet den Grund für die Verzögerung heraus.\n\nDie Luftflotte erwartet uns, {name}!", sourceObjective = "Sucht nach Fliep auf ihrem Schrottplatz im Bilgewasserhafen in Azshara.", completion = "<Fliep wischt sich das Gesicht ab und verschmiert sich dabei gehörig die Wange mit Schmieröl.>\n\nWas? Der Kapitän hat WAS gesagt?\n\n<Sie schwingt bedrohlich ihre Rohrzange.>\n\nEs ist SEINE Schuld, dass dieses Monstrum von Triebwerk verspätet ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[26359] = { id = 26359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht Raptor", description = "Wir haben Federn, ja.\n\nWir haben <den/die> {class}, ja.\n\nSprecht mit Priesterin, wenn bereit.", sourceObjective = "Sprecht mit Priesterin Hu'rala in Bambala, um am Ritual der Gedankensicht teilzunehmen.", completion = "Was hat Priesterin Euch gesagt?\n\nRaptor ist Tochter von Ohgan, Erbe von Mandokir.\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26360] = { id = 26360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankenkontrolle", description = "Gedankensicht nicht genug, nein.\n\nGedankenkontrolle viel mächtigere Magie, ja.\n\nMächtige Magie braucht mächtige Reagenzien und Trollhirn ist mächtiges Reagenz.\n\nBraddok in Zul'Mamwe sehr intelligent, ja.\n\nGeht nach Süden und untersucht Braddoks großes Gehirn.", sourceObjective = "Erhaltet Braddoks Riesengehirn von Braddok in Zul'Mamwe.", progress = "Riesenzauber brauchen Riesenhirne, ja.", completion = "Passt auf, nächster Teil schwierig, ja.\n\nScheitern sehr möglich, ja.\n\nAber {name} und {name}'aka werden wiedervereint... ja, werden sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26361] = { id = 26361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoots Samophlang", description = "Es war der Kapitän, der darauf bestanden hat, dass die neuen Triebwerke ein Induktionssamophlang haben.\n\nSo etwas wurde noch nicht einmal erfunden!\n\nIch habe Smoot damit beauftragt, ein Induktionssamophlang auf Basis von gestohlenen Zeichnungen der Venture Company zu entwerfen. Endlich ist es ihm auch gelungen, ein funktionierendes Modell zu bauen.\n\nDoch jetzt, wo er das Samophlang hat, ist er vor lauter Macht ganz berauscht. Er schleift es in der ganzen Stadt mit sich herum, wie ein Besessener.\n\nVersetzt Smoot eine Tracht Prügel und schnappt Euch mein Samophlang, {name}.", sourceObjective = "Findet Smoot im Bilgewasserhafen. Stellt ihn und besorgt Euch das Induktionssamophlang.", progress = "Smoot ist ein hervorragender Ingenieur.\n\nEin Samophlang kann aus 30 Metern Entfernung töten, wenn die Reduktionskaliphraketen falsch ausgerichtet sind.", completion = "Ausgezeichnet! Ich sollte dieses Triebwerk noch in dieser Stunde samophlanginiert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26362] = { id = 26362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid Raptor", description = "Gedankenkontrolle sehr mächtig, ja.\n\nMit Glück könnt Ihr Ohgan'aka helfen, aus Zul'Gurub zu fliehen.\n\nDann wird Ohgan'aka wieder {name}'aka werden!\n\nSprecht mit Priesterin, ja, und helft {name}'aka bei Flucht.", sourceObjective = "Sprecht mit Priesterin Hu'rala und helft dem gefangenen Schmetterschwanzjungen bei der Flucht aus Zul'Gurub.", completion = "Sehr schade, ja.\n\nDies ist der Wille der Geister, ja.\n\nWenn Ihr stärker seid, werdet Ihr vielleicht nach Zul'Gurub gehen und deine {name}'aka von Mandokir zurückholen, ja.\n\nDoch erst einmal gibt Euch Priesterin dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26363] = { id = 26363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsgipfel", description = "Ihr wart im Vorgehen gegen ihre Krieger sehr erfolgreich, {name}. Ich möchte, dass Ihr den Gipfel von Jintha'Alor untersucht.\n\nWir waren auf den härtesten Kampf vorbereitet, darauf, ihren dunklen Altar zu stürmen, aber es ist zu leise. Kein Geräusch weit und breit. Es könnte eine furchtbare Falle sein und jemand, der stark genug ist, sollte sich dort umsehen, bevor wir alle gesammelt einlaufen.\n\nWenn es keine Falle sein sollte... würde es mich auf jeden Fall auch interessieren, was dort los ist. Bringt mir jegliche Hinweise, die Ihr finden könnt.", sourceObjective = "Sammelt 8 Spinnengötzen der Blutfratzen auf dem Gipfel von Jintha'Alor.", progress = "Was habt Ihr gefunden?", completion = "Tot? Alle, um den ganzen Alter herum? Und sie hatten diese Spinnengötzen bei sich...\n\nEine Massenopfergabe. Sie haben Sharda ihre Leben geopfert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26364] = { id = 26364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit Ritzelstoß!", description = "Unsere Cousins, die Zwerge von Eisenschmiede, haben sich bereit erklärt, uns im Kampf gegen Razlo Ritzelstoß zu unterstützen. Gebirgsjäger Steinschleifer ist ein Veteran, der Dun Morogh gut kennt. Er und Hochtüftler Mekkadrill halten sich auf einer kleinen, schneebedeckten Insel im Eiswellensee nördlich von hier bereit. Trefft sie dort und sagt dem Hochtüftler Bescheid, wenn Ihr bereit seid, dem Verräter Ritzelstoß entgegenzutreten.\n\nNehmt dieses orbitale Zielgerät und benutzt es während der Schlacht. Es wird die Spezialwaffen des Hochtüftlers zum Ziel führen.", sourceObjective = "Besiegt Razlo Ritzelstoß. Sprecht mit Hochtüftler Mekkadrill auf dem Eiswellensee, wenn Ihr bereit seid, den Kampf zu beginnen.", completion = "Endlich sind wir frei von Razlo Ritzelstoß und seinen Störungen! Nach der Niederlage von Ritzelstoß und seinen Truppen, kann Thermadraht es sich nicht mehr leisten, weitere seiner Anhänger an die Oberfläche zu schicken. Ich kann den Tag, an dem wir ihn endgültig besiegen werden, kaum erwarten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26365] = { id = 26365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Rotkammgebirge!", description = "Die Lage hier ist zwar schlimm, aber in anderen Gegenden bebt es wortwörtlich nach dem großen Aufruhr immer noch.\n\nIch habe hier einen Bericht von Wachhauptmann Parker aus dem Rotkammgebirge, eines unserer Gebiete östlich vom Wald von Elwynn. Er ersucht die Hilfe eines Helden.\n\nSo, wie wir im Moment aufgestellt sind, kann ich keine weiteren Truppen losschicken. Könnt Ihr Parker aufsuchen und sehen, was er braucht? Ihr könnt Wachhauptmann Parker auf dem Turm bei den Drei Ecken finden.", sourceObjective = "Meldet Euch bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge.", completion = "Ich habe gehört, dass Westfall wirklich in der Klemme steckt.\n\n<Parker sieht Euch nicht einmal an, als er mit Euch spricht.>\n\nNun, wir haben hier selbst Probleme. Seht Ihr die Gnolle dort? Es sieht so aus, als haben sie wieder etwas vor. Das gefällt mir nicht. Das gefällt mir überhaupt nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26366] = { id = 26366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfprämie", description = "Umboda von den Blutfratzen ist einer ihrer stärksten Krieger und ein kranker Schlächter.\n\nEr sammelt und benutzt die Köpfe aller, die vor ihm fallen, als Schmuck, Belohnungen... und sogar Waffen! Es ist an der Zeit, dass er fällt.\n\nFindet Umboda Dreikopf, tötet ihn und bringt mir SEINEN Kopf! Wir werden sehen, wie die Blutfratzen kämpfen, wenn wir seinen Kopf über ihre Mauern werfen!", sourceObjective = "Besiegt Umboda Dreikopf und holt Euch seinen Kopf.", progress = "Zeigt ihn her!", completion = "Der Ausdruck von Angst und Verwirrung in seinem Gesicht... das ist genau das, was er verdient hat! Jetzt müssen wir nur noch sicherstellen, dass alle Blutfratzen so einen Gesichtsausdruck bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26367] = { id = 26367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longos Rache", description = "Ongo'longo war einer von uns. Außenseiter mögen ihn einen Terrortroll nennen, aber er war ein Bruchhauer und ein stolzer Krieger, so wie wir auch!\n\nDann haben die Blutfratzen ihn gefangen genommen. Sie halten ihn gefesselt in einer Grube oben in Jintha'Alor und zwingen ihn, zu ihrer kranken Unterhaltung zu tanzen.\n\nKeine Ketten können Ongo'longo halten. Ihr müsst nur sein Temperament aufwecken. Bekämpft ihn, bis er sich genug ärgert, um sich an sein wahres Ich zu erinnern und die Fesseln sprengt... und dann geht ihm schnell aus dem Weg!", sourceObjective = "Bekämpft Ongo'longo bis er seine Fesseln sprengt.", completion = "Ich wünschte, ich hätte es selbst sehen können, {name}. Ich muss die Geschichte auch von Ongo'longo selbst hören, wenn wir hier fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26368] = { id = 26368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftige Geheimnisse", description = "Von diesem interessanten Gift wird es noch mehr geben, wenn Shadra gerufen wurde.\n\nSeid nicht so überrascht... Die Verlassenen haben diese Länder schon seit längerem untersucht und wir haben die Königin des Gifts hier mindestens einmal gesehen. Ihre Gifte haben sich in der Vergangenheit als recht nützlich herausgestellt.\n\nUnd sie werden sich der Horde erneut als nützlich erweisen. Seid so nett und holt so viel Gift, wie Ihr von der Brut von Shadra erhalten könnt, die in der Höhle auf dem Gipfel sind... Ihr werdet ohnehin voll davon sein, wenn Ihr die Höhle betretet.", sourceObjective = "Erhaltet 6 Giftprobe der Shadrabrut von der Brut von Shadra in Jintha'Alor.", progress = "Habt Ihr das Gift...?", completion = "Mmh, ja... dieser alte, wohlbekannte Geruch.\n\nIhr habt den Verlassenen und der Horde gute Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26369] = { id = 26369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt die Bewahrerin", description = "Kotonga hat mir von Shadra berichtet. Sie ist die Giftkönigin, die Loa der Spinnen, in der Dunkelheit verehrt. Falls die Blutfratzen vorhaben, Rituale durchzuführen, so werde ich dies zu verhindern wissen.\n\nUntersucht die Höhle hinter dem Altar oben auf Jintha'Alor. Tief in der Höhle könnte sich noch eine Bewahrerin Shadras verstecken. Tötet sie und nehmt alles, was sie bei sich hat, damit wir herausfinden können, was dort vor sich geht.", sourceObjective = "Tötet Morta'gya die Bewahrerin und erhaltet die Tafel von Shadra.", progress = "Durchsucht ihren Leichnam. Ich möchte nicht, dass von den Blutfratzen gelegte Fallen von den Toten verdeckt werden.", completion = "Die Teile sind zersprungen und die Bewahrerinnen wurden getrennt... nun gut.\n\nDas ist das Ritual, um Shadra zu rufen. Sie scheinen es nicht abgeschlossen zu haben. Es sollte zerstört werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[26370] = { id = 26370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zur Späherkuppe", description = "Die Bruderschaft der Defias sollte man nicht auf die leichte Schulter nehmen, {name}. Was Ihr da gesehen habt, war die Geburtsstunde einer skrupellosen Verbrecherorganisation, die vor nichts Halt machen wird, bevor Sturmwind nicht in Schutt und Asche liegt.\n\nIch möchte, dass Ihr zur Späherkuppe zurückkehrt und Gryan wissen lasst, dass ich ihm Truppen schicke. Ich hoffe, es ist noch nicht zu spät.", sourceObjective = "Erstattet Marschall Gryan Starkmantel an der Späherkuppe in Westfall Bericht.", completion = "Fünf Jahre Arbeit innerhalb von fünf Minuten zu Asche verbrannt. Verfluchte Defias!\n\nUnd das ist erst der Anfang, {name}! Wir haben einen langen, anstrengenden Weg vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26371] = { id = 26371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende des Kapitän Grausohn", description = "Habt Ihr von Kapitän Grausohn gehört? Einige sagen, er ist die Erfindung eines betrunkenen Seemannsgehirns, aber jeder in Westfall wird Euch sagen, dass Grausohn existiert! Er ist ein Geist, der den Leuchtturm von Westfall ganz im Westen, vor der Endlosen Küste, heimsucht.\n\nWagt Ihr es, das zu untersuchen?", sourceObjective = "Findet Kapitän Grausohn beim Leuchtturm von Westfall in Westfall.", completion = "Ja... Ich war auch einst aus Fleisch und Blut, genau wie Ihr, mein Junge. Bis zu dem schicksalsträchtigen Tag, als die Murlocs den Leuchtturm angriffen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26372] = { id = 26372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Tests vor dem Flug", description = "Dieses neue Triebwerk ist extrem schnell. Und gefährlich. Ich würde es \"brisant\" nennen.\n\nGenau so mag der Kapitän es.\n\nRennt schnell den Hügel hinauf und sagt ihm Bescheid, dass ich dieses Schätzchen jetzt einbaue und er sich auf der Baustelle mit mir treffen soll.", sourceObjective = "Sprecht mit Kapitän Krazz im Bilgewasserhafen in Azshara.", completion = "Mein Luftschiff hat Triebwerke? Endlich!\n\nJetzt können wir uns wieder in die Lüfte schwingen!\n\nSobald die Boden- und Seetruppen bereit sind, werden wir den Himmel über dem Schattenhochland in Brand stecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26373] = { id = 26373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Kharanos", description = "Einige der Gebirgsjäger unter Steinschleifers Kommando haben mir von den Problemen draußen in Kharanos berichtet. Als die Troggs die Höhle der Frostmähnen eroberten, sind die überlebenden Trolle anscheinend nach Westen, bis ins Herz der Zwergenheimat geflohen.\n\nJetzt bedrohen sie die Zwergenstadt Kharanos. Die Zwerge dort brauchen wohl dringend Hilfe. Warum reist Ihr nicht nach Kharanos und stellt Euch Hauptmann Tharran vor? Folgt der Straße, die nach Osten aus Bräuhall herausführt und folgt ihr, bis Ihr die Stadt seht.", sourceObjective = "Sprecht mit Hauptmann Tharran in Kharanos.", completion = "Wenn der Geheimdienst von Gnomeregan Euch empfiehlt, müsst Ihr einen sehr guten Eindruck gemacht haben. Eure Hilfe können wir hier gut gebrauchen, da wir reich an Feinden, aber arm an Gebirgsjägern sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26374] = { id = 26374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Bodentruppen startklar", description = "Es war keine gute Idee, die Truppen in dieser pulsierenden Goblinmetropole einzuberufen. Jedes Laster, das man mit Gold kaufen kann, ist nur eine Armlänge entfernt. Unsere mächtigen Veteranen sind völlig zügellos und hauen ihren über Jahre mühsam in Nordend verdienten Sold auf den Kopf. Die Stadt droht, zusammenzubrechen!\n\nKönntet Ihr durch die Stadt streifen und die fahnenflüchtigen Nachzügler einsammeln?\n\nMeine Krieger der Axtbeißer sind auf dem Schlachtfeld unschlagbar, aber ich lasse nicht zu, dass sie ihren Uniformen während ihres Landgangs Schande bringen.", sourceObjective = "Durchsucht den Bilgewasserhafen und überzeugt 12 fahnenflüchtige Grunzer, sich zum Dienst zu melden.", completion = "Danke, {name}! Die meisten meiner Soldaten haben sich bereits zum Dienst gemeldet, einige leider etwas lädiert.\n\nBilgewässer Nächte sind lang.\n\nEin frischer Kampf im Schattenhochland sollte ihre Disziplin jedoch wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26375] = { id = 26375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Steine", description = "Die Schattenhammerkultisten rauben meine Steinlinge. Sie stehlen ihre Energie und foltern sie. Sie nehmen ihnen die Essenz, die dem Stein Leben einhaucht.\n\nBitte, {race}, befreit meine Steinlinge. Weder Diamant noch ich verfügen über das Fingerspitzengefühl, ihre Ketten zu zerschlagen, ohne sie zu verletzen. Aber wir haben ein Werkzeug, das Ihr vielleicht verwenden könnt.\n\nNehmt dies. Sprengt ihre Ketten und befreit sie.", sourceObjective = "Benutzt den filigranen Kettensprenger, um 6 Quarzsteinlinge zu befreien.", completion = "Ihr seid sehr großzügig, {race}. Ihr gebt der Erde, die Euch so viel gibt, etwas zurück. Ihr habt meinen Respekt. Mit der Zeit werdet Ihr auch sicher den Respekt der Steinlords erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26376] = { id = 26376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefsitzender Hass", description = "Ich würde mich ja für Boden entschuldigen, aber Stein ist stur.\n\nOhne den nagenden Zahn der Zeit weicht er nicht von seinen Gewohnheiten ab.\n\nDie Steinlords, darunter Boden und ich, haben die Aufgabe, die Weltensäule zurückzuholen.\n\nDoch wir sind uns uneinig.\n\nIch möchte Euch gerne meine Geduld zuteilwerden lassen, {race}.\n\nBeweist, dass Ihr kein Verbündeter des Schattenhammerkults oder Todesschwinges seid...\n\nTragt unseren Hass zu ihnen.\n\nSchlagt schnell zu, wo wir es nicht können.\n\nHabt Ihr Erfolg, werde ich Euch zuhören.", sourceObjective = "Tötet Dragul Riesenschlächter und 12 Schattenhammerkultisten an Lorthunas Tor.", completion = "Ich habe Euch beobachtet, {race}.\n\nIhr scheut Euch nicht, das Blut des Schattenhammers zu vergießen.\n\nDaher bin ich geneigt, Euch bis zu einem gewissen Grad zu vertrauen.\n\nEs ist ein Anfang.\n\nAlles zu seiner Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26377] = { id = 26377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loser Grund", description = "Der Schattenhammerkult baut in der Nähe seines Lagers Jadekristalle ab.\n\nDumm…\n\nWaghalsig…\n\nSammelt die abgebauten Kristalle. Bringt sie in die Mitte ihres Lagers. Verteilt sie auf dem Boden.\n\nDie Schwingungen und der aufgeladene Kristall werden die Tunnelgräber auf sie hetzen.\n\nSie werden lernen, die Erde zu respektieren...\n\nStück für Stück...\n\nFels für Fels...\n\n... mit der Zeit.", sourceObjective = "Sammelt 6 Jadekristallformationen und kombiniert sie miteinander. Verteilt sie dann im Lager an Lorthunas Tor.", completion = "Die Zeit bringt allen Respekt bei.\n\nDem kleinsten Kiesel.\n\nDem größten Berg.\n\nDem starrsinnigsten Kultisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26378] = { id = 26378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Westfall!", description = "In Westfall herrschen harte Zeiten. Jetzt, da die Bedrohung durch die Defias beseitigt ist, ist das Gebiet zu einer Zuflucht für Obdachlose und Unterdrückte geworden. Die Verbrechensrate in dieser Region ist astronomisch in die Höhe geschossen, da die Leute sich um Unterschlupf und Nahrung zanken. Und jetzt hört man sogar von Mord!\n\nWenn Ihr der Allianz helfen wollt, dann beginnt in Westfall. Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof. Ihr findet Westfall direkt westlich des Waldes von Elwynn.", sourceObjective = "Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof in Westfall.", completion = "Mord, Grünschnabel. Das seht Ihr da auf dem Boden vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26379] = { id = 26379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Flüchtlinge", description = "Ich hoffe, Ihr seid hier, um zu helfen! Ihr habt keine Ahnung, wovon ich spreche, oder?\n\nIch habe keine Zeit, um Euch alle Details zu erläutern, aber hier in Dunkelküste gab es einen Ort namens Auberdine, der vom Kataklysmus übel zugerichtet wurde. Wir sind dabei, einige der Überlebenden zu retten, aber ich brauche jemanden mit etwas mehr Erfahrung, der nach dem Flüchtlingslager sieht, das sich im Süden befinden soll. Jemanden wie Euch!\n\nÜberlasst uns die Dinge im Norden. Geht direkt nach Süden und helft den Flüchtlingen, wo Ihr nur könnt.", sourceObjective = "Schildwache Lendra in Lor'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26380] = { id = 26380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Kharanos", description = "Ich sollte diese Bierfässer zum Gasthaus von Kharanos bringen. In den Fässern befindet sich ein mysteriöses neues Bier, das von einer neuen Brauerei in Bräuhall hergestellt wird. Als ich die Stadt verließ, wurde ich von Trollen der Frostmähnen überfallen. Ich werde Tage brauchen, um den Wagen zu reparieren!\n\nWürdet Ihr mir vielleicht einen Gefallen erweisen? Die großen Fässer lassen sich nicht bewegen, aber ich habe hier ein paar kleine Probefässer. Würdet Ihr die für mich nach Kharanos bringen? Folgt einfach nur der Straße nach Südosten.", sourceObjective = "Bringt die Probefässer zu Gastwirt Belm in der Brauerei Donnerbräu in Kharanos.", progress = "Seid willkommen, Besucher. Habt Ihr dieses Gasthaus betreten, weil Ihr Euch ausruhen wollt oder weil Ihr einen neuen Ruhestein benötigt?", completion = "Die sehen vielversprechend aus. Ich habe viel Gutes über die Brauerei \"Kurz, aber Deftig\" gehört, aber ihr Bier konnte ich bisher nicht probieren.\n\nEntspannt Euch ein wenig, solange Ihr hier seid. Wenn Ihr einen Ersatzruhestein braucht oder Kharanos zu Eurer Heimat machen wollt, sprecht mich an. Ich helfe Euch gern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26381] = { id = 26381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Shadra", description = "Shadra muss gerufen werden, das ist sicher. Uns diese Gelegenheit entgehen zu lassen, wäre schlicht und ergreifend dumm. Die Apotheker finden sicher Verwendung für das Gift der Göttin, aber von Ritualmagie haben sie nicht viel Ahnung.\n\nGlücklicherweise bin ich mit der Vorbereitung dunkler Beschwörungen recht vertraut. Bringt mir die verstreuten Teile Shadras und ich werde sie auf diese Ebene beschwören.\n\nZuerst brauchen wir das Auge von Shadra. Es wird in Agol'watha bewacht.", sourceObjective = "Holt das Auge von Shadra aus Agol'watha.", progress = "Wenn es sich bei den Tafeln um eine Täuschung handelt, werde ich nicht erfreut sein. Habt Ihr das Auge gefunden?", completion = "Ich bin zufrieden, {name}. Das war schneller, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26382] = { id = 26382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiertanz", description = "Marnal liegt mir schon seit Tagen mit seinem Shadravorhaben in den Ohren. Ich bereue schon fast, die Tafel wirklich gefunden zu haben - zu dem Zeitpunkt hätte er meiner Meinung nach schon den Mund halten können.\n\nUnd trotz seiner Erfahrung mit Ritualmagie braucht er meine Hilfe genau so sehr wie ich seine. Ich muss ein Basismedium mit ähnlichen...\n\n...wisst Ihr was, ich werde Euch die Einzelheiten ersparen. Bringt mir die Eier der Shadrabrut aus Agol'watha. Ihr solltet dort viele finden - sie werden von den Trollen der Blutfratzen bewacht.", sourceObjective = "Sammelt 5 Eier der Shadrabrut aus Agol'watha.", progress = "Ich hoffe, Ihr habt genügend.", completion = "Gut, gut. Legt sie da drüben hin, ich habe beide Hände voll.", sourceObjectiveStatus = "unverified-source-field" }
quests[26383] = { id = 26383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaufhaltsame Veränderungen", description = "Ihr da! Ihr seht fähig aus. Und vielleicht sogar hilfsbereit?\n\nAuberdine ist letztendlich gefallen. Zwar haben viele Einwohner bereits vor langem die Stadt verlassen, als der Kataklysmus uns heimsuchte, doch einige der hartnäckigeren Bewohner wurden noch nicht gefunden. Und jetzt scheint die Stadt auch noch von Elementaren überrannt zu werden.\n\nMeine Schwestern brauchen Hilfe bei der Rettung der Überlebenden. Bitte, {class}, benutzt den westlichen Teleportbaum, um nach Rut'theran zu gelangen, sprecht mit Vesprystus und sichert einen Flug nach Lor'danel. Beeilt Euch!", sourceObjective = "Benutzt den Teleportbaum im westlichen Teil von Darnassus und reist nach Rut'theran. Sprecht dort mit Vesprystus, um einen Flug nach Lor'danel zu sichern.", completion = "Haben die Schildwachen Euch geschickt? Elune sei Dank. Wir brauchen jede Hilfe, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26384] = { id = 26384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Kleriker Marnal", description = "Wir können die Tafel noch nicht einfach wegschmeißen, {name}. Wir können sie benutzen...\n\nWisst Ihr, mir geht es in erster Linie um das Gift der Spinnen. Es ist eindeutig magisch und wahrscheinlich gibt es eine Verbindung zur Spinnengöttin, mit der die Trolle etwas zu tun haben. Und wenn man die Tafel zur Beschwörung nutzen kann...\n\nNa ja, ich glaube, Ihr wisst, worauf ich hinaus will. Die Horde kann sich diese Gelegenheit nicht entgehen lassen. Bringt die Tafel zu den Verlassenen. Sie sind westlich von hier in der Forschungsstation in den Ruinen von Hiri'watha.", sourceObjective = "Bringt die Tafel von Shadra zum dunklen Kleriker Marnal.\n\nBereitgestellter Gegenstand:", completion = "Ah, was haben wir den hier...\n\nFaszinierend. Wirklich faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[26385] = { id = 26385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaufhaltsame Veränderungen", description = "Sieht aus, als hättet Ihr Euren ersten Auftrag. Ihr müsst zurück nach Rut'theran reisen, wo wir zuerst ankamen, und mit Vesprystus sprechen, um einen Transport nach Lor'danel zu bekommen.\n\nSeid Ihr erst einmal in Lor'danel angekommen, müsst Ihr den Nachtelfen dort auf jede nur erdenkliche Weise helfen, die Euch möglich ist. Ich vertraue darauf, dass Ihr sie mit dem Respekt behandelt, den sie verdienen, nach Allem was sie für uns getan haben.\n\nIch selbst muss in die ferne Stadt Sturmwind reisen und mich mit König Varian treffen. Ich hoffe, Euer Gesicht bald wieder zu sehen, {name}. Bis dahin ein herzliches Lebewohl.", sourceObjective = "Sprecht mit Vesprystus in Rut'theran, um nach Lor'danel zu fliegen.", completion = "Unsere Verbündeten eilen zu unserer Hilfe? Elune sei Dank! Es war weise von Tyrande, Eurem Volk mit offenen Armen zu begegnen.\n\nWir brauchen Hilfe. Wir brauchen jede helfende Hand, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26386] = { id = 26386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surkhan", description = "Priesterin spricht nicht gut Orkisch, nein.\n\nVielleicht sprecht Ihr mir Surkhan, er ist oben.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen habt, ja.", sourceObjective = "Meldet Euch bei Surkhan in Bambala im Nördlichen Schlingendorntal.", completion = "<Ihr erklärt Surkhan, was sich bisher ereignet hat.>\n\nEs scheint, dass Jin'do überlebt hat und dass er seine Brüder versammelt, um Hakkar erneut in diese Welt beschwören zu können. Es war eine weise Entscheidung, mit mir zu sprechen.\n\nLeider können wir im Moment nicht sehr viel mehr machen als warten und beobachten. Jin'do ist schwach und die Zeit wäre für einen Angriff gut, aber ich muss auf die Reaktion aus Rastakhan warten, bevor ich Befehle erteilen kann. Bis dahin müsst Ihr und Euer Raptor warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26387] = { id = 26387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungerdiät", description = "Die Spinnen, die die Gruselruinen östlich von hier heimsuchen, sind nutzlos. Wir nennen sie zwar Shadrabrut und sie sind auch ganz offensichtlich mit der Spinnengöttin verwandt, aber das ändert auch nichts an der Tatsache, dass sie mehr Ärger machen als Nutzen bringen. Mir wäre es lieber, wenn wir die kleinen Plagegeister einfach ausmerzen könnten.\n\nFalls Ihr Euch zu den Gruselruinen aufmachen solltet, tötet alle Kokons, die Ihr finden könnt. Sie ernähren sich tagelang von den Leichen - die Nahrung der Biester zu zerstören wird effektiver sein, als der Versuch, sie alle zu zerquetschen.", sourceObjective = "Vernichtet 6 eingesponnene Opfer in den Gruselruinen.", completion = "Nun, das ist eine weitaus bessere Situation, von der wir alle etwas haben. Die Spinnen werden entweder verhungern oder sich Zwerge oder Elfen schnappen, um sich zu ernähren. An mir und meinen Kollegen ist ja nichts dran, was ein nahrhaftes Mahl darstellen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[26388] = { id = 26388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichthimmel", description = "In Ordnung, Ihr seid also bereit. Wartet hier, bis Kapitän Krazz den Zeppelin gewendet hat und begleitet dann die Luftflotte. Admiral Steinfaust erwartet Euch beim Hafen des Drachenmals!", sourceObjective = "Begleitet die Luftflotte der Horde ins Schattenhochland. Nehmt den Zeppelin vom Turm an der Südlichen Endhaltestelle der Raketenbahn in Azshara.", completion = "Das ist eine Katastrophe, {name}!\n\nUnsere Luftflotte wurde dezimiert. Und wir erhalten Berichte, dass unsere Schiffe grundlos auf offenem Meer von der Allianz angegriffen wurden.\n\nUnd was ist mit Höllschrei? Ist der Kriegshäuptling tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[26389] = { id = 26389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzfelsinvasion", description = "Die Orcs haben begonnen, den Wald niederzubrennen, {name}! Sie haben den Weinberg im Osten übernommen und planen ihren Entscheidungsangriff auf uns! Sie müssen aufgehalten werden!\n\nGeht nach Osten, überquert den Fluss und tötet die wildgewordenen Orcs des Schwarzfelsklans. Sammelt als Beweis ihres Ablebens ihre Waffen ein und kehrt zu mir zurück.\n\nIhr seid unsere einzige Hoffnung, {name}!", sourceObjective = "Bringt 8 Waffen der Orcs des Schwarzfelsklans an Euch.", progress = "Habt Ihr die wildgewordenen Orchorden getötet?", completion = "Die Orcs des Schwarzfelsklans werden jetzt, da ihre Hauptstreitkraft geschlagen wurde, sicherlich fallen. Nun bleibt nur noch eine Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26390] = { id = 26390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Invasion ein Ende!", description = "Die wütende Orchorde wird von einem Ungeheuer angeführt, das als Kurtok der Schlächter bekannt ist. Kurtok ist für den vor Kurzem erfolgten Einmarsch verantwortlich und muss getötet werden, wenn wir Frieden im Tal haben wollen.\n\nGeht vorsichtig nach Osten zurück, überquert den Fluss und begebt Euch durch den Weinberg. Haltet Ausschau nach der Passage, die in die Berge führt. Dort wird Kurtok sich aufhalten und einen weiteren Angriff vorbereiten. Tötet ihn und kehrt zurück zu mir.", sourceObjective = "Tötet Kurtok den Schlächter.", completion = "Jetzt, da Kurtok tot ist, sind wir wieder vor den Orchorden sicher. Ich werde Arbeiter zum Pass entsenden und versuchen, die Passage zu verschließen, damit dort keine Orcs mehr hindurch und auf unser Gebiet gelangen können.\n\nIhr habt den Dank von Sturmwind und der Allianz, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[26391] = { id = 26391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung ersticken", description = "Tage wie diese lassen mich die Zeiten zurücksehnen, in denen die Defias noch da waren. Der Kataklysmus hat einen Weg aus der Brennenden Steppe geöffnet, und jetzt überlaufen Schwarzfelsorcs das Nordhaintal! Sie haben mein Weingut übernommen und brennen es nieder! SIE BRENNEN ES NIEDER!\n\nBitte, {name}, dieses Weingut ist alles, was ich habe. Nehmt meinen Feuerlöscher und löscht die Flammen im Weingut. Vielleicht besteht noch Hoffnung für dieses Land!", sourceObjective = "Benutzt Millys Feuerlöscher, um 8 Brände im Weingut zu löschen.", completion = "Seid gesegnet, {name}. Ihr seid ein wahrer Held der Allianz! Auch wenn dieses Land völlig verbrannt und nichts als Schutt und Asche vom Weingut übrig ist, kann es sich vielleicht erholen. Stimmt's? Wie schlimm kann es schon sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[26393] = { id = 26393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eilige Nachricht", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Bartlett den Tapferen, unseren Greifenmeister. Er ist direkt bei der Schmiede; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", sourceObjective = "Bringt Argus' Notiz zu Bartlett dem Tapferen, dem Greifenmeister.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Sturmwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26394] = { id = 26394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Sturmwind", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Argus' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", sourceObjective = "Bucht einen Greifenritt bei Greifenmeister Bartlett dem Tapferen, dann bringt Argus' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Schmied Argus? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Heutzutage gibt es so viele neue Rekruten.\n\nIch danke Euch, {name}. Hier habt Ihr etwas Geld für Eure Reisespesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26395] = { id = 26395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Trinkfest", description = "{name}, ich habe alles, worum Argus gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Bartlett in Goldhain gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Argus. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Goldhain ohne neue Ausrüstung sind!", sourceObjective = "Bringt Osrics Kiste zu Dungar Trinkfest, dem Greifenmeister.", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Goldhain, eh? Seid Ihr schon mal in Goldhain gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[26396] = { id = 26396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Argus", description = "Der Name des Greifenmeisters in Goldhain ist Bartlett. Wenn Ihr bereits mit ihm gesprochen habt, könnt Ihr auf einem meiner Greifen zu ihm fliegen.\n\nVergesst nicht: Greifen sind so ausgebildet, dass sie jederzeit in ihre Hauptstadt fliegen können, bringen Euch aber nur zu anderen Greifenmeistern, wenn Ihr schon einmal dort wart.\n\nIhr habt Euch schon einmal mit Bartlett unterhalten, daher sprecht mich einfach erneut an, wenn Ihr auf einem Greifen nach Goldhain fliegen wollt. Sobald Ihr da seid, könnt Ihr Osrics Kiste zu Schmied Argus bringen.", sourceObjective = "Bucht einen Greifenritt nach Goldhain bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Schmied Argus in Goldhain.", progress = "Ihr seid zurück aus Sturmwind? Hat Osric die Rüstungen geschickt?", completion = "Wunderbar, Ihr habt die Rüstungen gebracht! Wir werden sie sofort unter denen verteilen, die sie brauchen.\n\nVielen Dank, {name}. Ihr wart uns wirklich eine große Hilfe. Und jetzt, da Ihr Euch ein wenig mit den Greifen vertraut gemacht habt, hoffe ich, dass Ihr öfter kommt und Goldhain unterstützt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26397] = { id = 26397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht mit der Erdenmutter", description = "Viel hat sich geändert in der Welt außerhalb Mulgores, {name}. Die Welt ist gebrochen und unsere Verbündeten der Horde haben dunkle Wege eingeschlagen. Wir müssen sie leiten. Selbst in der dunkelsten aller Stunden werden wir unsere Köpfe mutig hoch erhoben haben, und der Erdenmutter Ehre erweisen.\n\nIhr müsst Euch auf den Weg machen und der Welt ein gutes Beispiel sein. Reist nach Orgrimmar. Berichtet Kriegshäuptling Höllschrei, dass die Grimmtotem vertrieben wurden. Berichtet von unserem Stolz, unserer Disziplin, unserer Stärke, und unserem Leid.\n\nTal beim Himmelsturm wird Euch auf den Weg schicken. Geht in Frieden, und vergesst nie, wo Ihr herkommt.", sourceObjective = "Bringt das Mal von Bluthuf zu Garrosh Höllschrei in der Feste Grommash in Orgrimmar.\n\nSprecht mit Tal dem Windreitermeister oder wartet auf den Zeppelin, um Eure Reise anzutreten.", progress = "Was ist Euer Anliegen beim Kriegshäuptling der Horde, {race}?", completion = "Die Grimmtotem aus Mulgore vertrieben... wenn Baine möchte, dass dies gehört wird, so seid Ihr wohl wirklich ein gefährlicher Kämpfer.\n\nVom heutigen Tag an wird Eure Stärke nicht mehr Euch gehören. Sie gehört nun mir und der Horde, und ist eine Waffe für den Krieg.\n\nHöllschrei wacht über Euch, {name}. Bringt den Sieg oder findet den Tod!", sourceObjectiveStatus = "unverified-source-field" }
quests[26399] = { id = 26399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tip von 'nem Typen namens Mok'thardin bekommen, dass so'n Schwachkopf von <einem/einer:r> {race} in 'ner lächerlichen Aufmachung <eines/einer:c> {class} 'ne Ogerhand gefunden hat und...\n\n<Skeezy bricht ab und mustert Euch.>\n\nWas sagte ich gerade? Ach ja... <ein SCHWERTSCHWINGENDER HELD/eine ATEMBERAUBENDE HELDIN> fand diese Ogerhand und Mok'thardin glaubt deswegen, dass die Oger ein besonderes Artefakt haben. Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", sourceObjective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wie kommt es, dass ausgerechnet OGER immer die unbezahlbaren Artefakte finden?", completion = "<Skeezy müht sich vergebens ab, den Kasten zu öffnen.>\n\nDiese Oger wissen wirklich, wie man eine Schatztruhe verschließt. Ich sag' Euch 'was... Ein Kasten bringt mir nichts, Held. Wir müssen einen Weg in diese Kiste hinein finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26400] = { id = 26400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Universalschlüssel", description = "Wir brauchen etwas stärkeres, als Eure fleischigen {race}-Hände, um das hier zu öffnen. Und die Trottel der Venture Company im Nordwesten haben möglicherweise genau das Richtige.\n\nDas letzte Mal, als ich da drüben war, sah ich Schredder herumlaufen, die riesige, rotierende Klingen an den Händen hatten. Das wäre eine Möglichkeit, einen Kasten zu öffnen.\n\nWenn Ihr keine Schredder findet, könnt Ihr auch die riesige Sägeklinge in ihrem Sägewerk am See ausprobieren.", sourceObjective = "Öffnet die Belohnung der Mosh'Ogg, indem Ihr gegen einen Schredder der Venture Co. kämpft, oder die Sägeklinge im Sägewerk der Venture Company benutzt.", progress = "Habt Ihr die Kiste schon geöffnet? Ich kann es kaum erwarten, zu sehen, was sich darin befindet.", completion = "<Der Goblin späht hinein.>\n\nWaaaaaaaa...?!?\n\nIch... Ich muss das zu... zu Flem... im Süden schicken. Er wird etwas damit anzufangen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26401] = { id = 26401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Vestia", description = "Das sanfte Leuchten des Podests wird stärker. Ihr seht eine schlichte Kette, die zurückgelassen wurde. War es das, wonach der Lehrling gesucht hatte?", sourceObjective = "Bringt das Graunebelamulett zu Vestia Mondspeer im Turm von Estulan.", progress = "Ihr seid zurück… ohne ihn….", completion = "Wie schrecklich, dass jemand so voller Jungend und Talent den Dämonen zum Opfer fallen musste!\n\nBitte, verzeiht mir, dass ich auch Euch in Gefahr gebracht habe, {name}. Ich hoffe, dass Ihr dieser Dämonin nie wieder begegnen müsst…", sourceObjectiveStatus = "unverified-source-field" }
quests[26402] = { id = 26402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Shandris Mondfeder", description = "Wir Druiden haben nicht besonders viel mit den Schildwachen zu tun, aber wir arbeiten bereitwillig zusammen, um unser Land zu verteidigen. Jetzt, da Ihr mir geholfen habt, wäre es äußerst nachlässig, wenn ich Euch nicht bitten würde, auch ihnen zu helfen.\n\nShandris Mondfeder, General der Schildwachen, hat den Oberbefehl über alle militärischen Vorgänge in Kalimdor. Sie hält sich in der neu errichteten Mondfederfeste im Süden auf. Sagt Ihr, dass ich Euch schicke. Ich bin mir sicher, dass sie Eure Fähigkeiten benötigt.", sourceObjective = "Sprecht mit Shandris Mondfeder in der Mondfederfeste in Feralas.", completion = "Telaron hat mir bereits von Euch berichtet, {name}. Ich bin gespannt, ob Ihr nur halb so talentiert seid, wie er behauptet.\n\nIch kämpfe einen Krieg an mehreren Fronten und kümmere mich gleichzeitig darum, dass unsere Gebiete richtig verteidigt und unsere jüngsten Schildwachen richtig ausgebildet werden. Wenn Ihr ein geschickter Kämpfer seid, habe ich genug für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[26403] = { id = 26403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company-Bergbau", description = "Mann, ich hasse die Venture Company. Sie haben eine ganze Reihe von Operationen überall im Schlingendorntal, die hart arbeitende Goblins wie mich davon abhalten, ehrliches Gold zu verdienen!\n\nWie ich das mache? Durch Diebstahl. Die Geologen der Venture Co. in der Nähe des Nazferitisees im Nordwesten sind sehr an diesen merkwürdigen blauen Kristallen interessiert, die sie in den Minen finden. Bringt mir Proben dieses Gesteins von ihren Geologen. Mir ist egal, was Ihr tun müsst, um sie zu erhalten.", sourceObjective = "Bringt 5 gerommelte Kristalle zu Skeezy Whillzap in Bambala im Nördlichen Schlingendorntal.", progress = "Habt Ihr die Kristalle? Ich brauche sie!!\n\nIch meine... ich muss wissen, dass die böse Venture Company im Schlingendorntal an Boden verliert. Denn wisst Ihr, wir ehrlichen Leute müssen unseren Lebensunterhalt verdienen!", completion = "Großartig! Wunderbar! Die werden mir einiges einbringen!!\n\nDiese Venture Company hat sich den falschen Dschungel zum Schürfen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26404] = { id = 26404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhere Lohngruppe", description = "Hey, seid Ihr schon in Hartzangs Versteck gewesen? Oh, das MÜSST Ihr sehen. Das ist alles, was ein Goblin sich je erträumen kann.\n\nIch sag Euch was... Ihr seht aus, wie <ein überzeugter/eine überzeugte:c> {class}. Rashka, die da drüben in Weste und Rock, kann Euch einen Flug verschaffen, wenn Ihr den Weg nicht bereits kennt.\n\nDer Flug geht auf mich.", sourceObjective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.", completion = "Skeezy hat Euch an den richtigen Ort geschickt. Willkommen in Hartzangs Versteck!", sourceObjectiveStatus = "unverified-source-field" }
quests[26405] = { id = 26405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mambo in Zul'Mamwe", description = "Die Schädelspalter sind eine Schande für das ganze Trollreich. Ihre kindischen Zankereien mit den Blutskalpen haben das Nördliche Schlingendorntal zerrissen. Während Stämme wie die Dunkelspeere und die Zalandari erblühen, kämpfen die Schädelspalter um Ruinen.\n\nIch wurde ermächtigt, allen Söldnern eine Belohnung zu bezahlen, die bereit sind, den Schädelspaltern eine Lektion zu erteilen. Ich ermutige daher Euch und alle, die Ihr kennt, nach Zul'Mamwe zu reisen und ihrem abtrünnigen Stamm ein Ende zu setzen.", sourceObjective = "Tötet 16 Trolle der Schädelspalter in Zul'Mamwe.", completion = "Hier ist Eure Belohnung, wie versprochen. Ihr erfüllt das Volk der Trolle mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26406] = { id = 26406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fangzahn von Shadra", description = "Als nächstes brauchen wir den Fangzahn von Shadra.\n\nShadras eigene Brut bewacht ihn in den Gruselruinen im Osten. Ihr Gift ist stark, {name}... werdet nicht unvorsichtig.", sourceObjective = "Besorgt den Fangzahn von Shadra aus den Gruselruinen.", progress = "Habt Ihr den Fangzahn?", completion = "Da ist er... nur noch einer übrig.", sourceObjectiveStatus = "unverified-source-field" }
quests[26407] = { id = 26407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Handschrift von Mosh'Ogg", description = "Dieser Oger hatte einen ungewöhnlichen Gegenstand bei sich: die abgetrennte Hand eines anderen Ogers, die er an einer Schnur befestigt um den Hals trug Die Hand selbst weist viele Narben auf, die in einem schwachen lila leuchten.\n\nEine Narbe, die nach dem Tod leuchtet, ist höchst ungewöhnlich. So einen Gegenstand bei einem Oger zu finden, ist noch merkwürdiger. Vielleicht weiß jemand in Grom'gol etwas mit dieser Kuriosität anzufangen.", sourceObjective = "Bringt die entstellte Hand der Mosh'Ogg zu Scharfseher Mok'thardin im Basislager Grom'gol im Nördlichen Schlingendorntal.", progress = "Eine Hand sagt Ihr?", completion = "<Der Scharfseher achtet darauf, dass er den Gegenstand an der Schnur hält und vermeidet sorgfältig, die Faust des toten Ogers zu berühren.>\n\nDas ist in der Tat merkwürdig. Ich werde das meinen Kontakten im Osten, in der Nähe des Hauptlagers der Mosh'Ogg, unterbreiten. Ich habe so ein Gefühl, als ob sie sich für diese seltsamen Narben interessieren könnten.\n\nIch danke Euch, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26408] = { id = 26408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche im Eschental", description = "Dunkelküste mag zerschlagen und zerschmettert sein, aber dank Euch haben wir hier ein gewisses Maß an Sicherheit erlangt. Ein gewisses Maß an Frieden. Wir müssen noch viel wieder aufbauen.\n\nIhr solltet weitermachen, <mein Freund/meine Liebe>. Garrosh hat die geballte Macht seiner Horde gegen uns im Eschental aufgefahren. Sie werden uns alle töten und den Wald roden, wenn wir nicht gegen sie vorgehen.\n\nUm Hoffnung zu bewahren, diese Wälder nicht vollständig aufgeben zu müssen, benötigen wir Eure Hilfe. Folgt der Straße in Richtung Süden und sucht Schildwache Shyela auf.", sourceObjective = "Sprecht mit Schildwache Shyela bei Orendils Zuflucht im Eschental.", completion = "Schön, ein neues Gesicht in dieser Gegend zu sehen!\n\nDie Horde kriecht überall in den Wäldern herum, aber mein Auftrag sieht vor, dass ich diesen Außenposten absichere. Ich könnte wirklich jemanden gebrauchen, der ein wenig Kampflust mitbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26409] = { id = 26409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Goldmine?", description = "Mein goblinischer Initiand ist schon eine ganze Weile fort. Sein Name ist Goldmine.\n\nIch habe ihn losgeschickt, um die Felsklauen im Südwesten im Quarzitbecken zu beobachten. Wärt Ihr bereit, ihn zu suchen? Wenn Ihr ihn findet, bittet ihn, zum Tempel zurückzukommen.", sourceObjective = "Findet Initiand Goldmine am Quarzitbecken in Tiefenheim.", completion = "Hallöchen! Könnt Ihr mir vielleicht kurz helfen, Spezi?", sourceObjectiveStatus = "unverified-source-field" }
quests[26410] = { id = 26410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Verbundmasse", description = "Dieser Kerl ist der Sohn des Anführers der Irdenen! Er hatte es schon fast zurück in den Tempel geschafft, als er von mehr Felsklauen angegriffen wurde, als ich zählen konnte!\n\nWir wissen, dass der Steinvater der Irdenen das mittlere Fragment der Weltensäule besitzt. Wenn wir seinen Sohn heilen, gibt er uns vielleicht das Fragment.\n\nMeine Heilzauber funktionieren bei Flint hier nicht. Aber wenn wir an etwas Quarzitharz von diesen Monstern kommen könnten, könnte ich eine explosive Verbundmasse herstellen, die seine Wunden schließt und kauterisiert.", sourceObjective = "Sammelt 5 Einheiten Quarzitharz.", progress = "Ich brauche nicht viel Harz. Diese Felsklauen sind jedoch ziemlich gefährlich.", completion = "Was für ein Glück, dass ich zufällig Großmeister der explosiven Alchemie bin.\n\nDas hier wird sich aber nicht von allein entzünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26411] = { id = 26411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitztrocknung", description = "In Ordnung, nehmt dies und gebt es auf seine Wunden. Wenn die blitzartige Kauterisation ihn nicht in Stücke reißt, sollte er dadurch vollständig heilen.\n\nGlaube ich…", sourceObjective = "Behandelt Flint Erzmantel mit der explosiven Verbundmasse.", progress = "Quasselt mich nicht voll. Behandelt Flint mit der explosiven Verbundmasse.", completion = "Sieht aus, als hätte es gewirkt. Er sollte jeden Moment zu sich kommen.\n\nIch habe Euch doch gesagt, dass ich ein Großmeister der Alchemie bin!\n\nIch habe noch etwas Harz übrig. Daraus kann ich allerlei wundervolle explodierende Dinge bauen. Was wollt Ihr haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[26412] = { id = 26412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Sagt, habt Ihr von den Ogern gehört? Ich hab' 'nen heißen Tip von 'nem Typen namens Mok'thardin bekommen, dass sie ein ganz besonderes, magisches Artefakt in ihrer Höhle verstecken. Skeezy weiß das aber besser. Ich rieche Geld aus einer Mulgoremeile Entfernung und ich wette, das Ogerdingsbums ist ein Vermögen wert.\n\nHier ist ein Hinweis: Ich habe gesehen, dass sie eine Kiste in den Ruinen hinter ihrem Hügel bewachen. Habt Ihr Lust, sie für mich zu holen?", sourceObjective = "Holt die Belohnung der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26413] = { id = 26413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt ihn zur Erdenruferin", description = "Er scheint mir immer noch etwas wackelig auf den Beinen zu sein. Sein Kopf muss dröhnen.\n\nAm besten bringt Ihr ihn in den Tempel zur Erdenruferin und schaut, was sie für ihn tun kann.\n\nIch werde noch ein Weilchen hier draußen bleiben und diese Felsklauen \"beobachten\".", sourceObjective = "Bringt Flint Erzmantel zu Erdenruferin Yevaa im Tempel der Erde.", progress = "Einer der Irdenen? Das ist eine unerwartete und günstige Überraschung, {name}.", completion = "Die Anwesenheit von Flint Erzmantel ehrt uns. Wie ich gehört habe, befindet sich ein Fragment der Weltensäule im Besitz des Steinvaters.\n\nEs ist von oberster Wichtigkeit, dass wir alle Fragmente wiedererlangen. Die Instabilität zwischen den Welten wird immer stärker. Bald ist sie vielleicht schon so groß, das nicht einmal der mächtige Thrall ihr Einhalt gebieten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26414] = { id = 26414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Zander erwischen", description = "Manchmal fische ich zum Spaß. Dann wieder, um zu entspannen, aber manchmal brauche ich eine Herausforderung. Da kommt der verhärtete Zander ins Spiel. Dieser wertvolle Fisch wird nicht als Speise gefangen, sondern wegen der Herausforderung. Ihr werdet den Zander im Sturmwindsee nördlich der Stadt finden. Glaubt Ihr, Ihr seid der Herausforderung gewachsen?", sourceObjective = "Catherine Leland in Sturmwind möchte, dass Ihr ihr 8 verhärtete Zander bringt.", progress = "War die Herausforderung zu viel für Euch?", completion = "Gute Arbeit, {name}. Wie ich sehe, seid Ihr inzwischen ein ziemlich guter Angler. Vielleicht sollte ich Euch bald mit dem Boot mit hinausnehmen, um zu sehen, was Ihr wirklich könnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26416] = { id = 26416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Dschungel", description = "Mein Kommandant hat mich ausgeschickt, um nach Rekruten Ausschau zu halten, die bei der Verteidigung des Basislagers von Grom'gol im Nördlichen Schlingendorntal helfen. Kennt Ihr das Schlingendorntal? Es ist sehr weit weg... Man muss das Große Meer überqueren, und dann befindet es sich an der südlichen Spitze der Östlichen Königreiche. Ihr passt auf die Beschreibung, die er mir gegeben hat... Seid Ihr daran interessiert, Kalimdor für eine Weile zu verlassen?\n\nWenn ja, sprecht mit meinem Kollegen Bort in Orgrimmar. Er wird Euch behilflich sein, an Bord des Zeppelins zu gehen.\n\nUnd sagt ihm von mir \"Wusel-Dusel\". Er weiß schon, was das bedeutet.", sourceObjective = "Meldet Euch bei Bort in Orgrimmar.", completion = "Hah! Diese Allumpass ist wirklich zu komisch.\n\nOh, stimmt ja, Schlingendorntal. Ihr wollt wirklich dorthin?", sourceObjectiveStatus = "unverified-source-field" }
quests[26417] = { id = 26417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Nördliche Schlingendorntal: Das Gefallene Reich", description = "Kommandant Aggro'gosh sucht nach ergebenen Hordenmitgliedern, um ihm bei seiner Mission in Grom'gol zu helfen. Wenn Ihr interessiert seid, geht einfach oben auf den Zeppelinturm und besteigt den Zeppelin nach Grom'gol. So einfach ist das!\n\nIm Ernst, das Schlingendorntal ist momentan genau der richtige Aufenthaltsort... Dort gibt es reichlich Action und nicht annähernd so viel Schäden durch den Kataklysmus, wie im.... sagen wir ... Steinkrallengebirge. Ich wünschte, ich könnte mit Euch kommen.", sourceObjective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", completion = "Schön, dass Ihr es geschafft habt! Gehen wir an die Arbeit, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[26418] = { id = 26418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Panzer von Shadra", description = "Wir müssen noch einen weiteren Teil finden und dann haben wir alles, was wir brauchen.\n\nDer Panzer von Shadra wird von der letzten lebenden Priesterin der Spinnengöttin bewacht, von Qiaga der Bewahrerin. Sie ist auf dem Altar von Zul und wird von anderen fanatischen Zeloten bewacht.\n\nEin Kinderspiel, oder? Steigt die Treppen des Altars hoch und lasst ihren Kopf die Treppen runter rollen. Bringt mir den Panzer und wir können Shadra endlich beschwören.", sourceObjective = "Tötet Qiaga die Bewahrerin und besorgt den Panzer von Shadra.", progress = "Habt Ihr den Panzer?", completion = "Ja... endlich ist es soweit. Shadra wird unser sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[26419] = { id = 26419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra, Königin des Giftes", description = "<Der Boden wackelt als der Götze auf den Altar gesetzt wird und der See beginnt zu schäumen! Shadra erscheint!>", sourceObjective = "Tötet Shadra, die Königin des Giftes.", completion = "Ausgezeichnete Arbeit. Ihr habt der Dunklen Fürstin gute Dienste geleistet, {name}.\n\nIhr böses Blut wird unsere Armeen mit einer mächtigen Waffe gegen die verachtenswerte Allianz bieten. Wir werden sie aus diesen Ländern vertreiben.\n\nFür die Horde, versteht sich... und alles dank Eurer Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26420] = { id = 26420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Würmern graben", description = "He da, Angler! Arnold hier sagt, dass Ihr nach einem neuen Angelpunkt sucht und ich glaube, ich kenne genau den richtigen Ort. Nördlich von Sturmwind gibt es ein kleines Fleckchen Erde, das Olivias Teich heißt.\n\nDer Teich wird jedes Jahr mit neuen Kristallbarschen bestückt, aber sie sind schwer zu fangen. Sie beißen nur bei einem bestimmten Köder... Übergroße Regenwürmer. Wenn Ihr das Ufer des Teichs absucht, solltet Ihr ausreichend Würmer finden, die Ihr als Köder benutzen könnt.", sourceObjective = "Findet einen übergroßen Regenwurm in der Nähe von Olivias Teich und benutzt ihn als Köder, um einen Kristallbarsch zu fangen. Kristallbarsche findet man in Olivias Teich, nördlich von Sturmwind.", progress = "Hat der Köder funktioniert?", completion = "Das sind doch mal nette Barsche, {name}. Lasst sie uns braten und probieren, wie sie schmecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[26421] = { id = 26421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26422] = { id = 26422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26423] = { id = 26423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen. \n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26424] = { id = 26424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26425] = { id = 26425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochtüftler", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin teilte mir mit, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nMekkadrill - oder richtiger: Der Hochtüftler Mekkadrill - ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.", sourceObjective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26426] = { id = 26426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein grausamer Sturm", description = "Es gibt eine Aufgabe, die ich Euch anvertrauen kann.\n\nEs ist eine gefährliche Aufgabe. Wenn Ihr sie erfüllt, könnt Ihr weitere der sturen Steinlords beeindrucken.\n\nIm Nordwesten findet Ihr den Geschliffenen Schlund. Harte Winde schlagen dort gegen die Felsen und verbergen die wahre lebende Bedrohung darunter.\n\nIn den Geschliffenen Weiten leben die Schleifwürmer. Sie fressen sich durch die Felsen, als wären sie aus Wasser. Dasselbe tun sie auch mit unserer Steinhaut.\n\nSucht Felsen den Ausdauernden. Er wird Euch sagen, wie Ihr in die Bruchtiefen gelangt. Ich werde mit Euch sprechen, sobald Ihr dort angelangt seid.", sourceObjective = "Findet Felsen den Ausdauernden und folgt seinen Anweisungen, um in die Bruchtiefen zu gelangen.", completion = "<Der Boden zittert ein wenig, als Ihr Euch der Höhle nähert. Dies scheint der Eingang zu sein, von dem Diamant und Felsen gesprochen haben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26427] = { id = 26427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Kapitän oder Besatzung", description = "Ich weiß nicht, zu wem Ihr gehört, aber Ihr seht nicht aus wie einer von… ihnen.\n\nIch weiß nicht, was geschehen ist. Ich habe das Abendessen verschlafen und bin dann auf einem Schiff voller Toter und Mörder aufgewacht.\n\nIch weiß nicht, ob Ihr mich töten wollt, aber ich erspare Euch die Mühe.\n\n<Mürrisch zeigt auf eine Wunde in seinem Bauch. Seine Innereien sind nicht mehr da, wo sie sein sollten.>\n\nIch kann das Schiff noch eine Weile steuern. Von einer Bauchwunde stirbt man nicht sofort. Bringt mir einfach ein Stück Seil und etwas Rum... nein, Whiskey.", sourceObjective = "Bringt dem Ersten Maat Mürrisch eine Whiskeyflasche und eine Seilspule.", progress = "Habt Ihr, worum ich Euch gebeten habe?", completion = "In Ordnung. Helft mir, mich ans Steuer zu binden.\n\n<Mürrisch nimmt einen Schluck aus der Flasche.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26428] = { id = 26428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Dieben stehlen", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie ist tot, Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alldem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich will ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", sourceObjective = "Enthauptet Kenata Dabyrie, Fardel Dabyrie und Marcel Dabyrie.", progress = "Tötet sie alle und bringt mir ihre Köpfe!", completion = "Ihr steht als Racheengel vor mir und ich verneige mich dankbar vor Euch.\n\nNachdem diese Kuh tot ist und ich weiß, dass ihre Brut sich nicht mehr über Azeroth ausbreiten kann, kann ich meine Energie lukrativeren Dingen zuwenden. Ich hoffe, Ihr habt ihren Bauernhof geplündert, als Ihr sie getötet hattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26429] = { id = 26429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert die Bleichborken", description = "Die Trolle der Bleichborken und die Oger der Felsfäuste aus Arathi arbeiten Hand in Hand, um uns aus diesen Landen zu vertreiben. Doch weder sie, noch jemand anders wird unser Schicksal besiegeln. Wir werden sie vernichten und ihnen zeigen, dass auch wir hier unsere Heimat haben. \n\nDie Trolle haben sich von uns abgewendet; die Oger benutzten uns als Nahrung und Bettzeug, wenn wir es zuließen. Das darf einfach nicht sein.\n\nWir beginnen unseren Angriff bei den Trollen der Bleichborken südlich von hier. Schlachtet sie scharenweise ab und kehrt erst dann zurück, wenn ihre Lager blutgetränkt sind.", sourceObjective = "Tötet 10 Axtwerfer der Bleichborken, 10 Kopfjäger und 8 Hexendoktoren.", completion = "Eure Kleidung zeugt von Krieg und von Eurer Stirn läuft der Schweiß. Das ist gut, sehr gut sogar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26430] = { id = 26430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dorf der Bruchhauer", description = "Nicht alle Waldtrolle sind widerliche Plagegeister wie die Bleichborken. Nördlich von hier im Hinterland befindet sich das Dorf der Bruchhauer, Heimat der einzigen Waldtrolle, die noch mit der Horde verbündet sind.\n\nSogar sie können sich der Grausamkeit ihrer Brüder nicht entziehen. Der Stamm der Blutfratzen liegt mit ihnen im Krieg und lenkt sie von unserem Kampf gegen die Allianz ab.\n\nIhr habt hier gut gekämpft. Sprecht mit Urda, wenn Ihr ins Dorf der Bruchhauer fliegen möchtet. Ihr Dorf könnte Eure Stärke gut gebrauchen.", sourceObjective = "Reist zum Dorf der Bruchhauer im Hinterland und sprecht mit dem Ältesten Stumpfhauer.", completion = "Willkommen im Dorf der Bruchhauer, {class}. Ich hoffe, dass der Kampf gegen die Bleichborken Euch nicht ausgelaugt hat - die Blutfratzen sind noch schlimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[26431] = { id = 26431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archäologie", description = "Nehmt diese Quest an, um Archäologiepunkte auf Eurer Landkarte zu finden!" }
quests[26432] = { id = 26432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Jintha'Alor", description = "Wir müssen uns um weit mehr kümmern, als nur Zwerge, Mann. Während ich das Dorf bewache, führt meine Freundin Ura Stumpfhauer unsere Krieger gegen den gemeinen Blutfratzenstamm.\n\nSie haben unsere Brüder getötet und ich wurde sogar einmal von ihnen gefangengenommen. Jetzt ist es genug! Dieses Mal fällt die Stadt Jintha'Alor in unsere Hände.\n\nGeht nach Jintha'Alor und sprecht mit meiner Freundin. Sie hat ein Lager nahe des Eingangs zur Stadt erobert.", sourceObjective = "Findet Ura Stumpfhauer bei Jintha'Alor im Hinterland.", completion = "Willkommen, {class}. Wir werden dafür sorgen, dass die Blutfratzen es bereuen, uns über den Weg gelaufen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26433] = { id = 26433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das heilige Wasser der Klarheit", description = "Skeezy hat schon gesagt, dass Ihr kommen würdet. Dann lasst uns dieses... Ding mal identifizieren.\n\nZunächst müsst Ihr das heilige Wasser der Klarheit besorgen. Die Naga im Südosten unterhalten einen heiligen Schrein, aus dem köstliches klares und pures Wasser fließt. Sobald man auch nur einen Schluck von diesem heiligen Wasser schlürft, wird der Geist geläutert und der beste Weg liegt dem Trinkenden klar vor Augen.\n\nHört sich gut an, nicht wahr?\n\nBeschafft es aus dem Nek'maniquellbrunnen, der sich an dem höchsten Punkt des Nagacamps befindet. Viel Glück!", sourceObjective = "Beschafft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen am Schlingendornkap.", progress = "<Flem spitzt die Ohren, als Ihr Euch nähert.>\n\nDas heilige Wasser der Klarheit? Ist es hier!?", completion = "<Der Goblin stürzt das Wasser in einem Zug hinunter.>\n\nAhh... Wisst Ihr, wie schwer es ist, hier im Schlingendorntal frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so erbittert verteidigen.\n\nOh, stimmt ja... Euer Artefakt und Klarheit. Klarheit...\n\nIch hab's!", sourceObjectiveStatus = "unverified-source-field" }
quests[26434] = { id = 26434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursprüngliche Reagenzien der Macht", description = "Ich sehe es jetzt ganz deutlich... Der Schlüssel, um diesen mysteriösen Talisman zu identifizieren, liegt bei einigen sehr seltenen und wertvollen Gegenständen. Diese ursprünglichen Reagenzien der Macht werden uns den Ursprung des Schatzes enthüllen, wenn sie richtig kombiniert werden.\n\nReist nach Norden auf die Westseite der Arena der Gurubashi und jagt die Katzen, die den Dschungel durchstreifen. Ihre flauschigen Felle werden uns zur Wahrheit führen!", sourceObjective = "Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.", progress = "Achtet darauf, dass die Reagenzien ganz besonders kuschelig sind, {name}. Kratzende Reagenzien reichen einfach nicht.", completion = "<Flem streicht über die Felle und lächelt versonnen.>\n\nAusgezeichnete Arbeit, {name}! Diese Reagenzien werden perfekte Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26435] = { id = 26435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin ein gewaltiger Lügner und Betrüger", description = "Ich habe keine Ahnung, was dieses Artefakt ist. Ich habe auch keine Ahnung, wo ich überhaupt ANFANGEN sollte, herauszufinden, was das ist.\n\nUm genau zu sein habe ich keine Ahnung, warum überhaupt jemand auf die Idee kam, dass ICH in der Lage sein könnte, es zu identifizieren.\n\nIch habe um Wasser gebeten, weil ich Durst hatte. Ich habe um Juwelen und Felle gebeten... nun, für meine Freundin.\n\nHoffentlich kann ich Euch wenigstens die richtige Richtung weisen. Garley Lichtreiter in Beutebucht ist ein Mitglied der Archäologischen Akademie und könnte möglicherweise hilfreicher sein, als ich es war.\n\nTut mir leid.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Garley Lichtreiter in Beutebucht am Schlingendornkap.", progress = "Ja, {race}? Ich bin sehr beschäftigt.", completion = "Faszinierend!\n\nIch brauche etwas Zeit, um mir das genauer anzusehen. Warum seht Ihr Euch nicht ein wenig in Beutebucht um und kommt später wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26436] = { id = 26436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwurzelt", description = "Eure Absichten scheinen ehrlich zu sein.\n\nIch werde den anderen Steinlords von meinem vorsichtigen Vertrauen erzählen.\n\nDanach sollten sie gewillt sein, mit Euch zu sprechen.\n\nUnd was noch wichtiger ist, sie sollten gewillt sein, zuzuhören.\n\nIhre Gunst zu erlangen, wird Zeit in Anspruch nehmen. Die Gunst der Steinmutter zu erringen, wird wohl noch länger dauern. Zeit ist ein wirksames Geschenk, geht also großzügig damit um.\n\nBei den Berstenden Säulen, weit im Nordwesten, findet ihr Kor den Unbeweglichen. Er hat ein ausgeglichenes Gemüt. Aufgrund seiner Lage ist er auf Hilfe von anderen angewiesen.\n\nGeht zu ihm.", sourceObjective = "Findet Kor den Unbeweglichen bei den Berstenden Säulen.", completion = "Diamant sagt, dass man Euch vertrauen kann. Diamant ist geduldig und weise, also werde ich Euch die Möglichkeit geben, Euch zu beweisen.\n\nWie es der Zufall will, könnte ich Hilfe von jemandem gebrauchen, der etwas… beweglicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26437] = { id = 26437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallklar", description = "Bei den Berstenden Säulen befinden sich Kristalle. Weiße, kalkhaltige Kristalle. Wir können diese Kristalle in unsere Haut absorbieren. Um uns zu reinigen. Uns zu läutern.\n\nIch wandle nicht mehr zwischen den Steinen. Ich bin eins mit der Erde. Das hat viele Vorteile, doch ich kann mir die Kristalle nicht mehr selbst beschaffen.\n\nBringt mir die Kristalle, so dass ich stärker werde. Nehmt sie den Felsklauen weg. Nehmt sie meinen Söhnen weg. Diese Ehre sollte nur mir vorbehalten sein.", sourceObjective = "Sammelt 8 kalkhaltige Kristallformationen.", progress = "Habt Ihr mir den Gefallen getan, um den ich Euch bat? Habt Ihr mir die Kristalle gebracht?", completion = "Ahh… erfrischend. Vielen Dank, Fleischling.", sourceObjectiveStatus = "unverified-source-field" }
quests[26438] = { id = 26438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intervention", description = "Die Felsklauen sind wahnsinnig vor Hunger. Einst gruben sie mit Bedacht und Mäßigung. Jetzt ist ihr Hunger jedoch unersättlich. Sie sind blutrünstig und gewalttätig geworden.\n\nSie haben sich gegen meine Söhne gewandt. Sie überwältigen sie. Tötet sie. Es muss aufhören.\n\nTötet die Felsklauen. Sie erfüllen keinen Zweck auf dieser Welt. Niemand wird sie vermissen. Rettet meine Söhne. Tötet alle Felsklauen, die Ihr finden könnt.", sourceObjective = "Tötet 12 Jaspisspitzenfelsklauen.", completion = "Ihr habt Euch als nützlich erwiesen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26439] = { id = 26439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teile zusammenfügen", description = "{race}. Wenn Ihr den Steinlords dient, gibt es jemanden, der Euch vielleicht helfen wird.\n\nHaltet nach den Steingebundenen Ausschau. Sie schlafen überall bei den Berstenden Säulen verteilt. Es sollte kein Problem sein, sie aufzufordern, sich neu zu binden und Euch gegen die Felsklauen zu unterstützen.", sourceObjective = "Helft 6 schlafenden steingebundenen Elementaren dabei, sich neu zusammenzufügen.", completion = "Danke, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26440] = { id = 26440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänglich", description = "<Ein winziger Elementar scheint Gefallen an Euch gefunden zu haben.>\n\nKiris… Krissi… Kristall? <Kieselchen schaut Euch erwartungsvoll an.>\n\n<Erst jetzt bemerkt Ihr die riesige Kristallformation in der Mitte der Berstenden Säulen. Vielleicht solltet Ihr ihn dorthin bringen?>", sourceObjective = "Bringt Kieselchen zur großen Kristallformation in den Berstenden Säulen.", progress = "<Kieselchen schaut Euch erwartungsvoll an.>", completion = "<Die Steine in Kieselchens Körper springen fröhlich auf und ab. Er ist offenbar sehr dankbar.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26441] = { id = 26441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So groß, so rund…", description = "<Kieselchen schaut sich um und scheint über etwas ganz aufgeregt zu sein. Nach ein paar Sekunden der Verwirrung bleibt er stehen und starrt Euch mit großen leuchtenden Edelsteinaugen an.>\n\nHug-nrig… Hungrig…\n\n<So sehr Ihr es auch versucht, gegen diesen Blick seid Ihr einfach machtlos. Vielleicht weiß Kor ja, was Mini-Elementare gerne essen.>", sourceObjective = "Sprecht mit Kor, um herauszufinden, was Kieselchen gerne isst.", completion = "Habt Ihr einen neuen Freund gewonnen?\n\nSeid Ihr sicher, dass Ihr ihn füttern wollt? Er könnte sich an Euch gewöhnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26442] = { id = 26442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felshummer", description = "Wenn ich meine Henkersmahlzeit selbst aussuchen könnte, dann würde ich mich auf jeden Fall für frische Hummerschwänze entscheiden. Irgendetwas an dem leckeren Krustentier ist unwiderstehlich! Vor Kurzem haben wir begonnen, Hummer hier in Sturmwind zu fangen. Würde es Euch etwas ausmachen, hinauszugehen und die Fallen für mich zu überprüfen?\n\nEins noch... Passt auf die Haie auf. Die können ziemlich grausam sein.", sourceObjective = "Sammelt 6 Felshummer aus den Käfigen unter den Docks im Hafen von Sturmwind auf. Achtet auf Haie!", progress = "Anscheinend seid Ihr den Haien erfolgreich ausgewichen. Waren Hummer in den Fallen?", completion = "Die Fallen funktionieren anscheinend! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26443] = { id = 26443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallengelassen, das erstaunlicherweise in Gemeinsprache verfasst ist! Die darin erwähnten Namen, Diathorus und Gorgannon, gehören zwei berüchtigten Schreckenslords, die in dieser Gegend die Dämonen kontrollieren.\n\nDie Pläne beschreiben genau die Vorbereitungen auf einen Angriff der Dämonen auf Waldeslied im Norden. Das ist der Ort, an dem eine neue Siedlung der Draenei erbaut wird. \n\nMöglicherweise interessiert sich Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans hierfür?", sourceObjective = "Liefert die teuflischen Pläne bei Verteidiger Vedaar am Holzfällerlager des Kriegshymnenklans in Eschental ab.", progress = "Was habt Ihr da, mein Herr?", completion = "Bei den sieben Kristallen von Ata'mal, das darf nicht sein! Sie haben vor, Waldeslied anzugreifen?!\n\nNicht, solange ich Dienst habe!\n\n<Verteidiger Vedaar zerknüllt die von Dämonen gekritzelten Pläne in seiner Faust.>\n\nNein. Das werden wir nicht zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26444] = { id = 26444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Ich werde ihre Existenz in dieser Welt nicht dulden! Die Brennende Legion hat unser Volk so gut wie zerstört, und wir haben uns zurückgezogen, um in einer neuen Welt eine neue Heimat zu erschaffen. Dann kehrten sie zurück, und wir haben uns erneut zurückgezogen, wieder und wieder.\n\nNicht länger!\n\nIm Süden und im Westen befinden sich noch Überreste der Legion. Die Regionen heißen Dämonenhügel, Dämonensturz und Dämonenstieg. Das ist von der Streitmacht, die einst in diese Welt einfiel, noch übrig.\n\nGeht und vernichtet so viele von ihnen, wie möglich, bevor es zu spät ist!", sourceObjective = "Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.", completion = "Ihr habt meinen Respekt und meinen Dank, {class}. Vielleicht können wir jetzt hier eine neue Heimat schaffen, ohne uns um die Brennende Legion Sorgen machen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26445] = { id = 26445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie sind Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz. Um dort hinaufzugelangen, sucht nach einem Stieg in der Nähe des Denkmals für Grom Höllschrei.\n\nBringt mir ihre Waffen.", sourceObjective = "Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", progress = "Unsere Nachtelfenspione berichten, dass die Vorbereitungen für den Angriff fast abgeschlossen sind. Diese Schreckenslords müssen schnell sterben, {name}!", completion = "Die Brennende Legion wird das Eschental nie wieder bedrohen! Ihr habt uns vor einem Kampf gerettet, den wir wahrscheinlich verloren hätten, {class}.\n\nIch danke Euch, {name}, und die tiefste Dankbarkeit der Hand von Argus. Es ehrt mich, Euch auf unserer Seite zu wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26446] = { id = 26446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Dämonenhügels", description = "Kleines Wesen. Im Südwesten gibt es ein Gebiet im Nachtweisenwald, das seit kurzer Zeit Dämonenhügel genannt wird. Es ist sehr traurig zu sehen, wie die Dämonen auf ihm herumkrabbeln und ihre Verderbnis verbreiten.\n\nIch habe ein paar Samen, die ich für eine solche Gelegenheit aufgehoben habe. Bringt sie zum Dämonenhügel und pflanzt sie in fruchtbare Erdhaufen.", sourceObjective = "Pflanzt 8 Baumsetzlinge in die fruchtbaren Erdhaufen.", completion = "Gut. Auch wenn es vielleicht lange Zeit dauern mag, bis aus den Setzlingen Urtume werden, werden sie uns dann im Kampf gegen die Feinde des Eschentals helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26447] = { id = 26447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflische Pläne", description = "Der Dämon hat dieses Pergament fallenlassen, welches überraschenderweise auf Orcisch geschrieben wurde! Darin werden Diathorus und Gorgannon erwähnt, zwei berüchtigte Schreckenslords, die die Dämonen in dieser Gegend anführen.\n\nDie Pläne enthalten genaue Vorbereitungen für einen dämonischen Angriff auf den Splitterholzposten im Nordwesten.\n\nIhr seid Euch sicher, dass Valusha im Splitterholzposten daran interessiert ist.", sourceObjective = "Bringt die teuflischen Pläne zu Valusha im Splitterholzposten im Eschental.", progress = "Was habt Ihr da, Bruder?", completion = "Schreckenslords! Sie planen uns hier am Splitterholzposten anzugreifen?!\n\nNicht solange ich noch am Leben bin!\n\n<Valusha zerknüllt die Pläne mit dem Dämonengekritzel in ihrer Faust.>\n\nNein. Wir werden das nicht zulassen. Sie sind ein Schandfleck in unserer Welt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26448] = { id = 26448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Legion", description = "Die Überreste der Brennenden Legion sind uns schon zu lang ein Dorn im Auge!\n\nEs ist an der Zeit, sie dafür bezahlen zu lassen!\n\nDie Dämonen greifen von den Gebieten im Osten, die als Dämonenhügel, Dämonensturz und Dämonenstieg bekannt sind, an.\n\nGeht und zerstört so viele von ihnen, wie Ihr könnt und erlangt Ruhm für Euch selbst und für die Horde!", sourceObjective = "Tötet 15 beliebige Dämonen am Dämonenhügel, am Dämonensturz und am Dämonenstieg.", completion = "So ist es schon besser! Nichts ist so gut, wie unsere Welt von einem Dämonen zu befreien. Und sie sind würdige Gegner, nicht so wie die schwachen Völker der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26449] = { id = 26449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nie wieder!", description = "{name}, es ist Eure Aufgabe dafür zu sorgen, dass dieser Angriff der Brennenden Legion niemals stattfindet. Geht und erschlagt diese Schreckenslords. Ohne sie ist der Rest der Dämonen nur ein Haufen geistloser Untiere.\n\nIhr findet Gorgannon im Dämonensturz südlich hinter dem Dämonenhügel in der Nähe des schwebenden Speers von Mannoroth.\n\nDiathorus der Sucher lebt irgendwo im Grabhügel auf dem Dämonensturz.\n\nKehrt mit ihren Waffen als Beweis Eurer Taten zurück.", sourceObjective = "Besorgt Gorgannons flammende Klinge und den Teufelsspeer des Suchers.", progress = "Diese Schreckenslords müssen bald sterben, {name}!", completion = "Nie wieder wird die Brennende Legion die Orcs oder ein anderes Volk der Horde versklaven! Ihr habt tapfer gekämpft, {class}!\n\nDas wahre Herz der Horde schlägt in Euch! Ihr bringt uns sehr viel Ehre!", sourceObjectiveStatus = "unverified-source-field" }
quests[26450] = { id = 26450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn sie sie einfach herumliegen lassen ...", description = "Mir kam gerade ein Gedanke, {name}. Diese Naga haben mehr als nur Schilfrohr dort unten. Sie haben kleine Statuen auf ihren Schreinen im Sand unter den Bäumen herumliegen. Sie scheinen sie nicht zu benutzen.\n\nIch könnte diese Statuen gebrauchen. Ich könnte... sie überall im Lager aufstellen, damit es sich hier etwas heimeliger anfühlt. Alles ist besser als eine blutige Dinosaurierleichenpumpe. Ich könnte sie als Andenken verkaufen.\n\nIch könnte sie an die Naga zurückverkaufen!\n\nWarum holt Ihr nicht ein paar, während ich mir etwas ausdenke.", sourceObjective = "Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.", progress = "Lasst mal sehen!", completion = "Gute Arbeit, {name}. Jetzt muss ich mich nur noch entscheiden, was ich damit mache...", sourceObjectiveStatus = "unverified-source-field" }
quests[26451] = { id = 26451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashiherausforderung: Jeder gegen jeden in der Arena", description = "Die Arena ist ein Kampfort wie kein anderer. Darin habt Ihr keine Freunde. Bündnisse, die eingegangen werden, sind kurzlebig und Eure Verbündeten können sich von einem Augenblick zum anderen gegen Euch wenden. Horde gegen Allianz, Allianz gegen Allianz, Horde gegen Horde - alles ist möglich.\n\nNehmt diese Schlachtstandarte, {race}, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.\n\nSeid jederzeit wachsam, {race}. In der Arena der Gurubashi ist alles möglich.", sourceObjective = "Stellt die Herausforderungsflagge der Gurubashi im Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.", progress = "Bevor Ihr mich erneut ansprecht, sollte ein wenig mehr Blut auf Eurer Rüstung zu sehen sein.", completion = "Gut gemacht, {race}! Habt Ihr es gespürt? Den Rausch des Nahkampfs? Das wahre Risiko des Kampfes, jeder gegen jeden?\n\nDa heute Euer erster Tag hier ist, dürft Ihr noch einen Wettbewerb für eine weitere Belohnung austragen. Wenn Ihr in Zukunft zurückkehrt, dürft Ihr einmal am Tag antreten. Eure Belohnungen werden natürlich immer besser, je stärker Ihr werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26452] = { id = 26452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashiherausforderung", description = "Ihr seid zurückgekehrt, {race}. Das bedeutet, dass Ihr den Ruf der Arena erneut verspürt habt. Also gut.\n\nNehmt diese Schlachtstandarte, {race}, und platziert sie auf dem Arenaboden. Besiegt den herbeigerufenen Kämpfer und kehrt zu mir zurück.\n\nSeid jederzeit wachsam, {race}. In der Arena der Gurubashi ist alles möglich.", sourceObjective = "Stellt die Herausforderungsflagge der Gurubashi in dem Kampfring ab und besiegt dann den Herausforderer der Arena der Gurubashi.", completion = "Gut gemacht, {race}! Ich freue mich darauf, Euch bald wieder kämpfen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26453] = { id = 26453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Meine Leute haben im Osten des Eschentals mithilfe der Kaldorei eine wichtige Entdeckung gemacht.\n\nUnter der Aufsicht von Architekt Nemos und Verteidiger Vedaar erneuern sie einen alten elfischen Außenposten. Der Wiederaufbau wird nicht leicht werden, {name}, denn sie stehen vielen Herausforderungen und Feinden gegenüber. Ich weiß, dass Architekt Nemos und seine Landsleute in Waldeslied jede Hilfe, die sie bekommen können, zu schätzen wissen, und er hat mich gebeten, <jeden Mann, der/jede Frau> die; Interesse hat, zu ihm zu schicken.\n\nSprecht mich erneut an und ich werde dafür sorgen, dass Ihr schnell zu ihrer Stellung gebracht werdet.", sourceObjective = "Geht nach Waldeslied im Eschental und sprecht mit Architekt Nemos.\n\nVerteidigerin Palanaar kann Euch ein Reittier anbieten, um schneller dorthin zu gelangen.", completion = "Es ist schön, einen Neuankömmling hier in Waldeslied begrüßen zu dürfen.\n\nVerteidigerin Palanaar sendet so viel Hilfe, wie sie aufbringen kann, und jede helfende Hand ist willkommen.\n\nSchaut Euch um, {class}. Es ist vielleicht noch nicht viel, aber mit der Zeit und der Hilfe unserer Nachtelfenverbündeten werden wir eine Siedlung errichten, die es wert ist, Zuhause genannt zu werden. Es gibt hier viel zu tun, und für jede Hilfe, die Ihr uns leisten könnt, sind wir sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26454] = { id = 26454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schändliche Verschwendung", description = "Willkommen in Waldeslied, {class}. Wo Ihr jetzt noch Zelte seht, werden einst Gebäude stehen, aber dieses Ziel erfordert einen ständigen Nachschub an Baumaterial. Ich bringe es nicht übers Herz, unseren Arbeitern zu befehlen, die uralten Bäume dieses Hains zu fällen, aber unsere Nachbarn im Süden und Westen haben keine so große Ehrfurcht vor dem Wald.\n\nWir werden das verdorbene Holz aus der Festung der Satyrn im Westen zurückfordern. Bringt das Holz zu Knorre im Holzfällerlager des Kriegshymnenklans. Er ist ein Urtum, der es für unsere Zwecke reinigen wird.", sourceObjective = "Sammelt 5 Stück verdorbenes Satyrnaarholz.", progress = "<Das Urtum knarrt, als es sich zu Euch umdreht>\n\nArchitekt Nemos sagte, Ihr brächtet Holz, das Ihr aus dem verdorbenen Satyrnaar errettet habt.", completion = "Holz, das von widerwärtiger Dämonenmagie verzerrt wurde, ist für die Draenei in Waldeslied nutzlos. Nichts Vernünftiges lässt sich daraus erbauen, doch ich werde es reinigen und Architekt Nemos zurückgeben, auf dass er und seine Leute es benutzen können.\n\nSo wird die Tragödie doch ein gutes Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26455] = { id = 26455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kelch", description = "Das Gebiet westlich von hier, das nun Satyrnaar heißt, war einst ein bedeutender Schrein meines Volkes. Dort befand sich ein Relikt von unschätzbarem Wert, Elunes Kelch, der den Hütern des Schreins von den Priestern Elunes anvertraut wurde. Einst reisten Pilger zu dem Schrein, um die heilenden Kräfte, die dem Kelch nachgesagt wurden, am eigenen Leib zu erfahren.\n\nVielleicht sind diese Geschichten nur Ammenmärchen, aber wenn nur ein Körnchen Wahrheit in ihnen steckt, könnte der Kelch vielleicht der Schlüssel zur Wiederherstellung unseres leidenden Waldes sein. Ich muss es wissen, {name}.", sourceObjective = "Bringt Elunes Kelch in Euren Besitz.", progress = "Könnt Ihr ihn fühlen, {name}, den Hauch von Verderbnis im Wind? Wenn wir nichts tun, wird er noch stärker werden. Deshalb suche ich Elunes Kelch. Konntet Ihr ihn finden?", completion = "Ausgezeichnete Arbeit, {name}. Es schlummert eine deutliche Macht in ihm, die nicht einmal die Verderbnis der Satyrn trüben kann.\n\nSeht Ihr, wie er immer noch glänzt, nach all den Jahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[26456] = { id = 26456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht von der Nordfront", description = "Die Schlacht gegen das Holzfällerlager des Kriegshymnenklans wird nicht nur vom Rajenbaumturm aus geführt, {name}. Eine beträchtliche Anzahl von Schildwachen der Silberschwingen hat sich im Hain der Silberschwingen, in der Nähe der Grenze zum Brachland, postiert. Schildwache Weltensang ist für unsere Bemühungen gegen die, die unser Land zerstören wollen, verantwortlich.\n\nIch bin mit meinem Bericht an Schildwache Weltensang etwas spät dran, möchte aber den Turm nur ungern unbewacht lassen. Wenn Eure Reisen Euch in die Nähe des Silberschwingenhains bringen, könntet Ihr dann meinen Bericht abgeben?", sourceObjective = "Bringt Schildwache Melyrias Bericht zu Schildwache Weltensang im Hain der Silberschwingen im Eschental.", progress = "Was habt Ihr da, {class}?", completion = "Vielen Dank für diesen Bericht, {name}. Nach dem, was Schildwache Melyria schreibt, scheint es, als wären unsere schlimmsten Befürchtungen wahr geworden. Mit jedem Fortschritt, den wir machen, scheint die Horde umso entschlossener, so viel Schaden wie möglich anzurichten.\n\nWir können es uns nicht leisten, klein beizugeben. Das Schicksal des Landes unserer Vorfahren steht auf dem Spiel. Wenn wir mehr von Eurer Sorte an der Front hätten, könnten wir sicher triumphieren.\n\nWerdet Ihr Euch unserem Kampf anschließen? Eine neue Front hat sich gerade im Süden in der Kriegshymnenschlucht gebildet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26457] = { id = 26457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agenten der Zerstörung", description = "Das Holzfällerlager des Kriegshymnenklans ist ein Schandfleck in unserer Landschaft. Wann immer wir Fortschritte dabei machen, ihre Arbeiten zu stoppen, befiehlt Vorarbeiter Gorthak seinen Holzarbeitern, ihre Anstrengungen noch zu verdoppeln!\n\nJetzt fällen die Orcs mehr Holz, als sie je verbrauchen können und lassen es verrotten, während ihre Klingen schon wieder in frisches Holz schlagen! Dies ist eine Beleidigung gegenüber allem, für das wir einstehen, {name}, und wir werden ihnen zeigen, dass wir uns eine weitere Zerstörung unseres Landes nicht gefallen lassen!\n\nGeht, und ruht nicht, bevor Vorarbeiter Gorthak und seine Lakaien tot sind!", sourceObjective = "Tötet Vorarbeiter Gorthak und 12 weitere, beliebige Mitglieder der Horde im Holzfällerlager des Kriegshymnenklans.", completion = "Endlich haben wir ein Zeichen gesetzt, das die Orcs nicht ignorieren können. Jeder Vorarbeiter oder Großknecht, der einen Fuß in das Lager setzt, um Gorthak zu ersetzen, wird meinen Zorn zu spüren bekommen!\n\nWir müssen unseren Vorteil ausnutzen, {name}, und nicht ruhen, bevor das Holzfällerlager des Kriegshymnenklans nichts mehr als eine weit entfernte Erinnerung ist und junge Bäume ihre Wurzeln in diesen Boden schlagen.\n\nWas sagtet Ihr noch gerade über Sprengstoff...?", sourceObjectiveStatus = "unverified-source-field" }
quests[26462] = { id = 26462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bösen Bruchhauer", description = "Die Trolle der Bruchhauer meinen etwas Besonderes zu sein, weil sie Teil der Horde sind. Da kann ich nur lachen!\n\nWisst Ihr, das wirklich Witzige ist, dass es egal ist, ob sie der Horde angehören oder nicht, ob sie ein Trollimperium besitzen oder die Brennende Legion selbst sind. Wir haben Trolle in diesen Ländern seit Urzeiten bekämpft.\n\nUm genau zu sein werde ich Euch dabei sogar helfen lassen, <Junge/Mädchen>! Nehmt Euch eine Waffe und begebt Euch zum Schlachtfeld, um unsere Jungs östlich von hier zu unterstützen.", sourceObjective = "Tötet 10 Pirscher der Bruchhauer oder Verhexer der Bruchhauer.", completion = "Nicht schlecht für einen {race} aus der Stadt. Nette Vorführung!", sourceObjectiveStatus = "unverified-source-field" }
quests[26463] = { id = 26463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Teronis", description = "Eine Freundin von mir aus Astranaar, Raene Wolfsläufer, hat mich gebeten, einen Kundschafter zum Falathimsee im Westen zu schicken. Teronis ist vor Tagen aufgebrochen, kurz bevor die Horde angegriffen hat.\n\nEr war auf der Suche nach einem Gegenstand, von dem er dachte, dass er die Furbolgangriffe auf unser Volk mildern könnte: eine Rute, die von einem mittlerweile toten, bösen Zauberer hergestellt worden ist.\n\nBevor er aufbrach, erwähnte er einen Edelstein für die Rute.\n\nLeider wissen wir, dass der See von einer bösen Macht heimgesucht wird. Bitte, {name}, macht meinen Freund ausfindig.", sourceObjective = "Sucht am Falathimsee im Eschental nach Teronis.", completion = "Teronis' Körper liegt zerschmettert auf einem kleinen Hügel neben dem Bewahrer.\n\nTiefe Schnitte ziehen sich kreuz und quer über seine Leiche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26464] = { id = 26464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Stein", description = "Während Ihr Teronis' Habseligkeiten durchstöbert, stoßt Ihr auf ein durchnässtes Tagebuch.\n\nIhr blättert schnell durch die letzten noch lesbaren Seiten und lest, dass Teronis erwähnt, wie er den Edelstein gefunden hat, ihn dann aber in der Umgebung des Falathimsees verloren hat.\n\nJetzt müsst Ihr nur noch eines tun: den Edelstein finden. Vielleicht haben ihn die Tentakel...", sourceObjective = "Findet den leuchtenden Edelstein.", progress = "Ah, willkommen zurück, {name}.", completion = "Wie schrecklich, {name}. Teronis ist tot?!\n\nIch werde ihn später betrauern, aber jetzt müssen wir uns zuerst auf unsere Aufgaben konzentrieren. Ich schicke ein paar der Schildwachen aus, um Teronis' Leiche herzubringen und dem Hüter beizustehen.\n\nIhr habt den Edelstein, den Teronis suchte? Er muss sofort nach Astranaar gebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26465] = { id = 26465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die antiken Statuetten", description = "Ich möchte Euch mit einer Aufgabe betrauen, {class}.\n\nIch war auf meinem Boot und dümpelte über die versunkenen Ruinen von Zoram, als Naga mich angriffen. Sie sprangen aus dem Wasser und griffen mit ihren Klauen nach mir! Ich flüchtete, und der Rest ist - wie man so schön sagt - Geschichte.\n\nIch bin eine Art Archäologe und ich versuche, die Artefakte der verlorenen Stadt wiederzufinden.\n\nWürdet Ihr Euch hinaus zum Zoramstrand im Südwesten begeben und alle antiken Statuetten, die Ihr finden könnt, bergen? Sie sind der Grund, dass ich den Gefahren des Zoramstrandes getrotzt habe.", sourceObjective = "Besorgt 10 antike Statuetten.", progress = "Habt Ihr viele Statuetten gefunden, {name}?", completion = "Das sind ja doch einige, die Ihr gefunden habt! Danke, {name}!\n\nDie alte Stadt Zoram birgt viele Geheimnisse, und diese Statuetten könnten der Schlüssel zu einigen davon sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26466] = { id = 26466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuzel", description = "Ich fürchte, die Geheimnisse der antiken Statuetten werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihren antiken Schlössern findet.\n\nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der Großen Zerschlagung unterging.\n\nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor Kurzem gefunden.\n\nRuuzel, ihre Anführerin, haust auf einer Insel am nördlichen Ende des Zoramstrands. Bitte, {name}, beschafft mir den Ring!", sourceObjective = "Nehmt den Ring von Zoram an Euch.", progress = "Es heißt, dass der Ring von Zoram der Schlüssel zu allen Schlössern der Stadt sei. Habt Ihr ihn, {name}?", completion = "Ihr habt den Ring gefunden! Danke, {name}.\n\nBitte nehmt das hier als Lohn und wisset, dass ich Eure heutige Tat nie vergessen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26467] = { id = 26467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elende Satyrn! Die Dryaden sind in Gefahr!", description = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein würden, aber das war vor zwei vollen Tagen!\n\n{name}, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordwesten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", sourceObjective = "Sucht in Xavian im Eschental nach Anilia.", completion = "Der klaffenden Wunde in ihrer Seite nach zu urteilen, steht Anilia an der Schwelle des Todes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26468] = { id = 26468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zweig des Cenarius", description = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", sourceObjective = "Erhaltet den Zweig des Cenarius.", progress = "Habt Ihr sie gefunden? Was hat Anilia gesagt? Wo ist sie?", completion = "Anilia ist tot? Nein... das kann nicht sein! Noch vor kurzem sind wir zusammen durch die Wälder getollt und haben gespielt.\n\nDiese Zeiten sind jetzt wohl vorbei...", sourceObjectiveStatus = "unverified-source-field" }
quests[26469] = { id = 26469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrn schlachten!", description = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.\n\nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", sourceObjective = "Erhaltet 16 Satyrhörner.", progress = "Bitte, helft mir Anilias Tod zu rächen.", completion = "Danke, {race}, Ihr seid sehr freundlich. Der Geist meiner Schwester ist dankbar für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26470] = { id = 26470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung des Mystralsees", description = "Wir hätten die Silberwindzuflucht ohne Weiteres gegen den Ansturm der Horde halten können, wenn sie uns nicht die Kontrolle über unsere Wasserelementarverteidiger im Mystralsee entrissen hätten.\n\nEiner ihrer Schamanen hat Tideress heraufbeschworen, einen alten, wütenden Wassergeist des Waldes, der unsere Elementare besudelt und gegen uns aufgebracht hat. Da sowohl der See als auch die Horde über uns hereingebrochen sind, hatten wir keine andere Wahl, als uns hierher zur Spitze zurückzuziehen.\n\nBegebt Euch nach Osten. Erobert den See zurück, sodass eine Chance besteht, dass wir eines Tages die Zuflucht wieder einnehmen können.", sourceObjective = "Tötet 12 beschmutzte Wasserelementare und Tideress.", completion = "Gut gemacht, {name}! Nun da die Ränge der beschmutzten Wasserelementare dezimiert sind und Tideress wieder in den See verbannt wurde, sollten wir einen Gegenangriff auf die Silberwindzuflucht starten können.\n\n\n\nSobald wir mit der Verteidigung der Spitze fertig sind....", sourceObjectiveStatus = "unverified-source-field" }
quests[26472] = { id = 26472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrsinnige Druiden", description = "Die Druiden sind tot. Ihre Anführer haben sie getötet - sie wurden von der Horde, die das Herz des Waldes verderben, in den Wahnsinn getrieben. Ich kann die Verderbnis sogar von hier spüren und wage es nicht, weiterzugehen.\n\nIch stehe zu sehr im Einklang mit Eschental und dem Herz des Waldes - aber Ihr... Ihr könntet in den Grabhügel hinabsteigen und das tun, was getan werden muss. Ich habe dort eine Spur für Euch gelegt.\n\nObwohl es mir das Herz zerreißt, muss ich Euch darum bitten, die einstmals großartigen Anführer der Druiden zur ewigen Ruhe zu betten: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", sourceObjective = "Tötet die irrsinnigen Druiden: Taneel Finsterwald, Uthil Mondweise und Mavoris Wolkenbruch.", completion = "Ruht in Frieden, meine Freunde.\n\n<Ihr könnt den Schmerz in den Katzenaugen des Druiden sehen.>\n\nIch fühlte, dass die Pein der Grabhügel von Dor'Danil nachließ und wusste, dass Ihr Euren Auftrag erfüllt hattet.\n\nWas Ihr tun musstet, war grausam, {name}, denn die Geister, die Ihr vernichten solltet, waren doch nur unschuldige Opfer der Bösartigkeit der Horde. Hoffen wir, dass auch die anderen wahnsinnigen Geister endlich Ruhe finden, da sie jetzt vernichtet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[26473] = { id = 26473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathranshaar", description = "In den alten Ruinen von Bathrans Schlupfwinkel, der sich auf der anderen Seite der Straße im Osten befindet, wächst eine Pflanze. Diese Pflanze heißt Bathranshaar und man sagt ihr nach, dass sie Leiden des Geistes heilen kann.\n\nJetzt erntet die Horde diese Pflanze für ihre eigenen, finsteren Pläne.\n\nIn Astranaar befindet sich ein krankes Kind. Wir glauben, dass seine Krankheit nicht nur körperlicher Natur ist. Ich habe meinem Herrn versprochen, dass ich helfen werde, ein Heilmittel zu suchen, aber ich bin kein Kämpfer. \n\nWürdet Ihr zu Bathrans Schlupfwinkel gehen und die Pflanzen sammeln?", sourceObjective = "Sammelt 8 Büschel Bathranshaar.", progress = "Habt Ihr Bathranshaar gesammelt, {name}? Die Gesundheit des Kindes schwindet mit jeder Stunde...", completion = "Ah, Ihr habt das Haar! Das ist ein guter erster Schritt. Wir werden noch weitere Zutaten benötigen, aber das Haar des gefallenen Urtums könnte die wichtigste sein.\n\nIch hoffe nur, dass die Verlassenen aus der Pflanze keine Waffe entwickeln. Wir haben einfach nicht genug Leute, um sie jetzt zu vertreiben, insbesondere, da Maestras Posten angegriffen wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[26474] = { id = 26474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orendils Heilmittel", description = "{name}, nun da es von Elunes gesegnetem Licht durchflutet wurde, glaube ich, dass das Gebräu dem kranken Kind helfen wird. Bitte bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Weißmond.\n\nUm nach Astranaar zu gelangen, folgt ihr der Straße nach Süden und dann nach Osten. Wenn Ihr aber schneller dorthin gelangen wollt, sprecht mit Schildwache Avana.", sourceObjective = "Bringt Orendils Heilung zu Pelturas Weißmond in Astranaar im Eschental.", progress = "Ich muss mich entschuldigen, aber ich habe jetzt keine Zeit, um zu plaudern. Meine Tochter Relara ist todkrank!", completion = "Das ist von Orendil?\n\nSeine Fertigkeiten in Kräuter- und Heilkunde sind enorm. Dieses Heilmittel gibt mir Hoffnung, dabei hatte ich schon fast aufgegeben...", sourceObjectiveStatus = "unverified-source-field" }
quests[26475] = { id = 26475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Träne", description = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.\n\nElunes Träne ist eine Gesteinsart, die nur an einem Ort vorkommt: den Überresten des Irissees, der durch den Ausbruch des Donnergipfels nordöstlich von Astranaar zerstört worden ist. Orendil sagte, der Stein könne Verderbnis wegwaschen.\n\nBitte, {name}, bringt mir eine Träne Elunes und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", sourceObjective = "Erhaltet eine Träne Elunes.", progress = "Habt Ihr die Überreste des Irissees gefunden, {name}? Habt Ihr die Träne?", completion = "Oh, Ihr habt sie gefunden! Merkwürdig...der Stein sieht irgendwie angelaufen aus. Ich werde die Träne in einen Eintopf geben und beten, dass meine Tochter davon geheilt wird.\n\nDanke! Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26476] = { id = 26476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryadenlieferung", description = "Ah, da seid Ihr ja, {name}. Ich habe mich in die Anmerkungen vertieft, die Teronis gemacht hat, und es sieht so aus, als ist Euer nächster Schritt, die Teile von Dartols Rute zu finden.\n\nIch würde zunächst nach Osten reisen, zum Rajenbaumturm.\n\nDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.\n\nBehaltet den Edelstein bei Euch - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", sourceObjective = "Liefert den leuchtenden Edelstein bei Shael'dryn beim Rajenbaumturm im Eschental ab.", progress = "Hallo. Wie geht es Euch?", completion = "Oh, Raene hat Euch geschickt? Dann muss es wohl wirklich dringlich sein.\n\nWie kann ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26477] = { id = 26477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht den Schaft", description = "Ich wünschte, Ihr hättet bessere Nachrichten.\n\nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.\n\nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in der es sich befindet.\n\nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald am Heulenden Tal. Wenn Ihr es gefunden habt, sucht nach einer kleinen Lichtung hinter dem Tunnel in diesem Tal. Die Truhe ist dort irgendwo versteckt.", sourceObjective = "Sucht den hölzernen Schlüssel und benutzt ihn, um den Eisenschaft von Dartols Rute zu finden.", progress = "Es bestürzt mich sehr, dass die Treants verderbt wurden. Ich wünschte, ich könnte mehr tun, um ihnen zu helfen.", completion = "Wie ich mich freue, dass Ihr zurück seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26478] = { id = 26478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich tot stellen", description = "Das letzte Stück der Rute ist im Besitz der Druiden der Klaue. Ich habe ihren Anführer, Oso Dornennarbe, gebeten, es mir auszuhändigen, aber er und seine Wächter hätten mich beinahe umgebracht! Offenbar hat die Verderbnis des Herzens des Waldes seitens der Horde auch die Druiden betroffen.\n\nAber ich habe eine Idee, wie Ihr in Osos Höhle gelangen und den Knauf an Euch nehmen könnt.\n\nSchon als kleiner Faun war ich immer ziemlich gut darin, mich tot zu stellen. Das funktioniert wunderbar gegen Bären! Ich kann es Euch beibringen! Geht nach Osten zum Schattenwinkel und wenn sie versuchen, Euch anzugreifen, probiert einfach meine Taktik aus.", sourceObjective = "Erhaltet das letzte Teil von Dartols Rute, den Eisenschwertknauf.", progress = "Habt Ihr das letzte Teil der Rute gefunden, {name}? Hat meine Taktik funktioniert?", completion = "Ihr habt das letzte Teil gefunden? Wie wunderbar für Euch... und für Raene.\n\nDann sollten wir beginnen, sie zu reparieren, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[26479] = { id = 26479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Raene", description = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertiggestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.\n\nSeid vorsichtig damit... ich spüre eine große Macht darin, zum Guten wie auch zum Bösen. Ich hoffe nur, dass Raene und Ihr wisst, was Ihr tut.\n\nViel Glück, {name}.", sourceObjective = "Liefert Dartols Rute bei Raene Wolfsläufer in Astranaar im Eschental ab.", progress = "Ja, {name}? Wie liefen Eure Bemühungen?", completion = "Ihr habt die Rute wieder zusammengesetzt, die Teronis finden wollte? Wie schön, das zu hören.\n\nShael'dryns Hilfe war unentbehrlich. Teronis wäre stolz gewesen, wenn er gesehen hätte, dass seine Aufgabe selbst nach seinem tragischen Ende noch fortgeführt wurde.\n\n<Raene betrachtet die wiederhergestellte Rute mit Anerkennung und in ihren Augen spiegeln sich die vielen Gedanken, die in ihr vorgehen.>\n\nDie Zeit ist gekommen, ihre Macht gegen die Feinde des Eschentals einzusetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26480] = { id = 26480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartols Rute", description = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.\n\nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen, vermutlich die eines Furbolgs.\n\nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der noch unverderbt war.\n\nIch würde meine Suche bei dem Furbolg beginnen, der als Krolg bekannt ist. Sucht nach seiner Hütte südöstlich vom Mystralsee.", sourceObjective = "Benutzt Dartols Rute, um mit Krolg bei Krolgs Hütte im Eschental kommunizieren zu können.\n\nBereitgestellter Gegenstand:", completion = "Ja, ja... du erscheinst als einer meiner Art, aber mich kümmert nicht, was du in Wirklichkeit bist, solange du den Furbolgs helfen kannst.\n\nDie Nachtelfen und jetzt auch die Orcs haben meinem Volk viele Gräuel angetan.\n\nVerderbnis fließt durch unsere Adern, Verderbnis, die von den überheblichen Nachtelfen und den kriegerischen Orcs über uns gebracht wurde. Sie sind diejenigen, die das unserem Volk angetan haben... Sie sind diejenigen, denen ich die Schuld dafür gebe, dass mein Stamm mich verstoßen hat.\n\nBei Nacht kann ich noch immer die Lagerfeuer in der Dunkelheit brennen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26481] = { id = 26481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Verzierung", description = "Ich bin mir sicher, dass der seit langem tote Zauberer Dartol diese Rute dazu benutzen wollte, uns zu unterwerfen und zu zerstören, genauso wie es die Nachtelfen und Orcs versucht haben. Jetzt aber werden wir dieses Ding einem unvorhergesehenen Zweck zuführen.\n\nRan Blutreißer ist König über alle Furbolgs im Eschental. Sein Stamm, die Blutreißer, sind am mächtigsten und grenzen sich in einem Lager im Osten ab.\n\nTötet sie alle und bringt mir seinen Schädel. Wollen wir doch einmal sehen, ob wir nicht einen guten Verwendungszweck dafür finden können.", sourceObjective = "Erhaltet Ran Blutreißers Schädel und Dartols Rute.", progress = "Habt Ihr Ran schon erschlagen, Freund? Wir müssen seinen Schädel haben, wenn mein Volk frei sein soll.", completion = "Das habt Ihr gut gemacht, mein Freund.\n\nSchnell jetzt, gebt mir Rans Schädel. Solange noch seine Essenz ihn besudelt, können wir ihn an Dartols Rute befestigen und Euch die Macht verleihen, meine Brüder zu beeinflussen und sie vom Bösen zu befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[26482] = { id = 26482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wahre Macht der Rute", description = "Nehmt jetzt die Rute und sprecht, während Ihr unter ihrem Effekt steht, mit meinem Bruder Ota Wen.\n\nOta ist bei den anderen Furbolgs, die von den Orcs gefangen genommen und in den riesigen Käfig nördlich der Silberwindzuflucht gesperrt worden sind. Die Rute wird es Euch erlauben, Ota und die anderen Furbolgs dazu zu bringen, sich gegen die Horde aufzulehnen.\n\nDanach dürft Ihr Eures Weges ziehen. Wisst nur, dass Ihr mit Euren Taten einen neuen Freund gefunden habt.", sourceObjective = "Benutzt Dartols Rute und sprecht mit Ota Wen. Überzeugt ihn, sich gegen die Unterdrücker der Horde aufzulehnen. Bringt dann Dartols Rute zu Raene Wolfsläufer.", progress = "Ihr seid zurück, {name}. Was ist das dort an der Spitze der Rute? Ein Schädel?", completion = "Ihr habt also den Schädel des Furbolgkönigs benutzt, um die Macht der Rute zu verändern? Ihr habt dann diese Macht benutzt, um die gefangenen Furbolgs zur Revolte zu bewegen und die Horde in der Silberwindzuflucht anzugreifen?\n\nIch bin mit Euren Fähigkeiten mehr als zufrieden und beeindruckt, {name}. Die Schildwachen können Euch nicht genug danken. Es sollte nun einfach sein, die Orcs hinwegzufegen und die Zuflucht zurückzuerobern!\n\nTeronis wäre stolz. Ihr habt meinen größten Respekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26483] = { id = 26483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'dranda", description = "So viel Spaß es ja auch macht, die Trolle auf die Hörner zu nehmen, wir haben hier unten noch anders zu tun. Es wäre doch schöner, diesen Kampf endlich zu beenden, nicht wahr?\n\nIhr Kommandant, Gan'dranda, sitzt zwischen den eingestürzten Mauern im Südosten des Schlachtfelds. Unsere Jungs sind zum größten Teil unabkömmlich, also möchte ich, dass Ihr Euch dort hinschleicht und Gan'dranda beseitigt. Wenn sie dort <einen/eine:r> {race} über die Leiche ihres größten Helden gebeugt stehen sehen, sollte ihnen das den Schneid abkaufen.", sourceObjective = "Tötet Gan'dranda.", completion = "Na, das höre ich doch gerne! So ist's recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26484] = { id = 26484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Steinruh", description = "Die Irdenen und die Steintroggs haben vor mehr als fünfzehntausend Jahren einen Weg durch Uldum nach Tiefenheim gefunden. Seitdem befinden sie sich im Krieg.\n\nWenn wir das mittlere Fragment der Weltensäule wiedererlangen wollen, muss der Steinvater gerettet werden.\n\nBitte geht nach Steinruh und tut alles, was in Eurer Macht steht, um den Irdenen im Kampf gegen die Steintroggs zu helfen.\n\nIhr seid unsere größte Hoffnung, {name}.", sourceObjective = "Sprecht mit Spalt Steinbrecher in Steinruh in Tiefenheim.", completion = "Der Sohn des Steinvaters, Flint, hat Euch geschickt? Keine Zeit zu reden.\n\nWir müssen verhindern, dass sich eine zweite Front in dieser Schlacht aufbaut!", sourceObjectiveStatus = "unverified-source-field" }
quests[26485] = { id = 26485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnappkiefer, Bursche!", description = "Ich habe mir vorgenommen, für diese lästigen Trolle etwas ganz Besonderes zusammenzubrauen. Ja, ich sagte für sie... ein Gebräu, das sie niemals vergessen werden! Nach dem Genuss dieses Gebräus werden sie ihre Hauer aus den Abhängen sammeln können.\n\nEinige Zutaten weiche ich hier bereits ein, aber ich könnte Hilfe dabei gebrauchen, noch mehr zu beschaffen. Am Fuße der Aussichtsklippen im Osten in der Nähe des Ufers sind eine ganze Menge Schnappkiefer. Ich brauche frische, intakte Muskelmägen für mein Kawummbräu.", sourceObjective = "Beschafft 8 Schnappkiefermuskelmägen von Salzwasserschnappkiefern", progress = "Habt Ihr die Mägen?", completion = "Ah, schön frisch. Ich werde damit anfangen, während Ihr mir noch ein paar Sachen besorgt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26486] = { id = 26486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "99 Flaschen Wein am Strand", description = "Ich weiß ja, dass hier ein kleiner Kampf tobt, aber unten an diesen Aussichtsklippen sind überall Flaschen verteilt, die sehr verführerisch aussehen. Ich kann nicht zulassen, dass so ein gutes Tröpfchen der Horde in die Finger fällt!\n\nWenn Ihr zufällig dort vorbeikommt, dann sammelt die Flaschen für mich ein und bringt sie her. Ich werde Euch dafür bezahlen, als hättet Ihr sie selbst abgefüllt.", sourceObjective = "Sammelt 12 Flaschen mit Pupellyverbos' Portwein.", progress = "12 sollten reichen, oder?", completion = "Was für ein gutes Zeug! Wir können doch nicht zulassen, dass irgendwelche Trolle oder Goblins sich ein Schlückchen davon genehmigen, oder?\n\nVielleicht kann ich ein bisschen davon in meinem nächsten Gebräu verarbeiten…", sourceObjectiveStatus = "unverified-source-field" }
quests[26487] = { id = 26487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelweise Akiris", description = "Es ist nicht einfach, eine Kombination aus 5-Sterne-Exotikhotel und Verwertungsanlage für Dschungelmaterial zu führen! Zumindest wäre es nicht einfach, wenn ich nicht das Organisationstalent der persönlichen Assistentin eines Handelsprinzen hätte!\n\nDer erste Trick ist, mehrere Dinge auf einmal zu erledigen. Zum Beispiel: Die Forscher der Naga im Süden tragen wertvolles Seeschilf bei sich, Akiris. Wir können dieses Schilf an unsere Kunden in Übersee verkaufen und gleichzeitig die Matratzen unserer Kunden damit polstern! Wenn ich so darüber nachdenke, könnten wir es sicher auch für andere Zwecke verwenden.", sourceObjective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", progress = "Mal sehen… Wir brauchen ein paar Gewehre für unsere Naturwanderungen, Ruderboote für unseren Tagesausflug zum Bohrturm und…\n\nOh, Ihr seid schon zurück?", completion = "He, he! Nicht übel, gar nicht übel! Ihr könntet eine Zukunft im Beschaffungswesen haben. Oder im Hotelmanagement.", sourceObjectiveStatus = "unverified-source-field" }
quests[26488] = { id = 26488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Schluck", description = "Arnold und ich haben uns immer am Burggraben im Tal der Helden ausgeruht. Eines Tages habe ich mein Medaillon am See verloren und habe es nie wiedergefunden. Es gibt Gerüchte, dass riesige königliche Seeteufel in dem Burggraben leben. Diese Fische fressen einfach alles! Ich weiß, es hat nicht besonders viel Aussicht auf Erfolg, aber glaubt Ihr, Ihr könntet ein paar Seeteufel fangen und nach meinem Medaillon schauen?\n\nBitte gebt mir umgehend Bescheid, wenn Ihr es findet. Es bedeutet mir sehr viel.", sourceObjective = "Fischt einen königlichen Seeteufel aus dem Burggraben im Tal der Helden in Sturmwind. Wenn Ihr einen Seeteufel angelt, filetiert ihn und seht nach, ob er das Medaillon verschluckt hat.", progress = "Habt Ihr mein Medaillon gefunden?", completion = "Ihr habt es gefunden! Ich kann kaum glauben, dass es all die Jahre dort unten war! Ihr habt keine Ahnung, wie viel mir das bedeutet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26489] = { id = 26489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr hier?!", description = "Ja, wie kann ich Euch…\n\n<Sassy fällt die Kinnlade herunter.>\n\n{name}! Seid Ihr das wirklich?! Wie groß und stark Ihr geworden seid! Lasst mich mal Euren Bizeps fühlen.\n\nIch? Ich habe versucht, hier im Dschungel ein wenig Gold zu scheffeln. Wir sind hauptsächlich in der Materialbeschaffung tätig, aber auch im Tourismus.\n\nIch weiß, genial, oder?\n\nHe, hört mal. Da fällt mir gerade was ein. Die Forscher der Naga im Süden tragen wertvolles Akirisschilf bei sich, das wir verkaufen und gleichzeitig als Polsterung für unsere Gästematratzen verwenden können. Habt Ihr Lust, ein paar Naga zu töten? Es wäre ganz wie in alten Zeiten!", sourceObjective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26490] = { id = 26490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstklassiger Schleim", description = "Nicht viele Zwerge wissen das, aber um meinem Gebräu noch einen richtigen Schub zu verleihen, füge ich noch ein wenig von dem Schlamm hier aus der Gegend hinzu. Ja, von den riesigen, grünen, zwergenfressenden Schlammhaufen.\n\nDieses Gebräu braucht allerdings einen RIESIGEN Extraschub, also brauchen wir einen großen Schlamm! Im Lauerfels befindet sich die Mutter aller Schlamme, sie ist wirklich riesig... Wir nennen sie den Terrorhaufen.\n\nWenn Ihr das Zeug dazu habt, geht dorthin und bringt mir einen Brocken von dem Terrorklumpen!", sourceObjective = "Beschafft eine Terrorklumpenprobe vom Terrorklumpen.", progress = "Habt Ihr es?", completion = "Schaut Euch das an! Das wird der Mixtur richtig Dampf verleihen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26491] = { id = 26491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lauerfels aufräumen", description = "Vor Jahren gab es einmal eine Basis der Horde tief im Lauerfels. Sie ist seitdem verlassen, aber es handelt sich immer noch um ein wichtiges Gebiet, das es wert wäre, für unsere Verbündeten eingenommen zu werden.\n\nDas Problem ist, es ist voller zwergenfressender Schleime und Schlamme. Diese Dinger sind fast genauso eklig wie Trolle und bereiten uns dauernd Ärger.\n\nUnsere Jungs sind vollauf damit beschäftigt, gegen die Bruchhauer zu kämpfen, deshalb müsst Ihr nach Lauerfels gehen und dort für mich aufräumen.", sourceObjective = "Tötet 10 jadegrüne Schlamme.", completion = "Es ist schön, Euch wieder hier zu sehen... einschließlich aller Arme und Beine.", sourceObjectiveStatus = "unverified-source-field" }
quests[26492] = { id = 26492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauerfelsvorräte", description = "Ich hatte einen Cousin, der im Zweiten Krieg gekämpft hat! Er hat mir immer davon erzählt, dass sie einen Schlachtzug gegen Lauerfels geführt haben. Sie sind dort hineingestürmt und haben die Trolle wie Ratten aus ihrem Nest vertrieben. Sie haben sie den ganzen Weg bis nach Alterac gejagt!\n\nKurz darauf haben die Schleime Einzug gehalten, aber dort drin gibt es immer noch ganze Kisten voller Waren der Horde. Ich sage, wir lassen nicht zu, dass die Trolle sich das zurückholen!\n\nBringt mir einige Kisten vom Lauerfels im Nordwesten.", sourceObjective = "Sammelt 5 schlammbedeckte Vorratskisten ein.", progress = "Habt Ihr die Kisten?", completion = "Es sieht so aus, als ob darin noch alles gut ist! Hm... Ist das Bananenbrot? Das ist sogar noch frisch!\n\nHier mein Junge, nehmt Euch Euren Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[26493] = { id = 26493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand dort draußen will es haben", description = "Also, da Ihr ohnehin schon von der Erledigung der ganzen anderen Sachen schwitzt, dachte ich, Ihr könntet noch eine Aufgabe für mich erledigen. Das macht Euch doch nichts aus, oder?\n\nDas neueste Wissenschafts- und Explosionsjournal ist gerade aus Bilgewasserhafen eingetroffen und darin ist dieser Artikel über dieses heiße, neue Reagenz. Die Preise für dieses Reagenz schießen in den Himmel und wir haben beste Voraussetzungen, daraus Kapital zu schlagen!\n\n<Sassy beugt sich zu Euch und flüstert Euch die Einzelheiten ins Ohr.>\n\nVerstanden? Gut. Ihr findet die Basilisken in einer Höhle, weit im Osten.", sourceObjective = "Beschafft 7 Einheiten von Sassys Geheimzutat von Donnerschwanz- und Eisenkieferbasilisken in der Kristalladermine.", progress = "Ich hoffe, Ihr habt die Extraktionsmethode, die wir besprochen haben, angewendet.", completion = "Großartig! Die sehen... widerlich aus. Sie sind aber wahrscheinlich ziemlich wertvoll. Gehen wir und teilen sie auf. Ein paar für mich, ein paar für Jasper, ein paar für Chabal...", sourceObjectiveStatus = "unverified-source-field" }
quests[26494] = { id = 26494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mischmeister Jasper", description = "Würde es Euch etwas ausmachen, ein bisschen von dem Zeug hier Jasper zu bringen? Er ist bei den luxuriösen Wohnungen. Ich bin sicher, er wird dafür Verwendung haben.\n\nDanke, {name}!", sourceObjective = "Bringt Sassys Proben zu Mischmeister Jasper in Hartzangs Versteck.", progress = "Hey, ist das das Zeug? Aus der Zeitschrift?", completion = "Ich werde das erst einmal aufbewahren. Vielleicht können wir später herumexperimentieren.\n\n<Jasper schaut zu Euch hinüber.>\n\nJa, Ihr werdet reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26495] = { id = 26495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chabal", description = "Chabal, der Troll drüben am botanischen Garten/biologischen Waffenlabor, ist ein ganz besonderer Gast. Er ist ein Repräsentant der Zandalari-Trolle und hat eine weite Reise hinter sich, um bei uns zu sein.\n\n<Sassy packt einige der Gegenstände, die Ihr gesammelt habt, in ein kleines Paket und übergibt es Euch.>\n\nHier, gebt ihm das. Sagt ihm, dass die Zandalari in Hartzangs Versteck immer willkommen sind. Und erwähnt, dass Empfehlungen der Schlüssel zur Aufrechterhaltung unserer Geschäftsbeziehungen sind!", sourceObjective = "Bringt Sassys großzügige Gabe zu Chabal in Hartzangs Versteck.", progress = "Was soll das, {class}?", completion = "<Der Troll schaut in das Paket.>\n\nIch danke Euch.\n\nIch habe darauf gewartet, dass Ihr mich ansprecht, {race}. Ich habe festgestellt, dass Ihr der vielversprechendste {race} in dieser merkwürdigen Stadt seid. Ich habe eine Aufgabe für Euch, falls Ihr sie annehmen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26496] = { id = 26496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit den Blutfratzen", description = "Die Bruchhauer sind nicht der einzige Stamm schändlicher Trolle, um die wir uns kümmern müssen! Die Blutfratzen haben dieses Land seit Jahren aus ihrer Festung Jintha'Alor heraus verdorben.\n\nWir sitzen nicht länger am Nistgipfel und drehen Däumchen, falls es Euch entgangen sein sollte. Doran Stahlschwing führt den Sturmangriff gegen die Blutfratzen von einem Lager im Süden, das die Jungs gerade eingenommen haben. Sprecht mit ihm und schließt Euch dem Kampf an!", sourceObjective = "Findet Doran Stahlschwing bei Jintha'Alor im Hinterland.", completion = "Seid gegrüßt, {name}! Wir müssen viele Trolle töten und haben mehr als alle Hände voll damit zun!", sourceObjectiveStatus = "unverified-source-field" }
quests[26497] = { id = 26497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfratzenabschaum", description = "Die Blutfratzen sind ein anderer Stamm als die Bruchhauer, aber die Unterschiede sind kaum wahrnehmbar. Soweit es uns betrifft ist nur ein toter Troll eine guter Troll!\n\nAber täuscht Euch nicht, die Blutfratzen sind auch ohne die Ketten der Horde um ihre Hälse ausgesprochen bösartig. Sie werden das ganze Land vergiften, wenn wir uns nicht erheben und sie loswerden.\n\nIhr könnt mit ihren Hexendoktoren und Kopfjägern auf der unteren Etage beginnen. Sagt mir Bescheid, wenn Ihr eine ansehnliche Zahl von ihnen vernichtet habt.", sourceObjective = "Tötet 5 Hexendoktoren der Blutfratzen und 5 Kopfjäger der Blutfratzen in Jintha'Alor.", completion = "Ja, wir werden diese Trolle noch loswerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26498] = { id = 26498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Blutfratzen", description = "Wir machen gute Fortschritte. Rückt weiter vor und lasst nicht nach!\n\nDie Berserker der Blutfratzen kämpfen wie wilde Tiere und peitschen sich in einen wahren Blutrausch. Ihre Schattenzauberer rufen widerwärtige Geister aus dem Jenseits herbei. Das ist der Grund, warum wir uns dieser verdorbenen Kreaturen entledigen, {name}, vergesst das nicht.\n\nBegebt Euch auf die mittlere Stufe und tötet Berserker und Schattenzauberer!", sourceObjective = "Tötet 5 Berserker der Blutfratzen und 5 Schattenzauberer der Blutfratzen in Jintha'Alor.", completion = "Es wird nicht lange dauern, bis wir die einzigen Zwerge sind, die auf diesen Mauern noch atmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26499] = { id = 26499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Steinvaters", description = "Solange der Steinvater gefangen gehalten wird, ist die Moral meiner Truppen am Boden. Normalerweise nimmt es jeder von meinen Leuten mit mindestens fünf Steintroggs auf einmal auf. Aber jetzt…\n\nGeht hinaus auf das Feld um das Dorf herum. Stellt Steinvater Erzmantels Banner in der Nähe meiner Verteidiger auf. Schenkt ihnen seinen Segen und erinnert sie daran, wofür sie kämpfen.", sourceObjective = "Gewährt 12 Irdenen Verteidigern den Segen des Steinvaters", completion = "Ihr habt meinen Dank, {name}. Ihr habt das Blatt komplett gewendet. Das Schicksal dieser feigen Steintroggs ist besiegelt.\n\nJetzt müssen wir uns daran machen, Steinruh zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
